import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст Пресвятій Богородиці перед іконою «Боголюбська»","e":"Akathist to the Theotokos before her icon “Bogolyubovo”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Боголюби́вій Цари́це, превисшей вся́каго созда́нія, Ді́ві і Ма́тері Христа́ Бо́га, похва́льная воспису́єм Ті раби́ Твої́, Богоро́дице! Ти же, я́ко Боголюби́вая і Всеми́лостивая Ма́ти, благоізволившая яви́ти пресві́тлий Свой лик благові́рному на́шему кня́зю Андре́ю, от бід і скорбе́й сохрани́ ни і храм сей, да зове́м Ті:","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Ікос 1","ps":["А́нгелов превисшую вся Небе́сния Си́ли велича́ють Тя, Богоро́дицю Цари́цю, ми же грі́шнії на землі́, чу́дному Бо́жию о Тебі́ смотре́нію див'я́щеся, все́ю душе́ю, се́рдцем і устна́ми дерза́єм глаго́лати:","Ра́дуйся, Благослове́нная в жена́х Ді́во Благода́тная;","ра́дуйся, Всеви́шняго Ма́ти, Ду́ха Свята́го пребива́ніє.","Ра́дуйся, Цари́це Небесе́ і землі́ і всіх Небе́сних Сил ви́сшая;","ра́дуйся, А́нгели чти́мая, от Серафи́м воспіва́ємая.","Ра́дуйся, благословляємая на Небесі́ і сла́вимая на землі́;","ра́дуйся, воі́стину Присноблаже́нная і Пренепоро́чная.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 2","ps":["Ви́дящи Премилосе́рдная Ма́тер Бо́жия земно́є ско́рбноє житіє́ на́ше, не́мощі і болі́зні, благоізво́ли яви́ти чу́до, ізбра́в сосу́д благода́ті і ми́лостей Свої́х к нам, благочести́ваго кня́зя Андре́я. Оба́че і ми с ра́достію несказа́нною припа́даєм к Тебі́, Влади́чице, і із глубини́ душі́ благодари́м Тя, на́шу ди́вную Засту́пницю, воспіва́юще Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ти хотя́ чу́до, явле́нноє ми́лостію Твоє́ю, Пресвята́я Богоро́дице, єгда́ ко́ни, везшії святи́й о́браз, ста́ша, і лю́діє к ше́ствію подви́гнути їх не возмого́ша, благові́рний князь Андре́й нача́ть со слеза́ми моли́тися к Тебі́, Влади́чице, да пока́жеши, Пречи́стая, во́лю святу́ю Свою́; Ти же во виді́нії благоволи́ла єси́ откри́ти преблаги́й сові́т Твой. Ті́мже і ми, чу́до сіє́ воспомина́юще, прекло́ньше колі́на, взива́єм си́це:","Ра́дуйся, просла́вившая мі́сто оби́телі Твоєя́ ди́вним чудоді́йствієм і в сем ми́лость преізобильную нам показа́вшая;","ра́дуйся, страну́ Влади́мирськую сві́том Свої́м озари́вшая і лучи́ сві́та на всіх нас простирающая.","Ра́дуйся, Всеблага́я на́ша Наста́внице, любо́вію нас привлекающая;","ра́дуйся, Охранительнице на́ша от бід і болі́зней.","Ра́дуйся, у Го́спода спасе́нія на́шего Хода́тайце, Цари́це на́ша Небе́сная;","ра́дуйся, за вся благодія́нія Твоя́ благодаре́нію нас науча́ющая.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіня́єть всіх, с ві́рою і благогові́нієм притека́ющих к Тебі́, Пречи́стая Госпоже́ Богоро́дице, і упова́ющих на Твою́ ми́лость, поне́же вся́коє благо́є проше́ніє приє́млеши те́плі. Благові́рний князь моля́ше Тя, Влади́чице, яви́ти во́лю Твою́, преісполнився тре́пета пред та́їнством Твоєго́ проізволе́нія. Та́кожде і ми к Тебі́, Пречи́стая, прибіга́єм, умиле́нно вопію́ще: Всеми́лостивая Покрови́тельнице на́ша, научи́ і нас прославля́ти всечестно́є і всехва́льноє і́м'я Твоє́ і досто́йно воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй на путі́, я́ко Боготе́чную звізду́, честни́й о́браз Твой, Влади́чице, благові́рний князь в прилі́жній моли́тві своє́й пред чудотво́рною Твоє́ю іко́ною сподо́бися я́ві узрі́ти Тя, Цари́цю Небе́сную, те́плоє хода́тайство Твоє́ Бо́гу принося́щую о мі́сті явле́нія Твоєго́ і о всем ми́рі. О Бо́жия Ма́ти, Пречи́стая Богоро́дице! Со умиле́нієм припа́даєм к Тебі́ і, бога́тия Твоєя́ ми́лости ожида́юще, уми́льно вопіє́м Ті:","Ра́дуйся, Ра́досте на́ша і крі́пкая Засту́пнице;","ра́дуйся, Покро́ве наш і на́ше Утіше́ніє.","Ра́дуйся, Охранительнице на́ша і на́ше Упова́ніє;","ра́дуйся, Отра́до на́ша і ди́вноє о нас попече́ніє.","Ра́дуйся, Похвало́ на́ша, чудеси́ нас удивляющая;","ра́дуйся, Прибі́жище на́ше і зало́г ві́чнаго спасе́нія.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 4","ps":["Недоуміва́єть ум наш, ка́ко досто́йно єсть восхвали́ти Тя і ди́вноє явле́ніє Твоє́, Пресвята́я Влади́чице: я́ко со́лнце лучи́ іспуща́ющи, предста́ла єси́ моля́щемуся кня́зю і та́ко рекла́ єси́: «Не хощу́, да о́браз Мой несе́ши в Росто́в, но во Влади́мирі поста́ви Єго́; на сем мі́сті во і́м'я Моєго́ Рождества́ це́рков воздви́гни і обита́лище і́ноком соста́ви», і, возді́вши Свої́ Боже́ственнії ру́ці ко Влади́чнему о́бразу, скри́ся от духо́вних оче́с єго́. Преклоня́єм і ми колі́на пред Тобо́ю, Боголюби́вая Ма́ти, і Твоя́ чу́дная явле́нія і велі́нія разумі́юще із глубини́ душі́ воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Госпо́дь моле́нія Твоя́, Богоізбра́нная Цари́це Небе́сная, обіща́ ви́ну іспо́лнити, я́ко Преблаги́я Ма́тере, проше́нія Твоя́. Ти же, о Влади́чице, тогда́ рекла́ єси́ ко Го́споду усти́ Свої́ми: «Влади́ко Многоми́лостиве, Го́споди, Ісу́се Христе́, Си́не і Бо́же Мой, молю́ Тя, да пребу́деть Боже́ственная благода́ть на лю́діх Твої́х, і світоза́рний луч сла́ви Твоєя́ да нисхо́дить всегда́ на мі́сто сіє́, Мно́ю ізбра́нноє». І́стинно іспові́дуєм, о Пречи́стая, я́ко ско́ро помога́єши с ві́рою к Тебі́ прибегающим, і, со умиле́нієм воспіва́юще Тебі́, зове́м си́це:","Ра́дуйся, Моли́твеннице на́ша пред Го́сподем і Сино́м Твої́м;","ра́дуйся, Засту́пнице всего́ ро́да челові́чеськаго і Защи́тнице наро́да правосла́внаго.","Ра́дуйся, Ма́тернюю любо́в Твою́ всегда́ нам явля́ющая і вся блага́я нам да́рующая;","ра́дуйся, ра́дости нам, благода́ті же і сла́ви ві́чная Хода́тайце, ди́вная на́ша Уті́шительнице.","Ра́дуйся, битіє́ оби́телі і ниспосланіє на ню благода́ті предвозвестившая;","ра́дуйся, в па́м'ять Твоєго́ явле́нія храм во сла́ву Рождества́ Твоєго́ устро́їти указавшая і та́мо Це́ркві Христо́вой ди́вноє украше́ніє яви́вшая.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 5","ps":["Я́ко лучеза́рную звізду́, в пределах Влади́мирських явле́нную, узрі́ князь Андре́й Пресві́тлий о́браз Твой, Влади́чице, і в явле́нії сем уразумі́в зна́меніє ве́лія попече́нія Бо́жия о мі́сті явле́нія Твоєго́, даде́ єму́ і́м'я Боголюби́воє. О Цари́це і Влади́чице! Освіти́ і нас сві́том Твої́м Небе́сним, сохраня́ющи нас под кро́вом Твої́м благи́м, усли́ши всеумиленния моли́тви восхваля́ющих Тя і воспіва́ющих Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Виді́ніє чу́дноє Богома́тере і святи́я словеса́ Єя́ приє́мля с ра́достним тре́петом, благові́рний князь умиле́нно со слеза́ми паде́ на зе́млю і сла́достно возблагодари Всеви́шняго, я́ко сподо́бися узрі́ти Тя, Пресвяту́ю Богоро́дицю. Посе́м ускори́ це́рков заложити, іді́же ни́ні Боголюби́вая оби́тель, і́менем Твої́м красу́ющися, мо́литься за весь мир пред пречи́стим Твої́м о́бразом. Созерца́юще в таково́м сбитії зна́меніє благода́ті, дерза́єм воспіва́ти си́це:","Ра́дуйся, Ми́лостивая, я́ко устро́їла єси́ ти́хоє приста́нище іщущим спасе́нія;","ра́дуйся, Пресві́тлая, я́ко світ подава́єши всім хотя́щим жи́ти в преподо́бії і тім показу́єши пра́вия стезі́ к Ца́рствію Небе́сному.","Ра́дуйся, те́плая Хода́тайце о живу́щих в оби́теліх Твої́х, ми́лость Свою́ ви́ну їм обіща́вшая;","ра́дуйся, я́ко в труді́х і́ночеських їм всегда́ помога́єши і к трудолю́бію подвиза́єши.","Ра́дуйся, я́ко в ке́лліях мона́шеських на моли́тву вразумля́єши і к доброді́тельному житію́ ре́вностно возбужда́єши;","ра́дуйся, Храни́тельнице ди́вная оби́телей святи́х, я́ко Твоє́ю благода́тною си́лою о́ния зиждяться і преспіва́ють в благоче́стії.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 6","ps":["Пропові́дуєть вся земля́ Украї́нськая бога́тия ми́лості Твоя́, Влади́чице, і ди́вноє благода́тноє кня́зя Андре́я вразумле́ніє. Сему́ послі́дуя, благові́рний князь повелі́ о́браз написа́ти тім подо́бієм, я́коже єму́ яви́ся Пречи́стая, і, обрі́т святу́ю іко́ну, поклони́ся, ра́достно со слеза́ми благодаря́ Бо́га і ско́рую на́шу Помо́щницю, взива́я: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ благода́ть неізрече́нная от цільбоно́сния іко́ни Твоєя́, Пресвята́я і Боголюби́вая Ма́ти. Сли́шим і ви́дим вели́чіє чуде́с, от нея́ бива́ємоє, со удивле́нієм взира́єм на сію́ іко́ну, я́ко на Пресві́тлоє лице́ Само́й Пречи́стия Ді́ви. О Госпожі́, Цари́це і Влади́чице! Ти ви́ну воздвиза́єши ру́ці Твої́ на моле́ніє за нас пред Сино́м Твої́м, не пре́зри і вопію́щих Ті похва́льная сія́:","Ра́дуйся, во утіше́ніє нам дарова́вшая о́браз Твой чудотво́рний;","ра́дуйся, но́вую ми́лость і но́вую благода́ть сим в Це́ркві явля́ющая і тім путь спасе́нія показу́ющая.","Ра́дуйся, Покрови́тельнице на́ша, от бід нас спаса́ющая і в ско́рбіх би́строє облегче́ніє нам посила́ющая;","ра́дуйся, сострадательнейшая к болі́знем на́шим, ско́рую по́мощ нам подаю́щая.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 7","ps":["Хотя́ благові́рний князь досто́йно почти́ти пресвяту́ю во́лю Твою́, Влади́чице, собра́ архієре́ї, свяще́нники і люде́й мно́жество, да ублажа́ть Тя хвале́бно собо́ром. О чу́днаго торжества́! О прему́дрости суде́б Твої́х, Влади́чице! Пресла́вно прено́ситься чудотво́рная Твоя́ іко́на в ди́вний храм всечестна́го Рождества́ Твоєго́. Чудоді́йствієм прославля́ється це́рков Твоя́, о Госпоже́ Богоро́дице, і всі предстоя́щії, ра́дости і умиле́нія ісполне́нії, прекло́ньше колі́на, цілу́ють Твой пречи́стий о́браз і взива́ють: О, Ма́ти Боголюби́вая, осіни́ всеси́льною Твоє́ю десни́цею і нас, воспіва́ющих Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вна діла́ Твоя́, Влади́чице! Всі лю́діє, здра́вії і боля́щії, бога́тії і ни́щії, всі прибіга́єм к Тебі́, сострадательнейшей Ма́тері на́шей. Не отри́ни нас от лиця́ Твоєго́, бу́ди ми́лостива к нам, недосто́йним рабо́м Твої́м, во всіх путеіх жи́зні на́шея, защити́ і поми́луй от всея́ душі́ любо́вію вопію́щих Тебі́ такова́я:","Ра́дуйся, ненаді́ющихся наді́яніє і печа́льних утіше́ніє;","ра́дуйся, о скорб'я́щих попече́ніє і бедствующим по́моще.","Ра́дуйся, а́лчущих Корми́тельнице і ни́щих одія́ніє;","ра́дуйся, убо́гих Засту́пнице і боля́щих ісціле́ніє.","Ра́дуйся, ста́рцев Покрови́тельнице і ю́них Воспита́тельнице;","ра́дуйся, вражду́ющих примире́ніє і оби́димих Защи́тнице.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 8","ps":["Ди́вноє чу́до пренесе́нія пресла́вния іко́ни Твоєя́, Влади́чице, торже́ственно всі честву́єм і на вся́коє лі́то в сей сві́тлий пра́здник благода́рні воспомина́єм вся неізче́тная благодія́нія чуде́с, Тобо́ю, Пречи́стая, от іко́ни ди́вно істоча́ємих; і тя, уго́дниче Бо́жий Лео́нтіє, в по́мощ призива́єм, чту́ще с любо́вію честну́ю па́м'ять твою́, да моли́твами твої́ми сподо́бимся у Пречи́стия обрісти́ благода́ть, єще́ же непреста́нно воспіва́ти Го́споду: Аллилу́я."]},{"h":"Ікос 8","ps":["Все вели́чіє чуде́с Твої́х, Пречи́стая, ність ісчи́слити возмо́жно, єгда́ безбо́жний цар Батий, разоря́я гра́ди і ві́си і хра́ми сожигая, со мно́гою ра́тію прибли́зися і ко святі́й оби́телі Твоє́й, Пречи́стая, вни́де в це́рков і, обрі́т чудотво́рную іко́ну, де́рзостно положи́ ру́ку на драга́я ри́зи, храм со всім бога́тством огню́ предаде́, то́чію єди́н о́браз Твой, Влади́чице, ціл обрі́теся і ничи́мже поврежден бисть. О ве́ліє чу́до! О, коль ди́вни зна́менія благода́ті явля́єши нам, Пречи́стая! Кто не ублажи́ть Тя? Кто не воспоє́ть Твоя́ сла́вная чудеса́? І ми, грі́шнії, со умиле́нієм взира́юще на святу́ю іко́ну Твою́, толь чуде́сно от поги́бельнаго пла́мене сохра́ншуюся, со слеза́ми взива́єм си́це:","Ра́дуйся, я́ко купина́, огне́м горі́вшая і неопа́льна преби́вшая;","ра́дуйся, я́ко благода́ть Тебі́ даде́ся си́лу о́гненную угаша́ти.","Ра́дуйся, в годи́ну напа́стей і іспита́ній оста́вльшая нам святу́ю іко́ну Свою́ во утіше́ніє;","ра́дуйся, я́ко благости́нею Своє́ю угаша́єши в нас огнь нече́стія пла́менем огня́ Боже́ственнаго.","Ра́дуйся, просла́вившая чудеси́ іко́ну Твою́;","ра́дуйся, я́ко моли́твою і лобизанієм іко́ни Твоєя́ всі ми приє́млем благода́тноє утіше́ніє.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 9","ps":["Все упова́ніє возлага́єм на Твою́ бла́гость, Пресвята́я Влади́чице! Милосе́рдію Твоєму́ ність конця́, вели́чіє же Твоє́ кто іспові́сть? Предстоя́щи с мольбо́ю у Престо́ла Всеви́шняго, коль мно́гоє мно́жество чуде́с явля́ла єси́ нам, Пречи́стая, коль ди́вно спасла́ єси́ сла́вний град Москву́ от гро́знаго врага́ Тамерлана, коль чу́дно об'ят єго́ вели́кий страх прише́ствієм Твої́м в ма́тер ру́ських градо́в і пону́ди а́біє отступи́ти со всім во́їнством. Не умолчи́м нікогда́, Засту́пнице на́ша Пресла́вная, о всіх Твої́х благодія́ніїх, да не бу́деть под спу́дом світ чуде́с Твої́х. І ни́ні, предстоя́ще пред Пречи́стим Твої́м о́бразом і моля́щеся умиле́нною душе́ю і сокруше́нним се́рдцем, взива́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не довлі́ють по достоя́нію воспі́ти хвалу́ і благодаре́ніє Пречи́стій, ка́ко ца́рственний град сохрани́ от тата́рських по́лчищ. Єгда́ вся рать вра́жия отступа́ше от преді́л Моско́вських, цар Іоа́нн со ско́рбію і слеза́ми отпусти́ чудотво́рний о́браз Твой, Боголюби́вая Влади́чице, в ізбра́нную оби́тель Твою́, іді́же со умиле́нієм і ра́достію неізрече́нною сріто́ша єго́ лю́діє, і от ма́ла до вели́ка, всі, прекло́ньше колі́на, ублажа́ху Тя, Пречи́стая. І ми, сея́ ра́дости ми́сленні причаща́ющеся, Цари́це Небе́сній вопіє́м благода́рні:","Ра́дуйся, премилосе́рдая Уті́шительнице на́ша, святу́ю іко́ну да́ти нам ізво́лившая;","ра́дуйся, от наше́ствія враго́в іноплеме́нних нас ди́вно спа́сшая.","Ра́дуйся, царе́й на́ших несокруши́мий щиті́;","ра́дуйся, оте́чества на́шего благонаде́жноє утвержде́ніє.","Ра́дуйся, во́їнства крі́пкая защи́то, от меча́ вра́жия сохраня́ющая;","ра́дуйся, от разоре́нія, плі́на і лю́тия сме́рті свято́ю десни́цею Твоє́ю всіх упова́ющих на Тя ізбавля́ющая.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ свою́ ду́шу, благочести́вий цар Фео́дор, любо́вію боже́ственною разжигаєм, до́брі подвиза́ся, пребива́я в пості́ і моли́тві, і, вельми́ люб'я́ Боголюби́вую оби́тель, ча́сто ю посещаше. Єди́ножди же с те́плою моли́твою пред чудотво́рною Твоє́ю іко́ною, Боголюби́вая Ма́ти, от усе́рдія своєго́ в дар Тебі́ принесе́ носи́мий на пе́рсіх свої́х честни́й крест, ка́меньми драги́ми украше́нний. Взира́юще на сіє́ ди́вноє украше́ніє іко́ни Твоєя́, о Пречи́стая, ра́дуємся всі духо́вно о сем, ка́ко Тя, Цари́цю і Влади́чицю, сла́в'ять і чтуть всі ві́рнії, і моля́щеся вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́, огражда́ющая ни от вся́ких болі́зней, бива́єши Пресвята́я Богоро́дице, єгда́ со умиле́нною моли́твою призива́єм в по́мощ на́шу Твоє́ Ма́тернеє милосе́рдіє. А́ще бо Ти не би предстоя́ла, Боголюби́вая Ма́ти, моля́щи о нас, кто би нас ізба́вил от смертоно́сних ран і язв всегуби́тельних! Со умиле́нієм созерца́єм, ка́ко на путі́ благода́тнаго ше́ствія Твоєго́ всі боля́щії чуде́сно ісціля́хуся і стру́пи на тілесі́х во мгнове́ніє о́ка врачевахуся. Ті́мже і ми, припа́дающе к цільбоно́сній іко́ні Твоє́й, мо́лим Тя, Влади́чице: не оста́ви ни ми́лостію Твоє́ю пребога́тою, ізба́ви ни от вся́ких болі́зней, найпа́че же от смертоно́сния я́зви і па́губи. О Пресвята́я Богоро́дице! Благоспі́шно спаси́ нас і поми́луй с ві́рою і любо́вію вопію́щих Ті із глубини́ душі́:","Ра́дуйся, страни́ на́шея правосла́вния ди́вная Покрови́тельнице, мно́гажди от бід і напа́стей ю ізбавлявшая;","ра́дуйся, страда́льцев благода́тним утіше́нієм вінча́ющая і разсла́бленним ско́роє возставле́ніє даю́щая.","Ра́дуйся, сліпи́м прозрі́ніє і хроми́м от неду́га їх ди́вноє ізбавле́ніє дарова́вшая;","ра́дуйся, пораженних разли́чними неду́гами і болі́зньми чуде́сно ісціля́ющая.","Ра́дуйся, скорб'я́щих роди́телей в лише́нії чад їх утіша́ющая благода́тною Твоє́ю по́мощію;","ра́дуйся, Ціли́тельнице на́ша в страда́ніїх тіле́сних і блага́я Уті́шительнице в печа́ліх на́ших душе́вних.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє всеумиле́нно прино́сить Тебі́, Боголюби́вая Ма́ти, вся страна́ Украї́нськая за чу́дноє ізбавле́ніє от смертоно́сния я́зви, толь гибельно ю поразившия. Сві́тлії дні ди́вних ісціле́ній начертани на сердця́х ві́рующих, і моле́нія те́плия возно́сяться на вся́коє лі́то в па́м'ять сего́ ра́достнаго торжества́, єгда́ свята́я іко́на Твоя́, Влади́чице, с пі́нії духо́вними прино́ситься в сла́вний град Влади́мир. Красу́йся і лику́й, благослове́нний гра́де! Торжеству́йте, правові́рнії, зря́ще несомую іко́ну Влади́чиці, істоча́ющую неізче́тния ісціле́нія всім притека́ющим к ней с ві́рою і любо́вію! Преклоня́єм і ми колі́на пред Тобо́ю, Пресвята́я Богоро́дице, велича́єм Тя і мо́лим: прийми́ ми́лостивно і от нас же́ртву хвали́ і прославле́нія, приноси́мую Тебі́ от недосто́йних раб Твої́х, вопію́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную іко́ну Твою́, Боголюби́вая Ма́ти, с благогові́нієм зрим в Боже́ственних хра́міх Твої́х, ра́дующеся. Кто не прибегаше к Тебі́, Влади́чице? Кто не покланя́шеся, кто не лобиза́ше Твоя́ пречи́стия стопи́? Кто не умоляше Тя, Засту́пницю на́шу? О Пресвята́я Ді́во, прийми́ ві́ру і усе́рдіє на́ше, напра́ви путь наш на стезі́ і́стини, умоли́ Го́спода і Си́на Твоєго́, да спасе́ть нас, і́миже вість судьба́ми, да не поги́бнем в нераскаянії о на́ших грехопаденіїх, і усли́ши моле́нія к Тебі́ взива́ющих:","Ра́дуйся, Благода́тная, всі́ми доброді́тельми преукраше́нная, Своє́ю благода́тію нас не оставля́ющая;","ра́дуйся, Храни́тельнице на́ша, в час сме́ртний тьму вра́жию отгоня́ющая і по сме́рті нас упокоєвающая.","Ра́дуйся, Ми́лостивая, ми́лость Свою́ нам явля́ющая в день іспита́нія, во́ньже откри́ються діла́ на́ша, до́брая же і зла́я;","ра́дуйся, Милосе́рдая, заступле́ніє нам посила́ющая і тім в бу́дущем ві́чния ра́дости сподобля́ющая.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 12","ps":["Благода́тію Боже́ственною осіня́єма, свята́го Іоа́нна Предте́чу с ли́ки Арха́нгел зрим стоя́щия о́крест Пречи́стия Ма́тере Боголюби́вия, вку́пі же ублажа́єм і тя, уго́дниче Бо́жий. Помози́ нам, немощни́м, імі́ти ві́ру непоколеби́му, ум чист, си́ли і проізволе́ніє освяща́ти душі́ на́ша посто́м і моли́твою і ви́ну полага́ти хране́ніє усто́м на́шим, да моли́твами Влади́чиці і твої́ми сподо́бимся досто́йно воспі́ти Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще неісче́тная зна́менія і чудеса́ Твоя́, Пресвята́я Богоро́дице, умиле́нно припа́даєм к пречи́стому о́бразу Твоєму́, Боголюби́вая Ма́ти, лобиза́юще єго́ со стра́хом і тре́петом, хва́лим Тя я́ко неісчерпа́ємий істо́чник благода́ті, і мо́лим: бу́ди Хода́тайця о нас, воздви́гни ру́ці к Си́ну Твоєму́, да ви́ну в жи́зні сей і в бу́дущей милосе́рдіє Єго́ неотсту́пно бу́деть от нас, взива́ющих Тебі́:","Ра́дуйся, Присноблаже́нная, па́че земноро́дних ві́дущая блаже́нство пребива́ти с Бо́гом;","ра́дуйся, і нас прича́стники сего́ блаже́нства соделивающая.","Ра́дуйся, Пренепоро́чная Ді́во, всеці́ло стяжа́вшая чистоту́, смире́ніє і непоро́чность;","ра́дуйся, да́рующая нам блага́я сія́, да бу́дем уго́дни Тебі́ і Бо́гу.","Ра́дуйся, Всеми́лостивая Цари́це, простирающая на нас, грі́шних, ми́лость Свою́ во вся́коє вре́м'я живота́ на́шего;","ра́дуйся, чадолюби́вая Ма́ти, да́рующая нам Своє́ Ма́тернєє заступле́ніє в час сме́рти.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 13","ps":["О Ма́ти Боголюби́вая, Цари́це Небе́сная, Всемо́щная на́ша Предста́тельнице! Ма́лия сія́ усли́шавши смире́нния мольби́ на́ша, при́зри на ни ми́лостивим Твої́м о́ком; бу́ди нам ско́рая Засту́пниця в день кончи́ни на́шея і в час сме́ртний яви́ся нам Сама́, Пречи́стая, простира́ющи ру́ку по́мощі, отгоня́ющи духо́в зло́би, і́щущих поглоти́ти ду́шу на́шу при разлуче́нії от ті́ла, і сподо́би нас в бу́дущей жи́зні во весе́лії і ра́дованії возвели́чити і просла́вити Тя, я́ко Преблагу́ю Покрови́тельницю на́шу, да спасе́ннії Тобо́ю, в безконе́чнім ві́ці вопіє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов превисшую вся Небе́сния Си́ли велича́ють Тя, Богоро́дицю Цари́цю, ми же грі́шнії на землі́, чу́дному Бо́жию о Тебі́ смотре́нію див'я́щеся, все́ю душе́ю, се́рдцем і устна́ми дерза́єм глаго́лати:","Ра́дуйся, Благослове́нная в жена́х Ді́во Благода́тная;","ра́дуйся, Всеви́шняго Ма́ти, Ду́ха Свята́го пребива́ніє.","Ра́дуйся, Цари́це Небесе́ і землі́ і всіх Небе́сних Сил ви́сшая;","ра́дуйся, А́нгели чти́мая, от Серафи́м воспіва́ємая.","Ра́дуйся, благословляємая на Небесі́ і сла́вимая на землі́;","ра́дуйся, воі́стину Присноблаже́нная і Пренепоро́чная.","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Боголюби́вій Цари́це, превисшей вся́каго созда́нія, Ді́ві і Ма́тері Христа́ Бо́га, похва́льная воспису́єм Ті раби́ Твої́, Богоро́дице! Ти же, я́ко Боголюби́вая і Всеми́лостивая Ма́ти, благоізволившая яви́ти пресві́тлий Свой лик благові́рному на́шему кня́зю Андре́ю, от бід і скорбе́й сохрани́ ни і храм сей, да зове́м Ті:","Ра́дуйся, Боголюби́вая Цари́це Богоро́дице, Наде́ждо і Прибі́жище на́ше."]},{"h":"Молитва","ps":["О Пречи́стая Госпоже́ Богоро́дице, Ма́ти Боголюби́вая, наде́ждо на́шего спасе́нія! Воззри́ ми́лостивно на предстоящия с ві́рою і любо́вію і покланяющіяся пречи́стому о́бразу Твоєму́, прийми́ на́ше хвале́бноє пі́ніє сіє́ і проле́й те́плую Твою́ моли́тву о нас, грі́шних, ко Го́споду, да, презрі́во вся на́ша согріше́нія, спасе́ть і поми́луєть нас. О Преди́вная Влади́чице! Покажи́ на нас чу́дния ми́лості Твоя́: ізба́ви нас от вся́кия ско́рби, наста́ви на путь вся́кия доброді́телі і благости́ні, спаси́ от іскуше́ній, бід і болі́зней, ізми́ от нас оклевета́нія і ссори, сохрани́ от молнієно́снаго гро́ма, от запале́нія о́гненнаго, от гла́да, тру́са, пото́па і смертоно́сния я́зви, пода́й нам Свою́ ми́лостивую по́мощ на путі́, в мо́рі і на су́ші, да не поги́бнем лю́ті. О Всеми́лостивая Боголюби́вая Ма́ти, с тве́рдим упова́нієм возсила́єм к Тебі́ на́шу убо́гую моли́тву! Не отри́ни на́ших слез і воздиха́ній, не забу́ди нас во вся дні живота́ на́шего, но всегда́ пребива́й с на́ми і Твої́м заступле́нієм і хода́тайством у Го́спода пода́ждь нам отра́ду, утіше́ніє, защи́ту і по́мощ, да ви́ну сла́вим і велича́єм преблагослове́нноє і всепі́тоє і́м'я Твоє́. Амі́нь."]},{"h":"Молитва друга","ps":["О Чу́дная і Ви́сшая всіх тва́рей Цари́це Богоро́дице, Небе́снаго Царя́ Христа́ Бо́га на́шего Ма́ти! Усли́ши нас, грі́шних і недосто́йних раб Твої́х, в час сей моля́щихся і припа́дающих к Тебі́ с воздиха́нієм і слеза́ми і уми́льно глаго́лющих: ізведи́ нас от ро́ва страсте́й, Влади́чице; ізба́ви нас от вся́кия ско́рби і печа́лі; огради́ от вся́кия напа́сти і злих клеве́ть, от непра́веднаго і лю́таго наві́та вра́жия. Мо́жеши бо, о Благода́тная Ма́тер на́ша, не то́чію от вся́каго зла сохрани́ти лю́ди Твоя́, но і вся́ким благодія́нієм снабди́ти і спасти́; ра́зві Тебе́ іни́я Предста́тельниці в біда́х і обстоя́ніїх і те́плия Хода́тайці о нас, грі́шних, не і́мами к Си́ну Твоєму́, Христу́ Бо́гу на́шему, Єго́же умоли́, Влади́чице, да, спасе́ннії Тобо́ю, сла́вим і в бу́дущем ві́ці Всесвято́є І́м'я Си́на Твоєго́ і Бо́га на́шего, ку́пно со Отце́м і Святи́м Ду́хом, ни́ні і в безконе́чния ві́ки. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Боголюби́вая Цари́це, / Неіскусому́жная Ді́во Богоро́дице Марі́є, / моли́ за ни Тебе́ Возлюби́вшаго / і ро́ждшагося от Тебе́ Си́на Твоєго́ Христа́ Бо́га на́шего, / пода́ти нам оставле́ніє прегріше́ній, / ми́рові мир, землі́ плодо́в ізоби́ліє, / па́стирем святи́ню / і всему́ челові́чу ро́ду спасе́ніє. / Гра́ди на́ша і страни́ Украї́нськия от нахожде́нія іноплеме́нних заступи́ / і от междоусо́бния бра́ні сохрани́. / О, Ма́ти Боголюби́вая Ді́во! / О, Цари́ці Всепі́тая! / Ри́зою Твоє́ю покри́й нас от вся́каго зла, / от ви́димих і неви́димих враг защити́, // і спаси́ ду́ші на́ша."]},{"h":"Кондак, глас 3","ps":["Ді́ва днесь предстої́ть Си́ну, / ру́ці Свої́ к Нему́ простира́ющи, / святи́й князь Андре́й ра́дується, / і с ним Украї́нськая страна́ торжеству́єть, // нас бо ра́ди мо́лить Богоро́диця преве́чного Бо́га."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Грузинська»","e":"Akathist to the Theotokos before her icon “Georgian”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в, Бо́жієй ма́тері і Цари́ці пред пречи́стим Єя́ о́бразом, со умиле́нієм хвале́бная пі́нія прино́сим: Ти же, я́ко іму́щая к ро́ду христия́нському милосе́рдіє неізрече́нноє, от бід і скорбе́й ізба́ви всіх нас Тебі́ зову́щих:","Ра́дуйся, Неві́ста Неневі́стная."]},{"h":"Ікос 1","ps":["Арха́нгелов і А́нгелов чи́ни благогові́йно Тебі́ слу́жать і вся Небе́сния Си́ли немо́лчними гла́си Тя, Богоро́дице Ді́во, воспіва́ють, я́ко ро́ждшую небе́сних во́їнств Царя́: ми же земноро́днії, тре́петно предстоя́ще чудотво́рному Твоєму́ ли́ку бре́нними устна́ми вопіє́м Ті си́це:","Ра́дуйся, от всіх родо́в ко іскупленію ро́да на́шего ізбра́нная;","Ра́дуйся, Ду́ха Свята́го дарова́ній преісполненная.","Ра́дуйся, Херуви́мов і Серафи́мов превозше́дшая;","Ра́дуйся, та́їнству спасе́нія ро́да челові́чеськаго послужи́вшая.","Ра́дуйся, свято́є вмісти́лище Сло́ва Бо́жия;","Ра́дуйся, неопи́санноє Сло́во О́тчеє в ложесна́х Свої́х носи́вшая.","Ра́дуйся, проро́чеських глаго́лов нело́жноє ісполне́ніє;","Ра́дуйся, вину́ прароди́телей ро́да на́шего рождество́м Твої́м іскупившая.","Ра́дуйся, предста́тельство ро́ду христия́нському от Бо́га дарова́нноє;","Ра́дуйся, спасе́нія ро́да челові́чеськаго нача́ло.","Ра́дуйся, лі́ствице Боже́ственнаго снисхожде́нія;","Ра́дуйся, мо́сте от землі́ к небесі́ земноро́дних возводя́й.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 2","ps":["Ви́дящи Пречи́стая с висоти́ небе́снаго жили́ща Своєго́, іді́же с Сино́м Свої́м во сла́ві пребива́єть, озлобле́ніє проти́ву святи́нь христия́нських во страні́ Грузинстей, попуще́нієм Бо́жиїм во дні о́ни би́вшеє от Пе́рськаго царя́ Аббаса, Грузи́нськую страну́ разори́вшаго і хра́ми Єя́ христия́нськия оскверни́вшаго, і храня́щи святу́ю іко́ну от такова́го поруга́нія, страни́ Украї́нськия му́жу ві́рну і благогові́йну Стефа́ну, благопромислительне ві́дати ю вспомоществова́ла єси́, Влади́чице. Стяжа́в у́бо сей ві́рний раб святи́ню Твою́, во умиле́нії се́рдця, возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ти хотя́ благогові́йний муж Гео́ргій недоумі́нную та́йну открове́нія Твоєго́, Влади́чице, о ні́коєм бесценном би́сере, приста́вником імі́нія єго́ во страні́ Перси́дстій приобретеннем, с Патріа́рхом Филаре́том совещашеся. Ми же та́їнственному вразумле́нію Преблагослове́нния, сви́ше ві́рним рабо́м подаваємому, див'я́щеся, благогові́йно вопіє́м к Ней:","Ра́дуйся, сокрове́нния та́йни благода́ті Бо́жия ві́рним открива́ющая;","Ра́дуйся, устна́ми правосла́вних хвалу́ Бо́гові соверша́ющая.","Ра́дуйся, неві́рних ага́рян, святи́ню Твою́ презрі́вших, посрамля́ющая;","Ра́дуйся, сла́вою чуде́с Твої́х ві́рних сми́сли озаря́ющая.","Ра́дуйся, почита́нію святи́х іко́н нас наставля́ющая;","Ра́дуйся, Христо́ву ві́ру во страні́ на́шей утвержда́ющая.","Ра́дуйся, оби́тель і́ноков Кра́сния Гори́ святи́м Твої́м о́бразом освяща́ющая;","Ра́дуйся, день принесенія честни́я Твоєя́ іко́ни ісціле́нієм і́нока знаменовавшая.","Ра́дуйся, безці́нний би́сер, святу́ю Твою́ іко́ну, я́коже рекла́, нам дарова́вшая;","Ра́дуйся, безці́нний би́сер, Христа́, на спасе́ніє на́ше ро́ждшая.","Ра́дуйся, честни́м Твої́м о́бразом страну́ на́шу посіти́вшая;","Ра́дуйся, ми́рную оби́тель і́ноков неот'ємлемим бога́тством обогати́вшая.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіня́єть ви́ну с ві́рою притека́ющих к держа́вному покро́ву Твоєму́, Влади́чице, і благогові́йно чту́щих чудотво́рную іко́ну Твою́, Богома́ти: єй бо даде́ся благода́ть от Бо́га всяк неду́г і вся́ку я́зю в лю́діх врачева́ти, ті́мже благода́рственно вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́ющи промишле́ніє те́плоє о лю́діх зи́мния полу́нощі, Го́ру Кра́сную под кров Твой, Богома́ти, прия́ла єси́, і оби́телі і́ноков тоя́ честни́й о́браз Твой ми́лостивно дарова́ла єси́: да зря́ще то́ки чуде́с, преізоби́льно на моля́щихся Тебі́ с ві́рою ізлива́ємия, во умиле́нії, вопію́ть Тебе́, Влади́чице:","Ра́дуйся, смире́нную оби́тель і́ноков Кра́сния Гори́ держа́вним покро́вом Твої́м осіня́ющая;","Ра́дуйся, чудеса́ми от святи́я Твоєя́ іко́ни Го́ру Кра́сную прославля́ющая.","Ра́дуйся, подо́біє благода́тнаго Афо́на на зи́мній полу́нощі яви́вшая;","Ра́дуйся, Го́ру Кра́сную житію́ і́ночеському чу́дно указавшая.","Ра́дуйся, в щит і огражде́ніє мі́ста того́ цільбоно́сную іко́ну Твою́ дарова́вшая;","Ра́дуйся, поселившимся на сей святі́й горі́ інокам оби́тель ти́хую создавшая.","Ра́дуйся, житіє́ чи́на і́ночеськаго во спасе́ніє душ устроя́ющая;","Ра́дуйся, всім хотя́щим улучи́ти спасе́ніє споборствующая.","Ра́дуйся, Кра́сную Го́ру і обита́ющих на ней благода́тним Твої́м омофо́ром покрива́ющая;","Ра́дуйся, притека́ющих к Твоєму́ покро́ву і заступле́нію не оставля́ющая.","Ра́дуйся, сла́бих на путі́ доброді́телі укріпля́ющая;","Ра́дуйся, заблудших на путь і́стинний наставля́ющая.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я помишле́ній сумни́тельних сліпе́ць Питири́м, єгда́ озаре́н бі сія́нієм сві́та, я́ко со́лнечним, см'яте́ся і стра́хом обдержи́м бі, мня́ше о сем, я́ко о навожденії бісо́встім: мно́га бо лі́та сліп бі, с моли́твою зна́меніє креста́ сотвори́, обра́щся ко хра́му і узрі́ чу́дную Твою́, Влади́чице, іко́ну, світоза́рними луча́ми во хра́мі блиставшую, а́біє уразумі́, я́ко отверзо́шася о́чі єго́ і слух єго́ откри́ся, благода́рственноє прине́с Бо́гу, ди́вному в ді́ліх, пі́ніє: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав благові́рний цар всея́ Россі́ї Алексі́й, я́ко от святи́я іко́ни Твоєя́, Влади́чице, я́же на Горі́ Кра́сній, цільби́ многоразли́чних неду́г оби́льно подаю́ться, даде́ повелі́ніє ігу́мену оби́телі по градо́м і ве́сем вели́кия держа́ви своєя́ с че́стію подоба́ющею ю обноси́ти: да приє́млють стра́ждущії врачество́ неду́гов тіле́сних і душе́вних і во умиле́нії серде́ць взива́ють Тебе́, Влади́чице:","Ра́дуйся, Христа́ Бо́га на́шего освяще́нний храм;","Ра́дуйся, неізрече́нния Єго́ сла́ви вмісти́лище.","Ра́дуйся, Царя́ ца́рствующих одушевле́нний гра́де;","Ра́дуйся, пала́то і черто́же небе́сний.","Ра́дуйся, Це́ркві Правосла́вния похвало́;","Ра́дуйся, держа́ви Украї́нськия крі́посте і утвержде́ніє.","Ра́дуйся, градо́в і ве́сей на́ших благода́тноє охране́ніє;","Ра́дуйся, всіх христия́н, к Тебі́ притека́ющих, непости́дноє упова́ніє.","Ра́дуйся, от всіх родо́в досто́йно ублажа́ємая;","Ра́дуйся, всіх нас от бід і скорбе́й прише́ствієм честна́го Твоєго́ о́браза ізбавля́ющая.","Ра́дуйся, су́щих в стра́нствії ко взиска́нію го́рняго гра́да направля́ющая;","Ра́дуйся, Путеводи́тельнице на́ша к ві́чним оби́телем.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ подо́бна яви́ся Твоя́, Богома́ти, іко́на, по во́лі Твоє́й святі́й от восто́ка на са́мую полу́нощ принесе́нная, ю́же, я́ко дар небе́сний, восприє́мше і́ноці Красногорстії, поста́виша в собо́рную це́рков оби́телі, і во весе́лії поя́ху благи́х пода́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Видещі среброковача Гавриї́ла, зі́льні пла́чуща пред Твої́м чудотво́рним о́бразом, Влади́чице, я́коже бо тогда́ умилосе́рдися, си́на єго́ на одрі́ болі́зні лежа́ща воздви́гла і здра́ва сотвори́ла єси́, си́це і о мні умилосе́рдися, Преблагослове́нная Богоро́дице, і гріхми́ умерщвле́нную мою́ ду́шу воскреси́, зову́щу:","Ра́дуйся, Ма́ти Царя́ живота́ і Побіди́теля сме́рті;","Ра́дуйся, благоволе́ніє Си́на Твоєго́, Христа́ Бо́га на́шего, нам стяжа́вшая.","Ра́дуйся, сві́тлими луча́ми чуде́с от святи́я Твоєя́ іко́ни страну́ Украї́нськую озаря́ющая;","Ра́дуйся, бога́тия да́ри ісціле́ній і ми́лостей прося́щим Тя пред чу́дною Твоє́ю іконой істоча́ющая.","Ра́дуйся, моле́нія на́ша, приноси́мая Тебі́ с ві́рою і любо́вію ми́лостивно приє́млющая;","Ра́дуйся, тіле́сниє неду́ги ві́рно почита́ющих Тя ско́ро ісціля́ющая.","Ра́дуйся, печа́ль на́шу в ра́дость претворя́ющая;","Ра́дуйся, от слез і скорбе́й нас ізбавля́ющая.","Ра́дуйся, ско́рбних о ча́діх роди́телей утіше́ніє;","Ра́дуйся, чад їх благода́тноє охране́ніє і спасе́ніє.","Ра́дуйся, покро́ве нам в животі́ і по сме́рті;","Ра́дуйся, спасе́ніє на́ше на пра́ведном суді́ Бо́жиєм.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 6","ps":["Пропові́дника творя́щи купця́ Гео́ргия во́лі Своєя́, рекла́ єси́ к нему́, Влади́чице: приста́вник імі́нія твоєго́ Стефа́н, сий в Перси́ді, купи́ тебі́ бесці́нний би́сер, єгда́ же принесе́ть к тебі́, ти посли́ о́ний в Двинськую о́бласть, на Чермну́ю го́ру. Позна́в у́бо о сем Гео́ргій Твоє́, Пречи́стая, к мі́сту тому́ особоє благоволе́ніє, воспряну воспі́ти к ро́ждшемуся от Теб'я́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла сла́ва Бо́жия на святі́й Горі́ Кра́сній от пречу́дния Твоєя́ іко́ни, Богома́ти, пред не́юже предстоя́ще, со умиле́нієм мо́лимся Ті, усли́ши нас, вопію́щих Тебі́ усе́рдно:","Ра́дуйся, Го́ру полу́нощную прише́ствієм чудотворнагоТвоєго о́браза осіни́вшая;","Ра́дуйся, чуде́с неоскудевающий істо́чник на ней яви́вшая.","Ра́дуйся, милосе́рдіє і любо́в Твою́ к оби́телі і́ноков показа́вшая;","Ра́дуйся, благо́є о ней промишле́ніє Своє́ яви́вшая.","Ра́дуйся, тіле́сния неду́ги на́ша врачу́ющая;","ра́дуйся, в душе́вних ско́рбіх нас утіша́ющая.","Ра́дуйся, благоче́стія Наста́внице;","Ра́дуйся, і́ночеськаго житія́ Руководи́тельнице.","Ра́дуйся, до́брия ко спасе́нію душ обі́ти приє́млющая;","Ра́дуйся, благи́м намі́ренієм і начина́нієм на́шим спосо́бствующая.","Ра́дуйся, зли́я от навожденія врага́ бива́ємая по́мисли от нас отгоня́ющая;","Ра́дуйся, вра́жия ко́зні, я́ко паучи́ну, расторга́ющая.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 7","ps":["Хотя́ да́ти благослове́ніє новоустроєнней оби́телі і́ноков, Раї́фськой нарече́нній, Архипа́стир Каза́нський Лавре́нтій, лик Твой, Влади́чице, от чудотво́рнаго Твоєго́ Красного́рськаго о́браза тождественно списа́в, торже́ственно с молебним пі́нієм, во оби́тель Раїфськую внесе́. Свиді́телем же бив соверши́вшихся от сея́ святи́я Твоєя́, Влади́чице, іко́ни зна́меній і чуде́с, ра́достно возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую купі́ль Силоамськую зрим, Пречи́стая Богоро́дице, храм Твой, і́же в Раї́фі: всяк бо неду́г і вся́ку я́зю душе́вную і тіле́сную врачу́єши с ві́рою і любо́вію к Тебі́ притека́ющих і благогові́йно чту́щих і лобиза́ющих святи́й о́браз Твой. Сего́ ра́ди, іму́ще но́воє неізрече́нноє сокро́вище Твої́х ми́лостей, ра́достно вопіє́м Ті, Пречи́стая:","Ра́дуйся, купі́ль, в не́йже душе́вния неду́ги на́ша, врачу́ються;","Ра́дуйся, істо́чниче жа́ждущим во́ду жи́зні істочи́вший.","Ра́дуйся, сліпи́м тіле́снима очи́ма зрі́ніє подава́ющая;","Ра́дуйся, глухи́м слух отверза́ющая.","Ра́дуйся, разсла́бленния ті́лом укріпля́ющая;","Ра́дуйся, лежа́щия на одрі́ болі́зней возставля́ющая.","Ра́дуйся, пла́вающия по вода́м от бур і потопле́нія спаса́ющая;","Ра́дуйся, влающияся в пучи́ні жите́йськаго мо́ря к ти́хому приста́нищу спасе́нія направля́ющая.","Ра́дуйся, ору́жіє, і́мже устраша́ються полки́ де́монськия;","Ра́дуйся, щиті́, і́мже покрива́ються оби́телі і́ноков.","Ра́дуйся, ти́хоє пустинножи́телей весе́ліє;","Ра́дуйся, ти́хоє обурева́ємих в сем ві́ці приста́нище.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 8","ps":["Стра́нно сли́шати і неудо́бно разумі́ти злим неві́рієм омраче́нним, ка́ко от святи́х іко́н Твої́х, Влади́чице, зна́менія і чудеса́ бива́ють: нам же те́плі ві́рующим словесі́, Тобо́ю к первоначертанней благові́стником єва́нгельських тайн святі́й іко́ні рече́нному: благода́ть ро́ждшагося от Мене́ і Моя́ с сим о́бразом да бу́деть, удо́бно єсть разумі́ти і пра́ведно упова́ти, я́ко і с не́ю свято́ю Твоє́ю іконой, \"Грузи́нською\", благода́ть Твоя́ і си́ла пребива́єть ви́ну: сего́ ра́ди с благогові́йним стра́хом предстоя́ще, чтем і воздає́м єй честь, я́ко Тебі́ само́й, нам прису́щей, ра́достно пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся при́сно го́ре су́щи і с Небе́сними Си́лами ви́ну пребива́ющи, нас земноро́дних не оставля́єши, Богома́ти, те́плим предста́тельством пред Сино́м і Бо́гом Твої́м: ма́тернєє бо дерзнове́ніє к Нему́ і́маши. Сего́ ра́ди предстоя́ще пречи́стому Твоєму́ о́бразу, со слеза́ми покая́нія вопіє́м ті, Богороди́тельнице:","Ра́дуйся, Путеводи́тельнице ві́рная, к небе́сному оте́честву до́брі нас направля́ющая;","Ра́дуйся, Ма́ти Царя́ небесі́ і землі́, врата́ райскиє нам отверза́ющая.","Ра́дуйся, Домострої́тельнице, житіє́ на́ше к небе́сному устроя́ющая;","Ра́дуйся, ві́чная бла́га Си́на Твоєго́ нам явля́ющая.","Ра́дуйся, от скорбе́й і бід зді нас спаса́ющая;","Ра́дуйся, ві́чних мук і огня́ геє́нськаго по сме́рті нас ізбавля́ющая.","Ра́дуйся, всіх притека́ющих с ві́рою і любо́вію к Тебі́ сугу́бо ми́лующая;","Ра́дуйся, моли́тви на́ша, приноси́мия Тебі́ пред чудотво́рним Твої́м о́бразом, ко престо́лу Си́на Твоєго́ і Бо́га на́шего вознося́щая.","Ра́дуйся, блага́я на́ша Помо́щнице;","Ра́дуйся, непости́дноє на́ше упова́ніє і ві́рноє спасе́ніє.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 9","ps":["Вся́каго єстества́ Арха́нгельськаго і А́нгельськаго Преви́сшая, Херуви́м і Серафи́м Честні́йшая, Пресвята́я Ді́во, Бо́га бо Царя́ Небе́сних Сил пло́тію родила́ єси́, Нося́щаго весь мир дла́нію на рука́х носи́ла єси́, і вся́коє єстество́ Питающего млеко́м пита́ла єси́: ті́мже воі́стину Ма́тер Бо́жию і Хода́таїцю ро́да христия́нськаго Тя ві́дуще, со дерзнове́нієм вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не ві́дять ки́їми словеси́ благохва́льними подоба́єть велича́ти Тя, Богома́ти, по достоя́нію, недоумі́єть бо всяк язи́к досто́йно пі́ти Тя, Богоро́дице: оба́че, Блага́я су́щи, прийми́ ми́лостивно, а́ще і немощни́ми сми́сли сложенная, но от чи́стаго се́рдця приноси́мая Тебі́ в похвалу́ сицева́я пі́нія:","Ра́дуйся, пренепоро́чная Отрокови́це, преві́чним сові́том ко спасе́нію ро́да на́шего ізбра́нная;","Ра́дуйся, Же́но, Єя́же сі́м'я сокруши́ главу́ дре́вняго змі́я.","Ра́дуйся, в жена́х Преблагослове́нная;","Ра́дуйся, благода́ть у Бо́га обрі́тшая.","Ра́дуйся, Арха́нгельськоє віща́ніє о воплоще́нії Єди́наго от Святи́я Тро́йці смире́нно прия́вшая;","Ра́дуйся, кро́ткая раба́ Госпо́дня.","Ра́дуйся, сосу́де, Ду́хом Бо́жиїм освяще́нний;","Ра́дуйся, си́лою Всеви́шняго осіне́нная.","Ра́дуйся, Спаси́теля на́ших душ ро́ждшая;","Ра́дуйся, па́дший род наш с правосу́дієм Бо́жиїм примири́вшая.","Ра́дуйся, Єде́м затворе́нний рождество́м Твої́м ми́ру отве́рзшая;","Ра́дуйся, от пліне́нія а́да рождество́м Твої́м свободи́вшая.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи мно́гия лю́ди от бід і скорбе́й, всю́ду явля́єши, Богома́ти, ро́ду на́шему неоскудіва́ємий от своєя́ іко́ни \"Грузинськия\" істо́чник ми́лости. Красногорськую бо оби́тель от запале́нія о́гненнаго во дні о́ни неврежде́нну сохрани́ла єси́, угаси́вши свиріпі́ющую о́крест єя́ си́лу о́гненную, в ца́рствующем же гра́де Москві́ і в пусти́ні Раїфстей благода́ті струї́ от іко́ни Твоєя́ істоча́єши всім, с ві́рою покланя́ющимся Тебі́, і во іни́х граді́х і весях на́ших чту́щим Тя поле́зноє подає́ши. Ті́мже, прославля́юще Бо́га, дарова́вшаго нам о Тебі́ благода́ть такову́ю, при́сно вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ крі́пкая, Богоро́дице Ді́во, оби́телі Красногорськия і пусти́ні Раїфськия огра́да несокруши́мая, чи́ну же і́ночеському украше́ніє і сла́ва. Сего́ ра́ди, моля́щеся, вопіє́м Ті, Пречи́стая: покри́й с ві́рою покланя́ющияся Тебі́ пред Твої́м чудотво́рним о́бразом от бід і скорбе́й, с любо́вію Тебі́ вопію́щих:","Ра́дуйся, крі́пкая от находя́щих на ни напа́стей і бід Храни́тельнице;","Ра́дуйся, оби́телей і́ночеських неуси́пная Блюсти́тельниці.","Ра́дуйся, от свирі́піющаго пла́мене, во дні о́ни, оби́тель Красногорськую, по те́плому моле́нію і́ноков, ди́вно сохранившая;","Ра́дуйся, благорастворе́ніє возду́хов і спаси́тельний дождь благовре́менно той ниспославшая.","Ра́дуйся, житія́ чи́на і́ночеськаго украше́ніє і добро́то;","Ра́дуйся, в бу́рю іскуше́ній і бід нас спаса́ющая.","Ра́дуйся, помишле́нія на́ші освяща́ющая;","Ра́дуйся, се́рдця на́ші очища́ющая.","Ра́дуйся, душегуби́тельний пла́мень страсте́й на́ших угаша́ющая;","Ра́дуйся, мрак сатани́нських іскуше́ній разсеявающая.","Ра́дуйся, житію́ на́шему благослове́ніє Бо́жиє низводящая;","Ра́дуйся, ми́сленная очеса́ на́ша ко го́рнім оби́телем направля́ющая.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє прино́сять Ті, Влади́чице, лю́діє богоспаса́ємаго гра́да Архангелська, єгда́ град їх єди́ною в лі́то освяща́ється прише́ствієм Твоєго́ чудотво́рнаго о́браза, і со світи́льники і кади́льници гряду́ще во срі́теніє єго́, ра́достно вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рними луча́ми чуде́с іко́ни Твоя́, Влади́чице, на святі́й Горі́ Кра́сній немерцаємо сія́єть і Украї́нськую страну́ на́шу правосла́вную благода́тно озаря́єть, прогоня́юще вся́коє те́мноє ді́йство вра́жиє си́лою Бо́жиєю, побуждающи нас пред не́ю Тебі́, Богоізбра́нная Отрокови́це, хвале́бная пі́нія возноси́ти:","Ра́дуйся, на путі́ на́шего спасе́нія неугаси́мий світи́льниче ві́ри і благоче́стія;","Ра́дуйся, луче́ незаходи́маго со́лнця.","Ра́дуйся, немерцающая во страні́ на́шей правосла́вія звіздо́;","Ра́дуйся, доброді́телі путь освіща́ющая.","Ра́дуйся, заре́, со́лнце пра́вди явля́ющая;","Ра́дуйся, сві́те, мрак неві́дінія отгоня́ющая.","Ра́дуйся, купино́ неопали́мая, Бо́га яви́вшая;","Ра́дуйся, престо́ле о́гненний Вседержи́теля.","Ра́дуйся, чистоти́ сокро́вище;","Ра́дуйся, цві́те неув'яда́ємия сла́ви.","Ра́дуйся, Ви́шняго освяще́нноє Боже́ственноє селе́ніє;","Ра́дуйся, я́ко Тобо́ю даде́ся ра́дость всім, Тя, Богоро́дице, зову́щим.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 12","ps":["Благода́ті Твоєя́ нікогда́же оскудевающия неізсяка́ємий істо́чник яви́ла єси́, Богороди́тельнице, чудотво́рную Твою́ іко́ну, от нея́же всі скорб'я́щії і обремене́ннії гріхи́ мно́гими спасе́ніє і цільби́ во вся времена́ приє́млють і ра́достно о Тебі́ воспіва́ють всеблаго́му Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ пресла́вная чудеса́, Богома́ти, от святи́я Твоєя́ іко́ни неоску́дно нам подаваємая, і все упова́ніє на́ша на Тя, Засту́пнице, возлага́юще, со умиле́нієм вопіє́м Ті:","Ра́дуйся, непости́дноє христия́н упова́ніє в бу́дущем ві́ці;","Ра́дуйся, в ді́ланії за́повідей Си́на Твоєго́ пребива́ющих спаса́ющая.","Ра́дуйся, в животі́ сем нас во здра́вії сохраня́ющая;","Ра́дуйся, в стра́шний час сме́рти нас неоставляющая.","Ра́дуйся, ві́рним рабо́м Твої́м христия́нськую кончи́ну устроя́ющая;","Ра́дуйся, на суді́ пра́веднім Си́на Твоєго́ ві́рним слуга́м Твої́м вожделі́нний глас Єго́ сли́шати сподобля́ющая.","Ра́дуйся, всім хотя́щим спасти́ся і в ра́зум і́стини прийти́ Блага́я Одиги́тріє;","Ра́дуйся, всіх, в сокруше́нії серде́чнім ка́ющихся грі́шников, несомні́нноє спасе́ніє.","Ра́дуйся, Рождество́м Твої́м две́рі рая́ ми́ру отве́рзшая;","Ра́дуйся, земноро́дних с небе́сними к ві́чному весе́лію сочета́вшая.","Ра́дуйся, от А́нгел при́сно воспіва́ємая;","Ра́дуйся, і от земноро́дних досто́йно ублажа́ємая.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 13","ps":["О, всепі́тая Ма́ти, Пресвята́я Госпоже́, Ді́во Богоро́дице, не отри́ни смире́нно приноси́моє Тебі́ ни́ні пред чудотво́рним о́бразом Твої́м сіє́ ма́лоє моле́ніє на́ше, презира́ющи бе́здну гріхо́в на́ших: ізба́ви всіх нас от бід і скорбе́й в животі́ сем і гряду́щия ві́чния ізми́ муки́ нелицемі́рно о Тебі́ вопію́щих Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгелов і А́нгелов чи́ни благогові́йно Тебі́ слу́жать і вся Небе́сния Си́ли немо́лчними гла́си Тя, Богоро́дице Ді́во, воспіва́ють, я́ко ро́ждшую небе́сних во́їнств Царя́: ми же земноро́днії, тре́петно предстоя́ще чудотво́рному Твоєму́ ли́ку бре́нними устна́ми вопіє́м Ті си́це:","Ра́дуйся, от всіх родо́в ко іскупленію ро́да на́шего ізбра́нная;","Ра́дуйся, Ду́ха Свята́го дарова́ній преісполненная.","Ра́дуйся, Херуви́мов і Серафи́мов превозше́дшая;","Ра́дуйся, та́їнству спасе́нія ро́да челові́чеськаго послужи́вшая.","Ра́дуйся, свято́є вмісти́лище Сло́ва Бо́жия;","Ра́дуйся, неопи́санноє Сло́во О́тчеє в ложесна́х Свої́х носи́вшая.","Ра́дуйся, проро́чеських глаго́лов нело́жноє ісполне́ніє;","Ра́дуйся, вину́ прароди́телей ро́да на́шего рождество́м Твої́м іскупившая.","Ра́дуйся, предста́тельство ро́ду христия́нському от Бо́га дарова́нноє;","Ра́дуйся, спасе́нія ро́да челові́чеськаго нача́ло.","Ра́дуйся, лі́ствице Боже́ственнаго снисхожде́нія;","Ра́дуйся, мо́сте от землі́ к небесі́ земноро́дних возводя́й.","Ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в, Бо́жієй ма́тері і Цари́ці пред пречи́стим Єя́ о́бразом, со умиле́нієм хвале́бная пі́нія прино́сим: Ти же, я́ко іму́щая к ро́ду христия́нському милосе́рдіє неізрече́нноє, от бід і скорбе́й ізба́ви всіх нас Тебі́ зову́щих:","Ра́дуйся, Неві́ста Неневі́стная."]},{"h":"Молитва","ps":["Прийми́, Всеблагомо́щная Пречи́стая Госпоже́, Влади́чице Богороди́тельнице, сія́ честни́я да́ри от нас, недосто́йних рабо́в Твої́х, к Твоєму́ цільбоно́сному о́бразу пі́ніє возсила́ющих со умиле́нієм, я́ко Тебі́ Само́й су́щей ту і послу́шающей моле́нія на́ша, подаю́щи с ві́рою прося́щим по коєму́ждо проше́нію ісполне́ніє: скорб'я́щим ско́рби облегча́єши, немощни́м здра́віє да́руєши, разсла́бленних і неду́жних ісціля́єши, і от бі́сних бі́си прогоня́єши, оби́димия от оби́д ізбавля́єши, і наси́луємих спаса́єши, грі́шних проща́єши, прокаже́нних очища́єши, і ма́лих діте́й ми́луєши, і непло́дния от непло́дства разріша́єши. Єще́, Госпоже́ Влади́чице, от уз і темни́ць свобожда́єши, і вся́кия многоразли́чния стра́сті ісціля́єши, і о́чния болі́зні уврачу́єши, і от смертоно́сния я́зви ізбавля́єши: вся бо возмо́жна суть хода́тайством Твої́м к Си́ну Твоєму́, Христу́ Бо́гу на́шему. О, Всепі́тая Ма́ти, Пречи́стая Богоро́дице! Не преста́й моли́ти о нас, недосто́йних рабі́х Твої́х, сла́в'ящих Тя і почита́ющих, і покланя́ющихся пречи́стому о́бразу Твоєму́, і наде́жду іму́щих невозвра́тну і ві́ру несумне́нну к Тебі́, Присноді́ві, Пресла́вній і Непоро́чній, сла́в'ящих, і чту́щих, і пою́щих Тя во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь сві́тло красу́ється оби́тель Красного́рськая, / і с не́ю ликовству́єть Раї́фськая пу́стиня, / я́ко зарю́ со́лнечную, от восто́ка возсія́вшую, восприї́мши, Влади́чице, / чудотво́рную Твою́ іко́ну, / є́юже разгоня́єши мглу іскуше́ній і бід от вопію́щих ві́рно: / ізба́ви оби́тель на́шу і вся страни́ христия́нськия от всіх наві́т вра́жиїх // і спаси́ ду́ші на́ша, я́ко Милосе́рдная Засту́пниця ро́да христия́нського."]},{"h":"Кондак, глас 8","ps":["Тебі́, Ізбра́нній от всіх родо́в, Бо́жієй Ма́тері, / благода́рственная пі́нія прино́сим, / прише́ствієм честни́я Твоєя́ іко́ни, раби́ Твої́, Богоро́дице, озаря́ємі, / но, я́ко іму́щая держа́ву непобіди́мую, / от вся́ких нас бід свободи́, да зове́м Ті: // ра́дуйся, Неві́сто Неневі́стная."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Жировицька»","e":"Akathist to the Theotokos before her icon “Zhyrovichy”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Цари́це і Влади́чице похва́льния пі́сні принесе́м, я́ко хода́тайце і засту́пнице ро́да христия́нськаго, Ти же, я́ко блага́я предста́тельниця пред Го́сподем, умоли́ Си́на Твоєго́ і Бо́га на́шего дарова́ти нам наслі́діє благ ві́чних, да ра́дующеся о Тебі́ взива́єм:","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л, с небесе́ по́сланний к Тебі́, Ді́во чи́стая, веща́ Ті: Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю! Ми же, благода́тією Бо́жиєю чрез Тебі́ озаре́ннії, восхваля́єм Тя пі́сньми сицеви́ми:","Ра́дуйся, пре́жде віко́в Сові́том Бо́жиїм предизбра́нная;","ра́дуйся, А́гнице, А́гнця Бо́жия ро́ждшая.","Ра́дуйся, сокро́вищнице спасе́нія на́шего, преви́шшая сил А́нгельських;","ра́дуйся, Отрокови́це пренепоро́чная і Ма́тер Сві́та.","Ра́дуйся, горо́ несіко́мая, істо́чник води́ живи́я істочи́вшая;","ра́дуйся, раю́ цвітоно́сний, Боже́ственноє Дре́во жи́зні проізрасти́вшая.","Ра́дуйся, Богообра́дованная Ма́ти, ра́дость Не́бу і землі́ ро́ждшая;","ра́дуйся, си́лою Всеви́шняго осіне́нная, Боже́ственний Клас прозя́бшая.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 2","ps":["Ви́дящи ві́рная ча́да Твоя́, в біда́х жите́йських унива́ющая і по́мощі Небе́сния от Тебе́ тре́бующая, Ти, Богома́ти, наде́ждо христия́ном, чуде́сним явле́нієм близ ві́си Жиро́вицькия святи́я іко́ни Твоєя́ іспо́лнила єси́ ра́дости і весе́лія сердця́ всіх в ско́рбі припа́дающих к Тебі́, да благода́рственно вопію́ть о Тебі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом не уразумі́в та́йни чуде́снаго явле́нія на дре́ві іко́ни Твоєя́, Пречи́стая Влади́чице, скри боля́рин Со́лтан в ковче́жці явле́нний Тобо́ю о́браз. Ти же, Ді́во Богоро́дице, сугу́бим явле́нієм на том же дре́ві іко́ни сея́ вразуми́ла єси́ єго́, да всі позна́ють дар милосе́рдія, лю́дем Тобо́ю ниспосила́ємий, і во весе́лії возопію́ть:","Ра́дуйся, кла́дезю живи́й неісчерпа́ємия ра́дости;","ра́дуйся, цві́те благоуха́нний неізрече́нния сла́дости.","Ра́дуйся, явле́нієм іко́ни Твоєя́ на дре́ві нас крі́пко огражда́ющая;","ра́дуйся, благода́тію от нея́, а́ки от дре́ва жи́зні, нас сладкопита́ющая.","Ра́дуйся, ми́лости заблу́ждших не лиша́ющая;","ра́дуйся, покро́вом Твої́м всіх осіня́ющая.","Ра́дуйся, гла́су моле́нія скорб'я́щих послу́шная;","ра́дуйся, Ма́ти милосе́рдія неоску́днаго.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 3","ps":["Си́лою вразумле́нія о явле́нії чудотво́рния іко́ни Твоєя́ просвіще́нний, позна́ боля́рин Со́лтан, я́ко іко́на сія́ стра́ждущим во утіше́ніє Тобо́ю сви́ше ниспо́слана бисть, і, сле́зно сокруша́яся о неразу́мії своє́м, воздви́же храм на мі́сті явле́нія єя́, да всі лю́діє, Бо́гу воздаю́ть непреста́нную о Тебі́ хвалу́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи бога́тство милосе́рдія неізрече́нноє, не отри́нула єси́ промишле́нієм ізбра́нних Твої́х, в ско́рбі ве́лієй су́щих. Єгда́ бо храм, іді́же бі іко́на Твоя́ пречестна́я, огне́м попале́н бисть, Ти, Всеблага́я уті́шительнице, сохрани́ла єси́ о́браз Твой от огня́ неврежде́н, па́ки яви́ла єси́ на ка́мені близ хра́ма огне́м сожже́ннаго. Лю́діє же, узрі́вше таково́є чу́до, воспі́ша Ті хвале́бную піснь сицеву́ю:","Ра́дуйся, Купино́ неопали́мая, во огні́ пречестни́й Свой о́браз сохра́ншая;","ра́дуйся, ско́рбния лю́ди Твоя́ чудотво́рния іко́ни не лиши́вшая.","Ра́дуйся, кро́вом крилу́ Твоє́ю христия́н покрива́ющая;","ра́дуйся, предста́тельством Твої́м святи́ні охраня́ющая.","Ра́дуйся, на ка́мені пречестни́й Твой о́браз па́ки яви́вшая;","ра́дуйся, вразумле́нієм Твої́м на ка́мені ві́ри стопи́ на́ша утверди́вшая.","Ра́дуйся, я́ко сті́ну неруши́мую Тебі́ стяжа́хом;","ра́дуйся, я́ко благомо́щную покрови́тельницю Тя позна́хом.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 4","ps":["Бу́рею страсте́й і іскуше́ній одержи́мії ві́рнії Твої́, моля́щеся пред чудотво́рною іко́ною Твоє́ю, поко́й і душе́вную ра́дость обріта́ють. Ти бо, Ді́во чи́стая, христия́н путеводи́тельнице, му́дро і пра́во путь житія́ ше́ствовати наставля́єши, да всі богокра́сною пі́снію восхваля́ють Бо́га, пою́ще: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше лю́діє, я́ко явле́нная Тобо́ю іко́на да́ром чуде́с преізби́точествуєть, с ві́рою і упова́нієм на милосе́рдіє Твоє́ к ней притека́ють і, бога́тством щедро́т Твої́х обогати́вшеся, воспіва́ють Ті хвалу́ такову́ю:","Ра́дуйся, мо́ре щедро́т христия́ном ізлива́ющая;","ра́дуйся, ра́дость всему́ ми́ру принося́щая.","Ра́дуйся, свяще́нноє прибі́жище ві́рних;","ра́дуйся, пода́тельнице благ ві́чних.","Ра́дуйся, услади́тельнице го́рестей на́ших;","ра́дуйся, крі́пкоє воста́ніє па́дших.","Ра́дуйся, ізнемога́ющих засту́пнице і укріпле́ніє;","ра́дуйся, в страда́ніїх на́ших при́сноє утіше́ніє.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́, с восто́ка возсія́вшей, подо́бна била́ єси́, Пресвята́я Ді́во, єгда́ в лучеза́рнем сія́нії а́ки Жена́ красоти́ неізрече́нния яви́лася єси́ ді́тем, указу́ющи мі́сто явле́нія пречестни́я іко́ни Твоєя́, чуде́сно Тобо́ю от огня́ сохране́нния. Не лиши́ла єси́ і ма́лих сих Твоєя́ благости́ні, поуча́ющи їх о вели́цім милосе́рдії Твоє́м, да, подража́юще ді́тем ізра́їлевим, восклиця́вшим Христу́: «Оса́нна», – воспою́ть хвалу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша всі стра́нноє і пресла́вноє чу́до, іко́ною Твоє́ю явля́ємоє, Пречи́стая: діви́ця ні́кая Іри́на, болі́знію подви́гшися к поклоне́нію святи́не Твоє́й, на путі́ у́мре, і єгда́ і́ноці нача́ша сверша́ти отпева́ніє єя́ пред іко́ною Твоє́ю, ди́вно воскре́се, і всі лю́діє со тре́петом восклиця́ху:","Ра́дуйся, Сло́во жи́зні пло́тію роди́вшая;","ра́дуйся, ме́ртвую рабу́ Твою́ воскреси́вшая.","Ра́дуйся, ковче́же жи́зні на́шея, от пото́па сме́ртнаго нас сохраня́яй;","ра́дуйся, ра́зуме пресві́тлий, жи́зні ві́чния позна́ніє нам да́руяй.","Ра́дуйся, іко́ною Твоє́ю істо́чники чуде́с ве́ліїх нам явля́ющая;","ра́дуйся, тьму лю́тих обстоя́ній от почита́ющих ю отгоня́ющая.","Ра́дуйся, зна́меньми непостижи́мими моля́щихся Ті ободря́ющая;","ра́дуйся, ма́терніми щедро́тами всіх прибіга́ющих к Тебі́ посіща́ющая.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 6","ps":["Пропові́дници благости́ні Твоєя́ яви́шася всі притека́ющії к цільбоно́сній іко́ні Твоє́й, Влади́чице. Не отри́нула бо єси́ нікого́же, в те́плій моли́тві ру́ці свої́ к ней простира́юща, да позна́вшії си́лу да́ра чуде́снаго Бо́гу благода́рственную піснь возопію́ть: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вшая луча́ світоза́рная яви́ся всечестна́я оби́тель Жиро́вицькая, под кро́вом святи́ні Твоєя́, Богома́ти, воздви́гнутая і путь житія́ благонра́внаго озаря́ющая. Сей бо дом по́двигов і́ночеських і учи́лище боже́ственнаго разумі́нія освіти́ зе́млю на́шу луча́ми і́стиннаго богові́дінія, да всі Тебі́, о До́мі Прему́дрости седьмисто́лпний, та́ко воспою́ть в пі́сніх достохва́льних:","Ра́дуйся, заре́ Со́лнця незаходи́маго;","ра́дуйся, Богороди́тельнице Сві́та непостижи́маго.","Ра́дуйся, лі́ствице, к небесі́ возводя́щая;","ра́дуйся, нему́дрих ра́зумом боже́ственним умудря́ющая.","Ра́дуйся, учи́лищ благоче́стія в страні́ на́шей насади́тельнице;","ра́дуйся, в позна́нії за́повідей Христо́вих прему́драя руководи́тельнице.","Ра́дуйся, ду́ші ві́рних благода́тно насища́ющая;","ра́дуйся, ві́рния млеко́м прему́дрости пита́ющая.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 7","ps":["Хотя́ще возда́ти поклоне́ніє іко́ні Твоє́й, мно́гими чудеси́ просія́вшей, посеща́ху оби́тель Жиро́вицькую не то́кмо худоро́днії, но і ца́ріє зе́мстії, припа́дающе к пречи́стому Твоєму́ о́бразу, Влади́чице, і, ча́юще от Тебе́ вели́кия і бога́тия ми́лости, приноша́ху Ті піснь хвале́бную і Бо́гові воспіва́ху: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вноє воі́стину промишле́ніє яви́ла єси́, Влади́чице, ві́рним Твої́м; єгда́ бо оби́тель Жиро́вицькая ле́стію і наси́лієм от Правосла́вія отто́ржена бисть, заступле́нієм Твої́м па́ки возврати́ся лю́дем правосла́вним. Сего́ ра́ди всі пра́вия ві́ри покло́нници притеко́ша к пречи́стому о́бразу Твоєму́, і с весе́лієм воспі́ша:","Ра́дуйся, в ско́рбних обстоя́ніїх наде́жноє прибі́жище;","ра́дуйся, і́щущим спасе́нія ти́хоє приста́нище.","Ра́дуйся, со апо́столи ві́ри Христо́ви насади́тельнице;","ра́дуйся, глубині́ сло́ва Бо́жия прему́драя учи́тельнице.","Ра́дуйся, світи́льниче Трисо́лнечнаго Сві́та, і́стиною нас озаря́яй;","ра́дуйся, сто́лпе о́гненний, путь пра́вия ві́ри нам показу́яй.","Ра́дуйся, от па́губних уче́ній на́ше охране́ніє;","ра́дуйся, душевре́дних уче́ній посрамле́ніє.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 8","ps":["Стра́нная і пресла́вная чудеса́ позна́ша о Тебі́, Богома́ти, ві́рнії Твої́, я́ко не то́кмо іко́ною Твоє́ю благода́ть їм явля́єши, но і вода́м істо́чника, на мі́сті явле́нія проісте́кшаго, дар неду́ги ісціля́ти подає́ши, да всі, вели́кую і бога́тую ми́лость от Тебе́ восприї́мше, воспою́ть хвале́бную піснь Бо́гові: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі, к покро́ву Твоєму́ прибіга́ющії, ско́роє усли́шаніє і те́плоє заступле́ніє обріта́ють: Ти бо, Богома́ти, ско́рби ма́тернія при Кресті́ Си́на Твоєго́ восприї́мшая, ві́си тяготу́ скорбе́й на́ших. Ті́мже к Тебі́, Ма́ти, в ско́рбі іскуше́нней, я́ко о́бщници ско́рби і страда́ній Си́на Твоєго́, та́ко взива́єм:","Ра́дуйся, ненаде́янних наді́яніє;","ра́дуйся, ско́рбних утіше́ніє.","Ра́дуйся, печа́лі на́ша утоля́ющая;","ра́дуйся, всему́ ми́ру ра́дость да́рующая.","Ра́дуйся, в біда́х су́щим ру́ку по́мощі ско́ро подаю́щая;","ра́дуйся, ма́тернюю любо́в і милосе́рдіє нам явля́ющая.","Ра́дуйся, пред Бо́гом на́ша моли́твеннице і засту́пнице;","ра́дуйся, в напа́стіх превели́кая защи́тнице.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 9","ps":["Вся А́нгельськая во́їнства Тебі́, Богома́ти, я́ко ви́шшую Небе́с і чи́стшую сві́тлостей со́лнечних, ублажа́ють: Бо́га бо зачала́ єси́ пло́тію і Сві́та сві́тов родила́ єси́. Ті́мже і ми, земноро́днії, я́ко честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, велича́юще Тя, вопіє́м о Тебі́ Бо́гові: Аллилу́я."]},{"h":"Ікос 9","ps":["Вети́йство вся́коє земноро́дних не довлі́єть к прославле́нію іко́ни, Тобо́ю явле́нния, от нея́же, я́ко от приснотеку́щаго істо́чника, прибіга́ющії оби́ліє благ почерпа́ють. Ті́мже, недоуміва́юще восхвали́ти Тя по достоя́нію, я́ко первоїсто́чник благ сих, со умиле́нієм се́рдця взива́єм си́це:","Ра́дуйся, домострої́тельнице на́шего спасе́нія, житіє́ на́ше до́брі устроя́ющая;","ра́дуйся, путеводи́тельнице, к Небе́сному Оте́честву нас возводя́щая.","Ра́дуйся, благи́х вино́вная, грі́шники благ ві́чних не лиша́ющая;","ра́дуйся, предста́тельнице на́ша пред Бо́гом, пра́ведний гнів Бо́жий на ми́лость претворя́ющая.","Ра́дуйся, су́єтная ми́ра сего́ презира́ти нас науча́ющая;","ра́дуйся, к любві́ боже́ственній нас привлека́ющая.","Ра́дуйся, от всіх бід ско́роє ізбавле́ніє;","ра́дуйся, отча́янних наде́жноє спасе́ніє.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́щим нам і под кров Твой прибега́ющим, бу́ди, Пресвята́я Ді́во, помо́щниця неоску́дная. Сохрани́ нас от бід і напа́стей, найпа́че же от паде́нія гріхо́внаго і отча́янія, да, преуспіва́юще в доброді́теліх Христо́вих, с ра́достію о преди́внем Твоє́м заступле́нії благода́рственно возопіє́м: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ крі́пкая Це́ркві Правосла́вній била́ єси́, Пресвята́я Ді́во, во дні тя́жких іспита́ній єя́; ті́мже мо́лим Тя: заступи́, покри́й і соблюди́ ю і во вся дні от враг злоко́зненних, возстаю́щих на ню, да всі ра́достно о Тебі́ возопіє́м:","Ра́дуйся, Це́ркви Христо́ви огражде́ніє і Правосла́вія побо́рнице;","ра́дуйся, я́ко заступле́нієм Твої́м Це́рков Христо́ва сві́тло красу́ється.","Ра́дуйся, я́ко отсту́пници ві́ри оте́чеськия Тобо́ю вразумля́ються;","ра́дуйся, я́ко Тобо́ю ко́зні враго́в Правосла́вія посрамля́ються.","Ра́дуйся, я́ко вразумле́нієм Твої́м і́стинная ві́ра в страні́ на́шей насажда́ється;","ра́дуйся, я́ко распиха́ющаяся на ню зло́ба вра́жия утиша́ється.","Ра́дуйся, тве́рдоє Правосла́вія укріпле́ніє;","ра́дуйся, єрети́чествующих посрамле́ніє.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє сладча́йшеє не довлі́єть восхвали́ти по достоя́нію щедро́ти Твоя́, Пречи́стая, ність бо ра́зума, могу́ща позна́ти глубину́ милосе́рдія Твоєго́, ніже́ сло́ва, досто́йно воспіва́юща Тя. Оба́че, блага́я су́щи, прийми́ і на́ша убо́гая хвале́нія, да і ми, вели́чіє Твоє́ прославля́юще, воспоє́м о Тебі́ піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рними луча́ми, пречи́стому о́бразу Твоєму́ прису́щими, озари́, Влади́чице, путь житія́ на́шего приско́рбний, да всі от бід і лю́тих напа́стей Тобо́ю ізба́вленнії, возмо́жем пра́во ходи́ти в зако́ні Госпо́дні, благодаря́ще Тя і пою́ще си́це:","Ра́дуйся, чудеси́ Твої́ми, я́ко омофо́ром, нас покрива́ющая;","ра́дуйся, безчи́сленния щедро́ти всім подава́ющая.","Ра́дуйся, стра́сті на́ша і по́мисли утиша́ющая;","ра́дуйся, болі́зні тіле́сния і душе́вния ісціля́ющая.","Ра́дуйся, Твої́м хода́тайством от всіх бід ізбавля́ющая;","ра́дуйся, от ско́рби і печа́лі ско́ро нас ізима́ющая.","Ра́дуйся, вдов заступле́ніє і си́рих призрі́ніє;","ра́дуйся, ю́них ісправле́ніє і ста́рцев утіше́ніє.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 12","ps":["Благода́ть с небесе́ от Бо́га іспроси́ нам, Влади́чице, к пречи́стому о́бразу Твоєму́ притека́ющим і Тебі́, Ма́тер Сві́та, в пі́сніх велича́ющим, да, осіня́ємі покро́вом Твої́м, во вся́ком благоче́стії і чистоті́ поживе́м і Престо́лу Царя́ Сла́ви неосужде́нно предста́нем, пою́ще о Тебі́ хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще вели́чія Твоя́, Пресвята́я Ді́во, восхваля́єм Тя всі і, я́ко тве́рдую предста́тельницю спасе́нія на́шего, усе́рдно мо́лим: бу́ди нам во вся́ком ді́лі бла́зі помо́щниця і усли́ши нас, уми́льно взива́ющих Ті:","Ра́дуйся, пра́ваго путі́ ко Христу́ прему́драя указа́тельнице;","ра́дуйся, чистоти́ і цілому́дрія преди́вная охрани́тельнице.","Ра́дуйся, а́лчущих і жа́ждущих пра́вди пита́тельнице;","ра́дуйся, і́щущим предста́тельства Твоєго́ неуси́пная засту́пнице.","Ра́дуйся, ізнемога́ющим поможе́ніє;","ра́дуйся, всему́ ми́ру защище́ніє.","Ра́дуйся, на всіх путеіх жи́зні нас огражда́ющая;","ра́дуйся, при ісхо́ді на́шем от духо́в зло́би защища́ющая.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 13","ps":["О, Пресвята́я Влади́чице, Ді́во Богоро́дице, А́нгельськими чи́ньми на небесі́ песносло́вимая, прийми́ і от нас, недосто́йних раб Твої́х, сіє́ ма́лоє моле́ніє, в похвалу́ Тебі́ приноси́моє, і, от паде́ній гріхо́вних ізбавля́ющи, наслі́дники ни Ца́рствія Небе́снаго соді́лай, да с Тобо́ю во ві́ки поє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгел Гавриї́л, с небесе́ по́сланний к Тебі́, Ді́во чи́стая, веща́ Ті: Ра́дуйся, Благода́тная, Госпо́дь с Тобо́ю! Ми же, благода́тією Бо́жиєю чрез Тебі́ озаре́ннії, восхваля́єм Тя пі́сньми сицеви́ми:","Ра́дуйся, пре́жде віко́в Сові́том Бо́жиїм предизбра́нная;","ра́дуйся, А́гнице, А́гнця Бо́жия ро́ждшая.","Ра́дуйся, сокро́вищнице спасе́нія на́шего, преви́шшая сил А́нгельських;","ра́дуйся, Отрокови́це пренепоро́чная і Ма́тер Сві́та.","Ра́дуйся, горо́ несіко́мая, істо́чник води́ живи́я істочи́вшая;","ра́дуйся, раю́ цвітоно́сний, Боже́ственноє Дре́во жи́зні проізрасти́вшая.","Ра́дуйся, Богообра́дованная Ма́ти, ра́дость Не́бу і землі́ ро́ждшая;","ра́дуйся, си́лою Всеви́шняго осіне́нная, Боже́ственний Клас прозя́бшая.","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Цари́це і Влади́чице похва́льния пі́сні принесе́м, я́ко хода́тайце і засту́пнице ро́да христия́нськаго, Ти же, я́ко блага́я предста́тельниця пред Го́сподем, умоли́ Си́на Твоєго́ і Бо́га на́шего дарова́ти нам наслі́діє благ ві́чних, да ра́дующеся о Тебі́ взива́єм:","Ра́дуйся, Премилосе́рдая Влади́чице, предста́тельство на́ше і всера́достноє заступле́ніє."]},{"h":"Молитва","ps":["О, Премилосе́рдая Госпоже́, Ді́во Богоро́дице! Кі́їма устна́ма прикосну́ся ко святи́ні Твоє́й іли́ ки́їми словеси́ іспові́м щедро́ти Твоя́, лю́дем явля́ємия; нікто́же бо, притека́яй к Тебі́, отхо́дить тощ і не усли́шан. От ю́ности моєя́ взиска́х по́мощі і заступле́нія Твоєго́ і ніколи́же лише́н бих милосе́рдія Твоєго́. Зри́ши, Госпоже́, ско́рбі се́рдця моєго́ і я́зви душі́ моєя́ ві́си. І ни́ні, колінопреклоне́нно предстоя́ пред пречи́стим Твої́м о́бразом, моле́нія моя́ приношу́ Ті. Не лиши́ м'я всеси́льнаго хода́тайства Твоєго́ в день ско́рби моєя́ і в день печа́лі моєя́ заступи́ м'я. То́ка слез мої́х не отврати́ся, Влади́чице, і ра́дости моє́ се́рдце іспо́лни. Прибі́жище і предста́тельство бу́ди мні, Ми́лостивая, і сві́та Твоєго́ заря́ми ум мой просвіти́. І не то́кмо о себі́ молю́ Тя, но і о лю́діх, притека́ющих к заступле́нію Твоєму́. Це́рков Си́на Твоєго́ во бла́гости соблюди́ і огради́ ю от злоко́зненних наві́тов враг, возстаю́щих на ню. Архипа́стирем на́шим посли́ по́мощ Твою́ во апо́стольстві і сохрани́ їх здра́ви, долгоде́нствующи, пра́во пра́в'ящи сло́во і́стини Госпо́дні. Па́стирем іспроси́ у Бо́га Си́на Твоєго́ ре́вность і бді́ніє о душа́х вруче́ннаго їм ста́да слове́снаго, дух ра́зума і благоче́стія, чистоти́ і пра́вди боже́ственния їм низпосли́. Іспроси́ та́кожде, Влади́чице, у Го́спода власте́м предержа́щим і градоправи́телем му́дрость і си́лу, судія́м пра́вду і нелицеприя́тіє, всім же притека́ющим к Тебі́ дух цілому́дрія, смиренному́дрія, терпі́нія і любве́. Єще́ же молю́ Тя, Премилосе́рдая, осіни́ страну́ на́шу кро́вом Твоєя́ благости́ні і ізба́ви ю от бі́дствій стихи́йних, наше́ствія іноплеме́нников і междоусо́бних нестроє́ній, да всі, живу́щії в ней, в любві́ і ми́ре пребива́юще, ти́хоє і безм'яте́жноє житіє́ поживу́ть і, благ ві́чних моли́твами Твої́ми сподо́бившеся, возмо́гуть ку́пно с Тобо́ю і всі́ми святи́ми восхваля́ти Бо́га на небесі́ во ві́ки. Амі́нь."]},{"h":"Молитва інша","ps":["О, Всепі́тая і Преблагослове́нная Ді́во, Ма́ти Христа́ Бо́га на́шего, прийми́ моле́нія нас Тебі́ прославля́ющих, Тебі́ благодаре́нія принося́щих і почита́ющих честну́ю іко́ну сію́, от літ дре́вніх во ві́си Жиро́вицстей явле́нную. Не таї́м благодія́нія Твоя́, Богоро́дице, і па́ки іспові́дуєм, я́ко сія́ іко́на Твоє́ю благода́тною си́лою всім, с ві́рою приходя́щим к ней, істоча́єть неоску́дния ми́лості: просвіща́єть сердца́ благоче́стієм, укріпля́єть си́ли осла́бленния і ісціля́єть не́мощі душе́вния і тіле́сния. О, Всепі́тая Цари́це Небе́сная, прийми́ благода́рственноє пі́ніє і нікогда́же лиши́ нас Твоєго́ Небе́снаго покро́ва і заступле́нія — вся бо мо́жеть моли́тва Ма́тері к Милосе́рдному Боже́ственному Си́ну, о сем бо вели́ком заступле́нії возвіща́єть нам сія́ ма́лая іко́на, я́ко безці́нноє сокро́вище, на сем мі́сті обрі́тенноє. Благода́тная Ма́ти Бо́жия, Ти, і в огні́ о́браз сей сохра́ншая, па́ки да́руєши єго́ в зало́г Твоєя́ бли́зости к нам і всегда́шняго заступле́нія. О, Пречи́стая Влади́чице, ум'ягчи́ сердця́ на́ша, окамене́нния гріхо́м, да, ожи́вше благода́тними Твої́ми моли́твами, іспо́лним Боже́ственния за́повіді Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, і та́ко дости́гнем несконча́ємаго дне Ца́рствія Бо́жия, вне́же і зва́ни єсьми́ со всі́ми святи́ми. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Пред свято́ю Твоє́ю іко́ною, Влади́чице, / моля́щіїся ісціле́ній сподобля́ються, / ві́ри і́стинния позна́ніє приє́млють / і ага́рянськая наше́ствія отража́ють. / Ті́мже і нам, к Тебі́ припа́дающим, / гріхо́в оставле́нія іспроси́, / по́мислами благоче́стія сердця́ на́ша просвіти́ / і к Си́ну Твоєму́ моли́тву вознеси́ // о спасе́нії душ на́ших."]},{"h":"Кондак, глас 4","ps":["Вели́чія Твоя́ кто іспові́сть, / Пресвята́я Ді́во, / Творця́ всіх Христа́ Бо́га Ро́ждшая? / Єди́на бо єси́ Ма́ти і Ді́ва, / Преблагослове́нная і Препросла́вленная, / упова́ніє на́ше, істо́чник благости́ні, // ві́рним прибі́жище і ми́ру спасе́ніє."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Моздокська»","e":"Akathist to the Theotokos before her icon “Mozdok”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці, похва́льная пі́нія прино́сим Ті раби́ Твої́, я́ко честни́м о́бразом Твої́м ми́лости істо́чник стяжа́вшії, Ти же, Госпоже́, я́ко благосе́рдая Ма́ти, бу́ди неотсту́пна ми́лостію Твоє́ю от нас, да зове́м Ті:","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци сопредста́ша, Небе́сная Цари́це, о́крест святи́я іко́ни Твоєя́, благода́тію Тобо́ю просла́вленния. Тім же і ми, взира́юще на іко́ну Твою́, в боже́ственних хра́мах нас осіня́ющую, почита́єм ю, преклоня́єм колі́на пред вели́чеством Твої́м, Влади́чице, і уми́льно воспіва́єм си́це:","Ра́дуйся, Небе́сная Цари́це, Ма́ти Го́спода небесі́ і землі́,","Ра́дуйся, арха́нгелов і а́нгелов Влади́чице,","Ра́дуйся, го́рніх сил велича́ніє,","Ра́дуйся, челові́чеських ликостоя́ній похвале́ніє,","Ра́дуйся, пра́ведних душ сла́досте,","Ра́дуйся, живу́щих в Бо́зі умиле́ніє,","Ра́дуйся, о нас пред Бо́гом предста́тельнице,","Ра́дуйся, боже́ственния бла́гости пода́тельнице,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 2","ps":["Вмісти́лище свято́є си́ли Бо́жия іко́ну Твою́, Богома́ти, Тама́ра, цари́ця І́верськая, принесе́ лю́дям Осе́тії. Прише́ствієм у́бо о́браза сего́ Ти, Пречи́стая Богоро́дице, всели́лася єси́ в них, я́ко благосе́рдая Ма́ти, ущедря́ющи благоче́стно почита́-ющих Тя і воздвиза́ющи їх воспіва́ти Бо́гу: аллилу́я."]},{"h":"Ікос 2","ps":["Разу́мні іспові́дуєм ди́вноє промишле́ніє Бо́жиє о страні́ на́шей, єй же подо́біє І́верськия іко́ни Богома́тере, благода́тію просла́вленноє, дарова́ся. Тім же, благодаря́ще Тя, Влади́чице, за ми́лость твою́ к ро́ду на́шему, воспіва́єм си́це:","Ра́дуйся, щедро́ти Твоя́ на нас ізлива́ющая,","Ра́дуйся, Твоє́ю благости́нею нам благоде́ющая,","Ра́дуйся, во вся́кой нужді́ нам помога́ющая,","Ра́дуйся, наде́жду нас недосто́йних не отверга́ющая,","Ра́дуйся, упова́ющих на Тя по́мощію не оставля́ющая,","Ра́дуйся, си́лою врачева́нія іко́ну Твою́ знамену́ющая,","Ра́дуйся, то́ю істо́чники чуде́с істоча́ющая,","Ра́дуйся, є́ю же не́мощі на́ша ісціля́ющая,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіня́ше страну́ осети́нськую, єгда́ іко́на Пречи́стия Богома́тере при́йде в ню, пребива́нієм освяща́ющая зе́млю, к созда́нію хра́мов святи́х воздвиза́ющи, да сла́виться і́м'я Триіпоста́снаго Бо́га, явле́нієм Твої́м, Влади́чице, і да воспіва́ють Єму́: аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи премно́гую ми́лость ко Кавка́зу, Пресвята́я Влади́чице, устро́їла єси́ в страні́ на́шей іко́ни Твоєя́ благода́тноє утвержде́ніє. Охраня́й у́бо о́бласть сію́ і всю держа́ву Украї́нськую, да в ми́рі і тишині́ воспіва́єм Ті си́це:","Ра́дуйся, предста́тельнице к Бо́гу, мир спаса́ющая,","Ра́дуйся, храни́тельнице, держа́ву Украї́нськую покрива́ющая,","Ра́дуйся, христия́н во благоче́стії утвержда́ющая,","Ра́дуйся, земно́є житіє́ на́ше до́брі устроя́ющая,","Ра́дуйся, пра́ведно дви́жимий на ни гнів Бо́жий утоля́ющая,","Ра́дуйся, Го́спода на ми́лость к нам преклоня́ющая,","Ра́дуйся, Благода́тію Си́на Твоєго́ нас осіня́ющая,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 4","ps":["Бу́ря злострада́ній і бід опустоша́ше страну́ осети́нськую, єгда́ нечести́вії тата́ри огне́м і мече́м по ней прохожда́ху. І́щуще спасе́нія от них, лю́діє Куртати́нськия о́бласти от гор под сінь держа́ви Украї́нськия преселя́хуся, гряду́ще на но́воє местожи́тельства, взя́ша с собо́ю іко́ну Твою́, Богома́ти, да і о́ноє Тобо́ю освяти́ться, огражда́й у́бо, Влади́чице, Твої́м покро́вом і на́ше жи́тельство, да, осіня́ємі Тобо́ю, взива́єм к Бо́гу: аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав па́стир па́стви своєя́ прише́ствіє к Моздо́ку іко́ни Бо́жия Ма́тере, устроя́єть це́рков, в ней же поставля́єть святу́ю іко́ну і свяще́нники утвержда́єть, да ви́ну прославля́юще Богома́тер, вопію́ть Єй:","Ра́дуйся, святи́х хра́мов благода́тію наполне́ніє,","Ра́дуйся, домо́в на́ших небе́сноє благослове́ніє,","Ра́дуйся, святи́х оби́телей покро́в і защище́ніє,","Ра́дуйся, всіх ві́рних прибі́жище і утіше́ніє,","Ра́дуйся, спаси́тельную ві́ру в страні́ на́шей утвержда́ющая,","Ра́дуйся, благоче́стіє в землі́ на́шей насажда́ющая,","Ра́дуйся, во благонра́вії возраста́ти нам помога́ющая,","Ра́дуйся, в до́брих ді́ліх преспіва́ющих укріпля́ющая,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́ся іко́на Твоя́, Богома́ти, страну́ кавка́ськую обтека́ющи і су́щих во тьмі неві́дінія сві́том Богові́дінія озаря́юще, скорб'я́щих ра́достію ісполня́ющи, іщу́щих по́мощі Твоєя́ утеша́ющи благода́тію Си́на Твоєго́ і Бо́га, Єму́ же благода́рственні вопіє́м: аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше лю́діє гра́да Моздо́ка іко́ну Твою́, от мі́ста їх не дви́гшуюся, со умиле́нієм уразумі́ша, я́ко сим прояви́ся вели́коє Твоє́ к ним благоволе́ніє і тім показу́єши святу́ю во́лю Твою́. Благоволи́ у́бо, Пречи́стая, показа́ти і нам ми́лость Твою́, да є́ю ущедря́ємі, со благодаре́нієм воспіва́єм Ті хвали́ сія́:","Ра́дуйся, ма́тернею любо́вію нас возлюби́вшая,","Ра́дуйся, іко́ною Твоє́ю нас сла́дці утіша́ющая,","Ра́дуйся, істо́чник благода́ті То́ю открива́ющая,","Ра́дуйся, милосе́рдія две́рі нам отверза́ющая,","Ра́дуйся, оби́ліє ми́лости нам ізлива́ющая,","Ра́дуйся, усе́рдния на́ша моли́тви приє́млющая,","Ра́дуйся, воздиха́нія серде́чная послу́шающая,","Ра́дуйся, ско́роє утіше́ніє пода́ти поспеша́ющая,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дуєть чудеса́ Твоя́ і ми́лости о́бласть кавка́ськая, я́ко ди́вно огради́ла єси́ покро́вом Твої́м чудотво́рную іко́ну Твою́ от о́гненнаго запале́нія, об'я́вшаго це́рков, в ней же свята́я іко́на пребива́ше. Три́жди бо, це́ркві возгора́ємей, лю́діє іко́ну Твою́ на горі́ близ це́ркві неврежде́нну обріта́ху. Тім же і ми Тебі́ вопіє́м: о, Пресвята́я Влади́чице, при́зри всеми́лостивим о́ком Твої́м і на нас, предстоя́щих пред пречи́стим о́бразом Твої́м, і моли́твами Твої́ми ізба́ви нас от запале́нія бід і от пла́мене огня́ ві́чнаго, да с весе́лієм поє́м Бо́гу: аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ти сві́ту богові́дінія в дре́вней Осе́тії ізволя́ющи, руко́ю цари́ці Тама́ри святу́ю іко́ну Твою́ в ню посла́ла єси́ і по сих си́лою і чудеси́ Ту́ю просла́вила єси́, і та́ко уві́рившеся о Твоє́м промишле́нії, Пречи́стая, лю́ди Твоя́ соблюда́ющем, благода́рственні прославля́єм Тя си́це:","Ра́дуйся, іко́ну Твою́ із пла́мене чуде́сно сохрани́вшая,","Ра́дуйся, сію́ мно́гими чудеси́ в страні́ на́шей просла́вившая,","Ра́дуйся, моля́щимся пред іко́ною Твоє́ю здра́віє подава́ющая,","Ра́дуйся, упова́ющим на Тя спасе́ніє да́рующая,","Ра́дуйся, от христия́нских родо́в ублажа́ємая,","Ра́дуйся, прославля́ющих Тя прославля́ющая,","Ра́дуйся, благочести́вих чу́вства услажда́ющая,","Ра́дуйся, подвиза́ющихся во ві́рі благода́тне посіща́ющая,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 7","ps":["Хотя́ще лю́діє осети́нстії в кавка́ськую о́бласть пресели́тися достиго́ша гра́да Моздо́ка, нося́ще чудотво́рную іко́ну Твою́, Богома́ти. Но́щію от колесни́ци, вней же свята́я іко́на пребива́ше, небе́сний світ возсія́, і то сли́шав, єпи́скоп Га́ій со мно́жеством наро́да ісше́д, поклоня́шеся пред не́ю до землі́, я́ко Тебі́ Самі́й, Пречи́стая Богоро́дице, моле́бноє пі́ніє творя́ і взива́я Бо́гу: аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє мі́сто пребива́нія святи́я іко́ни Твоєя́ чуде́сним зна́менієм і открове́нієм єпи́скопу Га́їю уві́рила єси́. Ка́ко у́бо ізрече́м Твою́ к нам любо́в, Богоро́дице, і кто возглаго́леть си́ли Твоя́, дарова́нния іко́ні Твоє́й? Оба́че прийми́ піснь хвали́ і благодаре́нія сицеву́ю:","Ра́дуйся, во гра́ді Моздо́ке чудотво́рною іко́ною пребива́ти благоволи́вшая,","Ра́дуйся, і про́чія гра́ди і ве́сі пренесе́нієм іко́ни заступле́нієм Твої́м не оставля́ющая,","Ра́дуйся, є́ю на Тя наді́ющихся возвеселя́ющая,","Ра́дуйся, іко́ною Твоє́ю от вся́каго зла нас сохраня́ющая,","Ра́дуйся, то́ю а́ки о́блаком сві́тлим нас покрива́ющая,","Ра́дуйся, люби́ к нам неіссяка́ющая,","Ра́дуйся, ми́лости Своя́ к нам умножа́ющая,","Ра́дуйся, гріхи́ на́ша бла́гостію побіжда́ющая,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до ізбра́нія Тобо́ю, Влади́чице, но́ваго мі́ста вселе́нія іко́ни Твоєя́ удивля́єть уми́. Не то́чію бо світ в нощі́ облиста́ мі́сто стоя́нія колесни́ци с іко́ною Твоє́ю, но і нау́тріє, єгда́ лю́діє, воздви́гшеся далеча́йше ідти́, воли́ своя́ в колесни́цю впряго́ша, ті́ї не мого́ша повлещи́ ю, а́ще і мно́го біє́ни бя́ху. І сли́шавше о́крест живу́щії о такові́м зна́менії на мі́сті пребива́нія Твоєго́, стеко́шася во мно́жестві, поклоня́ющеся іко́ні Твоє́й і воспіва́юще Бо́гу: аллилу́я."]},{"h":"Ікос 8","ps":["Всі правосла́внії лю́діє сла́в'ять і́м'я Твоє́, Богоро́дице, честни́м бо предста́тельством Твої́м чуде́сную по́мощ нам явля́єши. Ди́вна суть діла́ Твоя́, і ди́вна пресвята́я іко́на Твоя́, пред не́ю же припа́дающе, с ві́рою і упова́нієм глаго́лем Ті си́це:","Ра́дуйся, засту́пнице ро́ду христия́нському, от Бо́га дарова́нная,","Ра́дуйся, пред Го́сподем о нас хода́тайствующая,","Ра́дуйся, моли́тви о нас Тому́ простира́ющая,","Ра́дуйся, проше́нія ві́рних к Си́ну Своєму́ і Бо́гу принося́щая,","Ра́дуйся, престо́лу бла́гости Єго́ ма́терськи о нас предстоя́щая,","Ра́дуйся, благода́ть смире́нія і терпі́нія нам подава́ющая,","Ра́дуйся, Бо́жиє к нам грі́шним благоволе́ніє,","Ра́дуйся, нас недосто́йних пред Бо́гом дерзнове́ніє,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє, ви́дя Тя, Богороди́тельнице, у престо́ла Си́на Твоєго́ предстоя́щую і за христия́н моля́щуюся, восхваля́єть Тя, лю́діє же гра́да Моздо́ка, прия́ше святу́ю іко́ну Твою́ а́ки ні́коє небе́сноє сокро́вище, прославля́ють Всеви́шняго Го́спода, чудотво́рную си́лу єй дарова́вшаго, і воспіва́ють Єму́: аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не возмо́жеть по достоя́нію благохвали́ти Тя, Пресвята́я Богоро́дице, і воспіва́ти чудеса́ Твоя́, от іко́ни явля́ємая, оба́че, блага́я су́щи, прийми́ от нас за премно́гую любо́в к нам і ми́лость хвале́бноє пі́ніє сіє́:","Ра́дуйся, ві́рующих блага́я Засту́пнице,","Ра́дуйся, призива́ющих Тя непости́дноє упова́ніє,","Ра́дуйся, благочести́вих всевеселя́щеє ра́дованіє,","Ра́дуйся, тружда́ющихся по́мощ і укріпле́ніє,","Ра́дуйся, оби́димих ско́роє заступле́ніє,","Ра́дуйся, гони́мих покро́в і защище́ніє,","Ра́дуйся, ізнемога́ющих крі́пость і утвержде́ніє,","Ра́дуйся, боля́щих благонаде́жноє посіще́ніє,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи мно́гі лю́ди от бід і скорбе́й, істоча́єши, Богома́ти, неоску́дний істо́чник ми́лости от Твоєя́ Іко́ни ро́ду на́шему, тою́, а́ки Тебі́ Самі́й су́щей, гра́ди і ве́сі о́бласти на́шея обтека́ющи і в них чту́щим Тя поле́зноє проше́ніє ісполня́ющи, тім же, прославля́юще Бо́га, да́вшаго нам благода́ть такову́ю, вопіє́м Єму́: аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ві́рним, Богоро́дице Ді́во, і заступле́ніє всім к Тебі́ прибега́ющим, і́бо небесе́ і землі́ Творе́ць, на руку́ Твоє́ю носи́тися благоволи́вий, приє́млеть Тя, о лю́діх моле́бне ру́ці простира́ющую. Бу́ди у́бо стіна́ і покро́в от всіх враго́во ви́димих і неви́димих і нам, ко пречестні́й іко́ні Твоє́й с ві́рою припа́дающим, да вопіє́м Тебі́:","Ра́дуйся, от обстоя́ній і бід нас сохраня́ющая,","Ра́дуйся, от потопле́нія скорбе́й нас ізима́ющая,","Ра́дуйся, іскуше́нія душевре́дная дале́че отгоня́ющая,","Ра́дуйся, вражди́ на благосе́рдіє прелага́ющая,","Ра́дуйся, на милосе́рдіє нас подвиза́ющая,","Ра́дуйся, люби́ти друг дру́га наставля́ющая,","Ра́дуйся, во непоро́чном житії́ ві́рних укріпля́ющая,","Ра́дуйся, присноблаже́нная, блаже́нство і нам уготовля́ющая,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє вся́коє побіжда́ється, спростре́тися тща́щеєся к явле́нієм благода́ті, при́сно бива́ємим от святи́я і чудотво́рния іко́ни Твоєя́, Богоро́дице, я́коже бо ско́рая помо́щниця, неду́ги ісціля́єши, от бід ізбавля́єши на вся́ком мі́сті с ві́рою Тя призива́ющих і вопію́щих Бо́гу: аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́ зрим святу́ю іко́ну Твою́, Богома́ти, во о́бласти кавка́зстей благода́тію Твоє́ю возже́нную, всю страну́ просвіща́ющую і мно́гих к сві́ту Своєму́ на спасе́ніє душ і тіле́с привлека́ющую, тім же вопіє́м Ті си́це:","Ра́дуйся, Бо́га с челові́ки соєдиня́ющая,","Ра́дуйся, нас земноро́дних к Бо́гу приближа́ющая,","Ра́дуйся, о ка́ющихся пред Бо́гом предста́тельствующая,","Ра́дуйся, призива́ющих Тя сохраня́ющая і спаса́ющая,","Ра́дуйся, па́дших Твоє́ю бла́гостію возставля́ющая,","Ра́дуйся, отча́янним наде́жду возвраща́ющая,","Ра́дуйся, скорбми́ гріхи́ на́ша очища́ющая,","Ра́дуйся, печа́лі на́ша благода́тію утоля́ющая,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 12","ps":["Благода́тію Твоє́ю, Пресвята́я Богоро́дице, я́коже дре́вле, і ни́ні притека́ющих к цільбоно́сній іко́ні Твоє́й не оставля́єши, призива́ющим Тя благопоспе́шне вспомоществу́єши, в печа́ліх бе́дствующим помога́єши, і ми у́бо Твої́м Заступле́нієм спаса́ємі благода́рними усти́ поє́м Бо́гу: аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ Твоя́ і ми́лости, ро́ду на́шему явле́нния, уми́льно припа́даєм к Пречи́стому о́бразу Твоєму́, Влади́чице, і благогові́йно лобиза́юще той, мо́лим Тя: наста́ви нас на путь спасе́нія, бу́ди Помо́щниця і Засту́пниця нам, вопію́щим Тебі́:","Ра́дуйся, ві́рним утвержде́ніє і защище́ніє,","Ра́дуйся, неду́жним і немощни́м ісціле́ніє,","Ра́дуйся, вдов і сиро́т покро́в і соблюде́ніє,","Ра́дуйся, в ну́ждах су́щих вспоможе́ніє,","Ра́дуйся, лише́нія терп'я́щих дово́льством ісполне́ніє,","Ра́дуйся, ско́рбних ма́терей утіше́ніє,","Ра́дуйся, сиро́тствующих чад неви́димоє охране́ніє,","Ра́дуйся, прибіга́ющих к Тебі́ ско́роє посіще́ніє,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 13","ps":["О, Всеблага́я і Всемилосе́рдая Ма́ти, Пречи́стая Госпоже́ Богоро́дице, прийми́ моле́ніє сіє́, ни́ні Тебі́ приноси́моє, от нас грі́шних і недосто́йних рабо́в Твої́х, ко о́бразу Твоєму́, а́ки к Тебі́ Самі́й припа́дающих, при́зри ми́лостивно на ві́ру і упова́ніє на́ше, ізба́ви нас от бід і скорбе́й, пода́ждь нам ру́ку по́мощі в жи́зні сей і бу́дущия ізми́ му́ки, да спаса́ємі Тобо́ю ви́ну вопіє́м: аллилу́я, аллилу́я, аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов ли́ци сопредста́ша, Небе́сная Цари́це, о́крест святи́я іко́ни Твоєя́, благода́тію Тобо́ю просла́вленния. Тім же і ми, взира́юще на іко́ну Твою́, в боже́ственних хра́мах нас осіня́ющую, почита́єм ю, преклоня́єм колі́на пред вели́чеством Твої́м, Влади́чице, і уми́льно воспіва́єм си́це:","Ра́дуйся, Небе́сная Цари́це, Ма́ти Го́спода небесі́ і землі́,","Ра́дуйся, арха́нгелов і а́нгелов Влади́чице,","Ра́дуйся, го́рніх сил велича́ніє,","Ра́дуйся, челові́чеських ликостоя́ній похвале́ніє,","Ра́дуйся, пра́ведних душ сла́досте,","Ра́дуйся, живу́щих в Бо́зі умиле́ніє,","Ра́дуйся, о нас пред Бо́гом предста́тельнице,","Ра́дуйся, боже́ственния бла́гости пода́тельнице,","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Влади́чиці на́шей Богоро́диці, похва́льная пі́нія прино́сим Ті раби́ Твої́, я́ко честни́м о́бразом Твої́м ми́лости істо́чник стяжа́вшії, Ти же, Госпоже́, я́ко благосе́рдая Ма́ти, бу́ди неотсту́пна ми́лостію Твоє́ю от нас, да зове́м Ті:","Ра́дуйся, Милосе́рдая, ми́лости нам іко́ною явля́ющая."]},{"h":"Молитва","ps":["О, Всеми́лостивая Госпоже́ Ді́во Богоро́дице, усли́ши нас моля́щихся Тебі́, і яви́ нам ско́рую ми́лость Твою́, Моли́ Си́на Твоєго́ ізба́витися нам от вся́каго зла і сохрани́ лю́ди, благоче́стно прибега́ющия і призива́ющия і́м'я Твоє́ свято́є, от вся́кия напа́сти, всіх нас сохраня́ющи под кро́вом бла́гости Твоєя́, ри́зою Твоє́ю честно́ю защити́. При́зри на всіх нас призрі́нієм ми́лостиваго Твоєго́ заступле́нія і моли́твою Твоє́ю сподо́би нас со Христо́м жи́ти і ра́дості а́нгельськия в небе́сних селе́ніїх наслажда́тися. Ти бо єси́, Госпоже́, Сла́ва небе́сних і Упова́ніє земни́х. Ти на́ша Наде́жда і Засту́пниця всіх, притека́ющих к Тебі́ і Твоєя́ святи́я по́мощі прося́щих, тім же всечестни́й о́браз Твой і руко́ю Твоє́ю Держи́маго Вседержи́теля ви́дяще на іко́ні, ра́дуємся грі́шнії, со умиле́нієм припа́даєм і любо́вію сей цілу́єм, ча́юще, Госпоже́, Твої́ми богоприя́тними моли́твами в ми́рі і благоче́стії земни́й путь прейти́ і небе́сния безконе́чния жи́зні дости́гнути і Трисія́нному Бо́гу со всі́ми, угоди́вшими Єму́, поклоня́тися во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["От святи́я іко́ни Твоєя́, о Влади́чице Богоро́дице, / ісціле́нія і ці́льби подаю́ться оби́льно, / с ві́рою і любо́вію приходя́щим к ней. / Та́ко і мою́ не́мощ посіти́, / і ду́шу мою́ поми́луй, Блага́я, / і ті́ло ісціли́ благода́тію Твоє́ю, Пречи́стая."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Молченська»","e":"Akathist to the Theotokos before her icon “Molchensk”","secs":[{"h":"Кондак 1","ps":["Ізбра́нной от всіх родо́в Бо́жієй Ма́тері благода́рственная прино́сим пі́нія о явле́нії чу́дния Єя́ іко́ни, к Не́йже притека́ющії от бід, скорбе́й і болі́зней ско́роє при́ймуть ізбавле́ніє. О, небесе́ і землі́ Цари́це, бу́ди нам милосе́рдная Ма́ти, да любо́вію Твоє́ю во вся дні жи́зні на́шея охраня́ємі, вопіє́м Ті:","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць ізбра́ Тя, Влади́чице, спасе́нію послужи́ти ро́да челові́чеськаго. Ти же, на сла́вний і многоско́рбний сей жре́бій согла́сіє да́вши, плоть Свою́ воплоще́нію Си́на Бо́жия дарова́ла єси́. Ни́ні же предста́тельствуєши за нас пред Ним і ве́лію Твою́ ми́лость ізлива́єши чрез многочи́сленния іко́ни Твоя́ чудотво́рния. К єди́ній же от них, «Молче́нськой», припа́дающе, із глубини́ се́рдця взива́єм Ті:","Ра́дуйся, Свято́є селе́ніє Сло́ва Бо́жия;","Ра́дуйся, Сві́та Непристу́пнаго Вмісти́лище;","Ра́дуйся, Престо́ле Госпо́день превознесе́нний;","Ра́дуйся, ріше́нія Предві́чнаго Сові́та Ісполни́тельнице;","Ра́дуйся, Ка́мене домострої́тельства Бо́жия;","Ра́дуйся, Небе́снаго во́їнства Цари́це;","Ра́дуйся, Царя́ ца́рствующих Ма́ти;","Ра́дуйся, Но́вий Єде́ме, сла́внійший дре́вняго;","Ра́дуйся, Є́вино паде́ніє к восста́нію подви́гшая;","Ра́дуйся, рождество́м Свої́м главу́ змі́єву попра́вшая;","Ра́дуйся, дре́вней кля́тви разріше́ніє;","Ра́дуйся, Обітова́ніє гряду́щаго спасе́нія;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 2","ps":["Ви́дяще Тя, Богоро́дице, на іко́ні ди́вній Твоє́й, во об'я́тіях Си́на Бо́жия держа́щую, в десни́ці Твоє́й зрим лі́ствицю, і́же путеводи́тельство Твоє́ явля́єть. По ней же по́мощію Твоє́ю і моли́твами на не́бо восхо́дим, іді́же всі пра́веднії воспіва́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум немощни́й ізумля́ється, Богома́ти, єгда́ в зна́ціх, на дре́вней іко́ні Твоє́й явле́нних, тщи́ться об'я́ти глубину́ непостижи́мую служе́нія Твоєго́: одія́ніє бо Твоє́ я́ко із те́мних о́блак сотка́но, на десно́м ра́мене – світи́ло лу́нноє, на главі́ Твоє́й – лик со́лнечний, на пе́рсіх – дуга́ многоцве́тная. Див'я́ся сему́, в ізумле́нії вопіє́м Ті та́ко:","Ра́дуйся, Ковче́же Но́єв, наро́д святи́й Бо́гу спаса́ющий;","Ра́дуйся, Голуби́це, благу́ю вість в пото́пі жите́йстім погиба́ющим прине́сшая;","Ра́дуйся, Дуго́ многоцве́тная, обітова́ніє спасе́нія на́шего;","Ра́дуйся, Лі́ствице Іа́ковля, Є́юже сни́де Бог к лю́дем Свої́м;","Ра́дуйся, Купино́ Неопали́мая, огнь Божества́ неврежде́нно приі́мшая;","Ра́дуйся, Же́зле Моїсе́йов, в мо́ре жите́йстім путь спасе́нія указу́ющий;","Ра́дуйся, Мо́ре Чермно́є, по проше́ствії Ізра́їля непрохо́дно преби́вшеє;","Ра́дуйся, Живоно́сний істо́чниче, в пусти́ні напоя́ющий жа́ждущия;","Ра́дуйся, Ма́нно Небе́сная, при́сно пита́ющая мно́гих;","Ра́дуйся, Скрижа́ле, в Тебі́ бо Сло́во спасе́нія вообрази́ся;","Ра́дуйся, Ковче́же Заві́та одушевле́нний, Христа́-Законода́вця внутр носи́вший;","Ра́дуйся, Свята́я Святи́х несравне́нно бо́льшая;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 3","ps":["Си́лу разумі́нія Писа́ній пода́ти нам про́сим, Влади́чице, даби́ позна́ти, я́ко проро́ци дре́вле прореко́ша во о́бразіх мно́зіх прикрове́нную до вре́мені сла́ву Твою́, Богома́ти. Та́ко і ни́ні возсія́вши в іко́ні Твоє́й средь блать Молче́нських, о́браз нам явля́єши, я́ко да возсія́єть світ ми́лости Твоєя́, Влади́чице, средь бла́та гріхо́внаго душ на́ших, тім же возсла́вим Бо́га: Аллилу́я."]},{"h":"Ікос 3","ps":["І́маше промишле́ніє благо́є о лю́діх Твої́х, Богоро́дице, зрим у́бо, я́ко дре́вле прорече́нноє во проро́ціх, явля́єши ни́ні ко вразумле́нію на́шему в чудотво́рних іко́нах Твої́х. Ві́дуще сіє́, воспої́м Ті та́ко:","Ра́дуйся, Засту́пнице, предстої́ши бо Христу́, я́ко Цари́ця, злати́ми ри́зами доброді́телі оді́яна;","Ра́дуйся, Горо́ ту́чная, усире́нная Ду́хом, в Тебі́ бо благоволи́ пребива́ти Бог;","Ра́дуйся, Черто́же Ца́рський, Гра́де ізбра́нний, в нем же всели́ся Христо́с;","Ра́дуйся, Руно́ Гедео́ново, на Него́ же Дух Святи́й сшел єси́, я́ко дождь;","Ра́дуйся, Ізбра́ннице Бо́жия, о Тебі́ же дре́вле воспі́ Соломо́н: Вся добра́ єси́, Бли́жняя моя́;","Ра́дуйся, Ковче́же одушевле́нний, в Тебі́ бо Прему́дрость Бо́жия созда́ Себі́ дом;","Ра́дуйся, Вмісти́лище небеса́ми Невмісти́маго, о Тебі́ бо Іса́їя возопи́: Се, Ді́ва во чре́ві при́йметь;","Ра́дуйся, Же́зле процві́тшій, от Него́ же прозябе́ нам Цвіт небе́сний Христо́с;","Ра́дуйся, Ді́во, Ієзекі́їлем предрече́нная, Є́ю же, затворе́нній вни́де Бог;","Ра́дуйся, Колесни́це огнеобра́зная Су́щаго на херуви́міх;","Ра́дуйся, Кни́го запечатле́ная, в Ней же Пе́рстом Боже́ственим начерта́ся нам Сло́во Бо́жиє;","Ра́дуйся, Горо́ Несіко́мая, от Нея́ же Краєуго́льний Ка́мень отсіче́ся, Христо́с;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 4","ps":["Бу́рю напа́стей і ра́спрей воздвиза́ємую умири́ла єси́ засту́пничеством Твої́м, Богома́ти, єгда́ Лжедми́трій со іноплеме́нници злоумишля́л єсть в Пути́влі проти́в землі́ Ру́ськой. Та́ко ни́ні предста́тельством Твої́м умири́ мир, просвіти́ отступи́вших от Бо́га і разори́ сові́ти нечести́вих проти́ву Це́ркві Христо́вой. Да просла́вим Бо́га, дарова́вшаго такову́ю Засту́пницю, поя́ Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше словеса́ Твоя́, Богоро́дице, о первопи́санній іко́ні: С сим о́бразом благода́ть Моя́ і си́ла, с наде́ждой припа́даєм к святи́м іко́нам Твої́м і прославля́єм житіє́ Твоє́ та́ко:","Ра́дуйся, непло́дних богооте́ць Іоаки́ма і А́нни благоуха́нний пло́де;","Ра́дуйся, в храм зако́нний жи́ти приведе́нная і во Свята́я Святи́х, на обще́ніє А́нгелов введе́нная;","Ра́дуйся, путь ді́вства Присноде́вством Свої́м освяти́вшая;","Ра́дуйся, Благода́тная, благу́ю вість о рождестві́ Си́на Бо́жия от Арха́нгела получи́вшая;","Ра́дуйся, Благослове́нная в жена́х, ізбра́нничеством і смире́нієм Свої́м Бо́га на зе́млю низве́дшая;","Ра́дуйся, цілова́ніє Єлисаве́тино і взигра́ніє младе́нця єя́ я́ко проро́чество приі́мшая;","Ра́дуйся, кра́йнєє снисхожде́ніє Бо́жиє продолжи́ла єси́, во верте́пі Си́на Бо́жия ро́ждши і в я́сліх положи́вши Єго́;","Ра́дуйся, рождество́м Си́на Своєго́ А́нгелов возвесели́вшая;","Ра́дуйся, поклоне́ніє па́стирей і да́ри волхво́в Си́ну Бо́жию приі́мшая;","Ра́дуйся, скорбе́й, Симео́ном Тебі́ предрече́нних, не убоя́вшаяся;","Ра́дуйся, от зло́би І́рода со Младе́нцем Христо́м А́нгелом спасе́нная;","Ра́дуйся, явле́нієм Свої́м і́долов єги́петських сокруши́вшая;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ єсть лю́дем іко́на Твоя́, Богома́ти, явля́єши бо ся в ней Одиги́трієй, путь на не́бо нам указу́ющей. Мо́лим Тя, Преблага́я, укажи́ нам ца́рський путь ко спасе́нію, да ше́дше їм, воспої́м Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще, Богоро́дице, ди́вную іко́ну Твою́, я́ко щит в жите́йських брані́х нам да́нную, обраті́мся душе́ю к многоско́рбному і сла́вному путі́ Твоєму́ і воззри́м со смире́нієм на бі́ди і ско́рби на́ша, да наставле́нієм Твої́м усмо́трим в них Бо́жиє промишле́ніє, ко спасе́нію подава́ємоє. Разумі́вше же сіє́, воспої́м Ті та́ко:","Ра́дуйся, Си́на поте́ряннаго, в до́мі Отця́ – Хра́мі Бо́жиєм обрі́тшая;","Ра́дуйся, о преложе́нії води́ во вино́ на бра́кі в Ка́ні Си́на упроси́вшая;","Ра́дуйся, весь кре́стний путь Си́на Бо́жия до Голго́фи с Ним проше́дшая;","Ра́дуйся, Преблагослове́нная, апо́столов тве́рдостію Своє́ю превозше́дшая;","Ра́дуйся, Божество́ Си́на Своєго́ в сами́х му́ках Єго́ прозрі́вшая;","Ра́дуйся, пре́данность смотре́нію Бо́жию при Кресті́ Христо́вом яви́вшая;","Ра́дуйся, гріх распе́нших Си́на Твоєго́ любо́вію покри́вшая;","Ра́дуйся, весь род челові́чеський в лиці́ Іоа́нна Богосло́ва при Кресті́ усинови́вшая;","Ра́дуйся, пе́рвая от челові́к воскре́сшаго Го́спода узре́вшая;","Ра́дуйся, вознесе́ніє Го́спода зря́щи, прославле́нію челові́чества Єго́ возликова́вшая;","Ра́дуйся, по успе́нії своє́м ду́шу в ру́ці Си́на Своєго́ преда́вшая;","Ра́дуйся, я́ко по вознесе́нії своє́м на не́бо там предста́тельствуєши за нас;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 6","ps":["Пропове́дниками сла́ви Твоєя́, Богома́ти, в землі́ Су́мськой, яви́стася два і́нока, прине́сших іко́ну Твою́ во дні дре́внія із разоре́нних преді́лов Ки́євських на го́ру Чу́дную посреді́ блать Молче́нських. Ви́дящії же ту і уві́рившеся в чудотворе́ніїх єя́ возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ на Чу́дной го́ре благода́ть ве́лія, єгда́ по сме́рті і́ноков, іко́на Твоя́, Богоро́дице, бо́ртнику яви́ся, і, по велі́нію Твоєму́, на мі́сті явле́нія єя́ це́рков Рождества́ Богоро́диці лю́дем пути́вльським в ра́дость ве́лію основа́ся. С ни́ми же і вся Це́рков Правосла́вная славосло́віє прино́сить Ті таково́є:","Ра́дуйся, усе́рдно внима́вшая уче́нію Си́на своєго́;","Ра́дуйся, ві́рная Ісполни́тельнице діла́ Христо́ва;","Ра́дуйся, Благослове́нная, апо́стольський жре́бій прия́вшая;","Ра́дуйся, Хра́мі Бо́га Жива́го, Це́рков собо́ю прообрази́вшая;","Ра́дуйся, Сто́лпе і Утвержде́ніє І́стини, Це́ркве покро́в і заступле́ніє;","Ра́дуйся, Прему́дросте Бо́жия, ста́до Христо́во назида́ющая;","Ра́дуйся, Істо́чниче красоти́ церко́вния;","Ра́дуйся, хра́мов Бо́жиїх благоукраше́ніє;","Ра́дуйся, благода́ть і си́лу о́бразом свої́м сообща́ющая;","Ра́дуйся, благолі́пієм слу́жби церко́вния ісполня́ющая;","Ра́дуйся, благозву́чіє моли́твеннаго пі́нія благода́тію напоя́ющая;","Ра́дуйся, Се́рдце Це́ркве, отве́тную любо́в у ві́рних визива́ющая;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 7","ps":["Хотя́й бо́ртник ме́ду собра́ти, ви́ді на ві́твіх в сія́нії я́ко со́лнце іко́ну Твою́, Богома́ти. Сли́ша же глас: Да сози́ждеться на мі́сті сем це́рков Пресвяти́я Богоро́диці, мед і́стинний вмі́сто пчели́наго обрі́т, возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Новозда́нний храм на мі́сті явле́нія іко́ни Твоєя́, Богома́ти, мно́гих моля́щихся привле́кл єсть. Моли́твами же і по́двигами Софро́нієва пу́стинь во і́м'я Рождества́ Твоєго́, Влади́чице, основа́ся зді. І́ноці же оби́телі сей сла́в'яще Тя та́ко:","Ра́дуйся, от ми́ра отре́кшимся духо́вноє утіше́ніє да́рующая;","Ра́дуйся, во бранеіх духо́вних непобіди́мая Спобо́рнице;","Ра́дуйся, правосла́вних оби́телей благоустроє́ніє;","Ра́дуйся, трудо́в мона́шеських благопло́діє ізря́дноє;","Ра́дуйся, я́ко чу́дная іко́на Твоя́ на Чу́дной го́ре просла́вися;","Ра́дуйся, я́ко среди́ то́пи блать Молче́нських благода́ть Твоя́ ве́лія возсія́;","Ра́дуйся, я́ко ме́дом і́стинним бо́ртнику яви́вшися, ни́ні напоя́єши всіх;","Ра́дуйся, Софро́нієвой пу́стині основа́ніє;","Ра́дуйся, по разоре́нії пу́стині іко́ни Твоєя́ чу́дноє спасе́ніє;","Ра́дуйся, пути́вльськия оби́телі прему́дроє устроє́ніє;","Ра́дуйся, оби́телі Молче́нськия із руї́н чуде́сноє возста́ніє;","Ра́дуйся, землі́ Пути́вльськия Тверди́не і благослове́ніє;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до яви́ся, єгда́ діви́ця сліпа́я во ві́си Буси́новськой узрі́ Тя во сні, Влади́чице. Сли́шавши же сло́ва: Іди́ вдоль рі́ки і обря́щеши іко́ну Мою́, возста́ от сна, во́лю Твою́ іспо́лни. Обрі́тше же чу́дную іко́ну, в ра́дості возопи́: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся ісполня́я по сло́ву Твоєму́, Пречи́стая, по́йде діви́ця по бре́гу і обрі́те істо́чник, оми́вши о́чі, прозрі́. Посе́м до но́щі с усе́рдієм іска́ше діви́ця іко́ну Твою́, Богома́ти, і не узрі́. То́кмо на втори́й день сріто́ша іко́ну, із глубини́ душі́ возопи́ Ті та́ко:","Ра́дуйся, град Москву́ явле́нієм чу́дния іко́ни Твоєя́ посіти́вшая;","Ра́дуйся, ві́си Буси́новськой благослове́ніє і благоукраше́ніє;","Ра́дуйся, душ челові́чеських із мра́ка ізведе́ніє;","Ра́дуйся, духо́вних і тіле́сних оче́с прозрі́ніє;","Ра́дуйся, Живоно́сний Істо́чниче жизнь ві́чную істоча́ющая;","Ра́дуйся, кла́дезю Буси́новському си́лу благода́тную сообща́ющая;","Ра́дуйся, мно́гих оми́вшихся в нем ско́роє ісціле́ніє;","Ра́дуйся, Мо́ре благода́ті от іко́ни Твоєя́ істоча́ющая;","Ра́дуйся, Приста́нище жите́йськаго бу́рнаго пла́ванія;","Ра́дуйся, Звіздо́, озаря́ющая ду́ші на́ша;","Ра́дуйся, Не́бо, сія́нієм Сла́ви Госпо́дней іспо́лненноє;","Ра́дуйся, Горо́ висо́кая, в го́рняя ду́шу возводя́щая;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 9","ps":["Вся́коє і́стинноє утра́тив разумі́ніє, ні́ції от богоро́дичник, непра́во воздаю́ще почита́ніє Богоро́дице, нави́кли в храм Буси́новський ходи́ти, смуща́юще ста́до Христо́во, служи́телями же це́ркві вразумле́ни би́ша, оста́вили заблужде́ніє своє́, ві́рнії же возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї сі́ї многовіща́ннії, глаго́лють, я́ко Ді́ва Пречи́стая, а не Син Єя́, спаса́єть род челові́чеський. Сію́ хулу́ глаго́люще і та́їнств церко́вних не приє́млюще отріва́ють себе́ от Це́ркві Бо́жієй. Ми же, воздава́я честь Пречи́стій, іспові́дуєм Єя́ Ма́терію Христа́, Си́на Бо́жия, і я́ко Хода́тайце пред Ним за нас нави́кли честь Єй воздава́ти. Сего́ ра́ди восхваля́єм Пренепоро́чную та́ко:","Ра́дуйся, Дще́ре Ада́мова, ізбра́нничеством, послуша́нієм і чистото́ю Своє́й гріх перворо́дний обеспло́дившая;","Ра́дуйся, Непоро́чная, ли́чнаго гріха́ єди́ная із жен не імі́вшая;","Ра́дуйся, Пло́де Сладча́йший, в дар Го́споду от ро́да челові́чеськаго принесе́нний;","Ра́дуйся, Браконеїску́сная, наше́ствієм Ду́ха свята́го предочище́нная;","Ра́дуйся, плоть Свою́ Си́ну Бо́жию взаїмода́вшая;","Ра́дуйся, Прему́драя, непра́во почита́ющих Тя вразумля́ющая;","Ра́дуйся, Благода́тная, чудеси́ ди́вниє от іко́н Твої́х істоча́ющая;","Ра́дуйся, Милосе́рдная, інове́рцев, обраща́ющихся к Тебі́ не отверга́ющая;","Ра́дуйся, Преблага́я, проше́нія всіх ско́ро ісполня́ющая;","Ра́дуйся, Пресвята́я, всіх любо́вію Своє́ю покрива́ющая;","Ра́дуйся, Пресві́тлая, лжеучи́телей суєму́дренних вразумля́ющая;","Ра́дуйся, Чи́стая, коле́блющихся во ві́рі наставля́ющая і утвержда́ющая;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи род челові́чеський от скорбе́й і болі́зней, Богома́ти, ве́лію ми́лость і́маши к стра́ждущим младе́нцем, ві́домо бо єсть, я́ко пома́зани би́вше єле́єм от іко́ни Твоєя́ в це́ркві Буси́новськой, скорі́є получа́ху ізціле́ніє. Ма́тері же о́них воспева́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ крі́пкая, Богома́ти. Оби́телі Молче́нськой, і ве́сі Буси́новськой огра́да несокруши́мая. Сего́ ра́ди припа́дающе к чудотво́рной іко́ні Твоє́й с многоразли́чними скорб'я́ми свої́ми, вопіє́м Ті такова́я:","Ра́дуйся, жен нося́щих во чре́ві Храни́тельнице;","Ра́дуйся, стра́ждущих ро́жениць Разріше́ніє;","Ра́дуйся, младе́нцев Млекопита́тельниці;","Ра́дуйся, блага́я наста́внице ю́них;","Ра́дуйся, сиро́т Огра́до і ізря́дноє попече́ніє;","Ра́дуйся, Устрої́тельнице благи́х супру́жеств;","Ра́дуйся, семе́й благочести́вих Покрови́тельнице;","Ра́дуйся, в ско́рбіх жите́йських наде́жная Помо́щнице;","Ра́дуйся, вражду́ющих ско́роє примире́ніє;","Ра́дуйся, вдов і ма́терей одино́ких Заступле́ніє;","Ра́дуйся, в немощні́й ста́рости Опо́ро і Утіше́ніє;","Ра́дуйся, всі́ми отве́рженних Защище́ніє;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 11","ps":["Пі́нієм хвале́бним прославля́єм Тя всі, Богоро́дице, я́ко по вели́кому милосе́рдію Твоєму́, хули́телі ві́ри правосла́вния, оскверни́вше живоно́сний істо́чник Буси́новський, замишля́ли ума́лити сія́ніє сла́ви іко́ни Твоєя́, Влади́чице. Оба́че в за́мислі своє́м ніка́коже успі́ша, возросла́ бо єсть сла́ва Єя́ па́че пре́жняго. Ві́рнії же, ра́дующеся о сем, возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льници на́ша угасо́ша, зіло́ оскуде́ли єсть ми єле́ом ві́ри і доброді́телей, всу́є м'яте́мся в жи́зні сей вре́менній. К іко́ні же Твоє́й припа́дающе, си́лу ві́ри і наде́жду спасе́нія в Тебі́ обріта́єм. Сего́ ра́ди велегла́сно Ті вопіє́м:","Ра́дуйся, обурева́ємих жите́йською бу́рею Світи́льниче неугаси́мий;","Ра́дуйся, ми́ра м'яту́щагося умире́ніє;","Ра́дуйся, ро́да правосла́внаго Покрови́тельнице;","Ра́дуйся, прави́телей безу́мних вразумле́ніє і наказа́ніє;","Ра́дуйся, в ра́тних бра́ніх пра́вим Побо́рнице;","Ра́дуйся, правові́рних вожде́й і во́їнов воодушевле́ніє і Храни́тельнице;","Ра́дуйся, больни́х і уя́звленних ра́нами Ціли́тельнице;","Ра́дуйся, средь толп м'яте́жних су́щим Покро́ве і Огражде́ніє;","Ра́дуйся, ізгна́нних із домо́в свої́х Приста́нище;","Ра́дуйся, у кра́я бе́здни су́щих Спасе́ніє;","Ра́дуйся, ма́терем скорб'я́щим, усе́рдно моля́щимся Тебі́, заблу́дших діте́й Возвраще́ніє;","Ра́дуйся, отча́явшимся наде́жду спасе́нія подаю́щая;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 12","ps":["Благода́ть, возсія́вшая іногда́ посреді́ блать Молче́нських от ди́вния іко́ни Твоєя́, Богома́ти, преізлива́ється ни́ні во ві́си Буси́новськой і во всем гра́де Моско́вськом, зна́ємо бо єсть, я́ко сугу́бую благода́тную по́мощ і́муть от Тебе́ неду́гующії душе́вними болі́зньми і одержи́миє духа́ми нечи́стими. Ми же, лику́юще о сем, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще мно́жество благодія́ній Твої́х ро́ду челові́чеському, не уподо́бимся младе́нцем несми́сленним, да́рам матери́нським ра́дующимся, са́мую же ма́тер благодари́ти забива́ющим. Но іму́ще в Тебі́, Богоро́дице, красоти́ і любве́ сокро́вище неістощи́моє, воспої́м благода́рними усти́ Ті си́це:","Ра́дуйся, дарова́ньми благода́тними оби́льно украше́нная;","Ра́дуйся, усе́рдно притека́ющих к Тебі́ ще́дро одаря́ющая;","Ра́дуйся, ро́да челові́чеськаго упова́ніє;","Ра́дуйся, всея́ тва́рі Бо́жієй ча́яніє;","Ра́дуйся, одержи́мих духа́ми нечи́стими ісціле́ніє;","Ра́дуйся, вся потре́бная ко спасе́нію подаю́щая;","Ра́дуйся, отходя́щим в жизнь ві́чную ободре́ніє і заступле́ніє;","Ра́дуйся, непра́вих суде́й вразумле́ніє;","Ра́дуйся, стра́ждущих у́зников Защи́та і Утіше́ніє;","Ра́дуйся, стра́нствующих Путеводи́тельниця;","Ра́дуйся, зижди́телей тружда́ющихся блага́я Помо́щнице;","Ра́дуйся, песнотво́рцев богоуго́дних Вдохнове́ніє;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти, припа́дающе ни́ні к благода́тній іко́ні Твоє́й, про́сим Тя умоли́ти ми́лостиваго Бо́га: да спасе́ть погиба́ющий мир, поми́луєть страну́ на́шу Украї́нськую і нас, живу́щих в ней вразуми́ть і на путь пра́вий наста́вить, да воспоє́м Єму́ всі: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць ізбра́ Тя, Влади́чице, спасе́нію послужи́ти ро́да челові́чеськаго. Ти же, на сла́вний і многоско́рбний сей жре́бій согла́сіє да́вши, плоть Свою́ воплоще́нію Си́на Бо́жия дарова́ла єси́. Ни́ні же предста́тельствуєши за нас пред Ним і ве́лію Твою́ ми́лость ізлива́єши чрез многочи́сленния іко́ни Твоя́ чудотво́рния. К єди́ній же от них, «Молче́нськой», припа́дающе, із глубини́ се́рдця взива́єм Ті:","Ра́дуйся, Свято́є селе́ніє Сло́ва Бо́жия;","Ра́дуйся, Сві́та Непристу́пнаго Вмісти́лище;","Ра́дуйся, Престо́ле Госпо́день превознесе́нний;","Ра́дуйся, ріше́нія Предві́чнаго Сові́та Ісполни́тельнице;","Ра́дуйся, Ка́мене домострої́тельства Бо́жия;","Ра́дуйся, Небе́снаго во́їнства Цари́це;","Ра́дуйся, Царя́ ца́рствующих Ма́ти;","Ра́дуйся, Но́вий Єде́ме, сла́внійший дре́вняго;","Ра́дуйся, Є́вино паде́ніє к восста́нію подви́гшая;","Ра́дуйся, рождество́м Свої́м главу́ змі́єву попра́вшая;","Ра́дуйся, дре́вней кля́тви разріше́ніє;","Ра́дуйся, Обітова́ніє гряду́щаго спасе́нія;","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Кондак 1","ps":["Ізбра́нной от всіх родо́в Бо́жієй Ма́тері благода́рственная прино́сим пі́нія о явле́нії чу́дния Єя́ іко́ни, к Не́йже притека́ющії от бід, скорбе́й і болі́зней ско́роє при́ймуть ізбавле́ніє. О, небесе́ і землі́ Цари́це, бу́ди нам милосе́рдная Ма́ти, да любо́вію Твоє́ю во вся дні жи́зні на́шея охраня́ємі, вопіє́м Ті:","Ра́дуйся, О́бразе любве́ неізрече́нния, Пресвяти́я Тро́йці чи́стоє зерца́ло."]},{"h":"Молитва","ps":["О, Всеми́лостивая, человіколюби́вая Влади́чице на́ша Богоро́дице! Усли́ши сіє́ немощно́є моле́ніє с любо́вію і тре́петом припа́дающих к честні́й і сла́вній Молче́нськой іко́ні Твоє́й. Смире́нно про́сим Тя: бу́ди Стіна́ неруши́мая страні́ на́шей Украї́нській, святу́ю Це́рков Правосла́вную защити́ от неві́рія, єресе́й і раско́лов. Ти бо єси́ всеси́льная христия́н Засту́пниця. Вся́кую ду́шу, к Тебі́ прибіга́ющую, огради́ от зла́го обстоя́нія, ско́рби і болі́зні, удержи́ от паде́ній гріхо́вних, па́дших возста́ви к покая́нію, стра́ждущих душе́вними неду́гами і одержи́мих зли́ми духа́ми ісціли́, пода́ждь уходя́щим в жизнь ві́чную утіше́ніє і наде́жду спасе́нія, і вся потре́бная к благочести́вой жи́зні да́руй. Да сла́вим в Тро́йці Єди́наго Бо́га, Отця́, і Си́на, і Свята́го Ду́ха і Твоє́ ми́лостивноє предста́тельство, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь сві́тло красу́ється сла́вний град Москва́ і в Пути́влі ликова́ніє ве́ліє, я́ко честву́ють, Богома́ти, ди́вную іко́ну Твою́, ме́дом благода́ті всіх напоя́ющую."]},{"h":"Кондак, глас 6","ps":["Притеце́м, лю́діє, к Влади́чиці на́шей Ді́ві Богоро́диці, іко́ну бо Свою́ Молче́нськую нам дарова́, то́ки ісціле́ній істоча́ющую, вся́кую по́мощ в душе́вних і тіле́сних неду́зіх подаю́щую і к жи́зні ві́чной приводя́щую."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Утоли моя печалі»","e":"Akathist to the Theotokos before her icon “Soothe My Sorrows”","secs":[{"h":"Кондак 1","ps":["Взбра́нноє нам і ди́вноє ізбавле́ніє дарова́ся, Твой о́браз честни́й, Преблагослове́нная Ді́во Влади́чице Богоро́дице, я́ко ізба́вльшеся от злих явле́нієм єго́ і к нему́ взира́юще, воспису́єм Ті благода́рственная раби́ Твої́, Богоро́дице; но я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Ікос 1","ps":["А́нгел мно́жество і вся Небе́сная Во́їнства сла́в'ять Тебі́, Цари́цю всіх Богоро́дицю, Ти же іспо́лнила єси́ ра́дости ду́ші на́ша ми́лостивим явле́нієм нам о́браза Твоєго́ свята́го, Богоізбра́нная Ді́во Влади́чице, к нему́же кла́няющеся, Тебі́ умиле́нная моле́нія возсила́єм, милосе́рдому Твоєму́ к нам заступле́нію со стра́хом зову́ще такова́я:","Ра́дуйся, Отця́ Безнача́льнаго благослове́ніє;","ра́дуйся, Си́на Преві́чнаго жили́ще.","Ра́дуйся, Ду́ха Свята́го пребива́ніє;","ра́дуйся, я́ко Тебі́ сла́в'ять многоочи́тії херуви́ми.","Ра́дуйся, я́ко Тебі́ похва́льная прино́сять шестокрила́тії серафи́ми;","ра́дуйся, я́ко Тебі́ вся небе́сная во́їнства велича́ють.","Ра́дуйся, я́ко Тебі́ вся колі́на земна́я Ма́тер Бо́жию іспові́дують;","ра́дуйся, я́ко Тобо́ю вся вселе́нная весе́лія ісполня́ється.","Ра́дуйся, я́ко Тобо́ю вся болі́зні на́ша ісціля́ються;","ра́дуйся, Твої́ми бо моли́твами печа́лі на́ша утоля́ються.","Ра́дуйся, Твої́ми бо хода́тайстви вся проше́нія на́ша ісполня́ються;","ра́дуйся, я́ко Тебі́ і Си́ну Твоєму́ в Твоє́й честні́й іко́ні благода́рно поклоня́ємся.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 2","ps":["Ви́дять Тя, Богоізбра́нная Отрокови́це, вся небе́сния си́ли предстоя́щу всегда́ Престо́лу Сла́ви Небе́снаго Царя́ і за христия́ни к Си́ну і Бо́гу моля́щуюся, Небе́сная Цари́це; ми же грі́шнії на землі́, зря́ще Твою́ святу́ю іко́ну і к ней припа́дающе, Тебі́ ра́достно поклоня́ємся, зову́ще: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум пода́ждь нам, Всеусе́рдная Предста́тельнице на́ша, Небе́сная Цари́це, із уст бо нас скве́рних, ка́ко мо́щно пі́ти Твоєму́ і́мені? Я́ко благи́х єси́ нам Хода́тайця, сильна́ єси́ вспомоществова́ти во вся́кой на́ми тре́буємой по́мощі, да Тебі́ со умиле́нієм зове́м си́це:","Ра́дуйся, моли́тви о нас к Си́ну і Бо́гу во утіше́ніє принося́щая;","ра́дуйся, Твої́ми моли́твами о́чі на́ша от ві́чнаго рида́нія ізбавля́ющая.","Ра́дуйся, Твої́ми Ма́терніми моли́твами Си́на і Бо́га на ми́лость к нам приклоня́ющая;","ра́дуйся, Твої́ми моли́твами пра́ведний на нас гнів Бо́жий утоля́ющая.","Ра́дуйся, Твої́ми хода́тайстви гріхи́ на́ша проща́ющая;","ра́дуйся, Твоє́ю по́мощію стра́сті на́ша істребля́ющая.","Ра́дуйся, Твої́м предста́тельством вре́менная на́ша ско́рби разруша́ющая;","ра́дуйся, Ти во вся́ких біда́х і ну́ждах нам помога́ющая.","Ра́дуйся, Тя сла́в'ящих всегда́ прославля́ющая;","ра́дуйся, Твоє́ю ра́достію печа́лі на́ша утоля́ющая.","Ра́дуйся, непреста́нноє нам весе́ліє подава́ющая;","ра́дуйся, нам ра́йськія две́рі отверза́ющая.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ Тя к ско́рому і те́плому заступле́нію ві́рно притека́ющих к Тебі́ і честно́му Твоєму́ о́бразу поклоня́ющихся, єди́ній бо то́кмо Тебе́, нетлі́нній і Пречи́стій Богома́тері, даде́ся дар вся́коє благо́є на́ше проше́ніє ісполня́ти, і єди́на Ти мо́жеши нам помощі́, єли́ко хо́щеши. Тім всяк во́зраст славосло́вить Си́на Твоєго́ і Бо́га на́шего, зови́й: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи бога́тство милосе́рдія неоску́дноє, всім конце́м земни́м простира́єши руку́ по́мощі і подає́ши боля́щим ісціле́ніє, стра́ждущим осла́бу, сліпи́м прозрі́ніє і всім вся по потре́бі ісполня́єши. Ми же Тебі́ благода́рно си́це поє́м:","Ра́дуйся, єди́на Ма́ти, милосе́рдіє нам явля́ющая;","ра́дуйся, ми́лости сокро́вище многоці́нноє нам открива́ющая.","Ра́дуйся, безчи́сленния щедро́ти всім подава́ющая;","ра́дуйся, сло́во прему́дрости прося́щим да́рующая.","Ра́дуйся, преспі́яніє ра́зума ю́ним подава́ющая;","ра́дуйся, ра́ни на́ша гріхо́вния істребля́ющая.","Ра́дуйся, пра́ведних в ра́йських селе́ніїх насажда́ющая;","ра́дуйся, отча́янним бу́дущих благ Наде́ждо і Укріпле́ніє.","Ра́дуйся, всіх па́дших ско́ро к благода́ті возставля́ющая;","ра́дуйся, всім вся́кую тре́буємую от Тебе́ по́мощ подава́ющая.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 4","ps":["Бу́рею мно́гих бід одержи́мим нам всегда́ помога́єши, Небе́сная Цари́це, с ві́рою прибега́ющим к Тебі́ і поклоня́ющимся цільбоно́сній Твоє́й іко́ні, є́йже первопи́санній іногда́ рекла́ єси́: С сим о́бразом благода́ть Моя́ і си́ла. І ми і́стинно ві́руєм, я́ко послу́шаєши проше́нія призива́ющих і́м'я свято́є Твоє́ і Си́ну Твоєму́ зову́щих: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша Госпо́дь Твоя́ на небесі́ о нас хода́тайства, ізбра́нная Пала́то Ду́ха Свята́го, ісполня́єть Твоя́ проше́нія, ми же грі́шнії на землі́, ви́дівше святу́ю Твою́ іко́ну, я́ко світоза́рноє со́лнце нам світя́щуюся, Тебі́, я́ко Бо́жієй Ма́тері, дерза́єм глаго́лати:","Ра́дуйся, Со́лнце ми́сленноє нам явля́ющая;","ра́дуйся, Сві́том немерца́ющим нас просвіща́ющая.","Ра́дуйся, умерщвле́нних гріха́ми нас оживля́ющая;","ра́дуйся, непло́дним ма́терем ложесна́ разріша́ющая.","Ра́дуйся, неча́янно находя́щих на нас злих враго́в ско́ро прогоня́ющая;","ра́дуйся, жела́ємих благ всегда́ нас наслажда́ющая.","Ра́дуйся, ско́ро в біда́х і в печа́ліх нас утіша́ющая;","ра́дуйся, ві́рою і́м'я Твоє́ призива́ющих от неча́янния сме́рті спаса́ющая.","Ра́дуйся, на Тя упова́ющим безконе́чний живо́т да́рующая;","ра́дуйся, ві́ру і любо́в к Тебі́ іму́щих к небесі́ возводя́щая.","Ра́дуйся, Предста́тельство на́ше крі́пкоє;","ра́дуйся, во вся́ких обстоя́тельствах нас защища́ющая.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́, честну́ю Твою́ іко́ну, Ти нам показа́ла єси́, Влади́чице ми́ра, к не́йже ми зря́ще і ві́рою серде́чною моля́щеся, Тебі́, Богоро́дице, глаго́лем: Ти єси́ нам щит непобіди́мий і стіна́ необори́мая, вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша си́ли небе́сния на руку́ Твоє́ю Созда́вшаго Свої́ма рука́ма челові́ки і Влади́ку разуміва́юще Єго́; ми же грі́шнії на землі́, зря́ще ізображе́нную Тебе́, Пречи́стую Ма́тер Єго́, любе́зно Свої́ ру́ці к нам простира́ющую, к Тебі́ уми́льно зове́м:","Ра́дуйся, на руку́ Твоє́ю Огнь Боже́ственний неопа́льно держа́щая, І́мже гріхи́ на́ша попаля́ються;","ра́дуйся, на руку́ Твоє́ю Сві́та Неприкоснове́ннаго носи́вшая, І́мже ду́ші на́ша просвіща́ються.","Ра́дуйся, враго́в на́ших ви́димих і неви́димих побіжда́ющая;","ра́дуйся, любо́в і милосе́рдіє к нам явля́ющая.","Ра́дуйся, ру́ці Твої́ в поруче́ніє о нас к Бо́гу принося́щая;","ра́дуйся, вход в Ца́рствіє Небе́сноє нам отверза́ющая.","Ра́дуйся, Твоє́ю по́мощію нас защища́ющая;","ра́дуйся, Твої́м хода́тайством гріхи́ на́ша проща́ющая.","Ра́дуйся, Твої́м моле́нієм печа́лі на́ша утоля́ющая;","ра́дуйся, я́ко Твої́м предста́тельством вся́ких благ наслажда́ємся.","Ра́дуйся, я́ко Тобо́ю вся во благи́х жела́нія на́ша ісполня́ються,","ра́дуйся, я́ко во́лю Си́на Твоєго́ твори́ти нас подвиза́єши.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 6","ps":["Пропові́дници Богоно́снії апо́столи, по вознесе́нії Госпо́дні, при освяще́нії хра́ма Твоєго́, неви́димою руко́ю ізображе́нний шаро́вними подо́бії на стіні́ обрі́тше о́браз Твой, Влади́чице, рожде́нному от Тебе́ Бо́гу воспі́ша: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ прему́дростію от І́стиннаго Со́лнця Пра́вди, Богоізбра́нная Отрокови́це, і, лучи́ і́стиннаго Богоразу́мія іспуща́ющи, ті́ми освіща́єши всіх ві́рою іспові́дающих Тя і́стинную Ма́тер Бо́жию би́ти, вопію́щих си́це:","Ра́дуйся, всіх на небесі́ сла́вою Твоє́ю просвіща́ющая;","ра́дуйся, нача́ло челові́чеськаго спасе́нія устроя́ющая.","Ра́дуйся, ковче́же жи́зні на́шея, от пото́па сме́ртнаго нас сохраня́ющий;","ра́дуйся, в ра́йських селе́ніїх жи́ти нам да́рующая.","Ра́дуйся, Предста́тельнице на́ша к Бо́гу, мир спаса́ющая;","ра́дуйся, в біда́х су́щих ско́ро заступа́ющая.","Ра́дуйся, вся́кия болі́зні челові́чеськія, тіле́сния і душе́вния, ісціля́ющая;","ра́дуйся, німи́м і косноязи́чним словеса́ отверза́ющая.","Ра́дуйся, вся́каго бла́га прося́щим у Тебе́ пода́тельнице;","ра́дуйся, уче́ніє благода́ті всім істоча́ющая.","Ра́дуйся, тім вся́кий чин і во́зраст дово́льно услажда́ющая;","ра́дуйся, всіх блага́я жела́нія ісполня́ющая.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 7","ps":["Хотя́ долготерпіли́вий Всеви́дець Госпо́дь яви́ти Своєго́ человіколю́бія і щедро́т бе́здну, ізбра́ Тебі́ Себе́ в Ма́тер, ми́лости неісчерпа́ємий істо́чниче, да а́ще кто пра́ведним судо́м Бо́жиїм осужде́нія досто́їн, Твої́м всемо́щним хода́тайством сохране́н бу́деть і Си́ну Твоєму́ і Бо́гу на́шему велегла́сно зове́ть: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вна показа́л єси́ діла́ Твоя́ в Пречи́стій Ма́тері Твоє́й, Го́споди, і ди́вну дарова́л єси́ нам Єя́ іко́ну, па́че луче́й со́лнечних просвіща́ющую люде́й, я́ко Са́мую зря́щих Богоро́дицю і ві́рою серде́чною от душі́ любо́вію вопію́щих такова́я:","Ра́дуйся, іко́ну Твою́ на землі́, я́ко о́блак, всім распростира́ющая;","ра́дуйся, то́ю па́че наді́янія милосе́рдоє к нам заступле́ніє явля́ющая.","Ра́дуйся, Твоє́ю іко́ною істо́чники чуде́с всю́ду істоча́ющая;","ра́дуйся, явле́нієм Твоєя́ іко́ни вся лю́ди просвіща́ющая.","Ра́дуйся, то́ю но́воє зна́меніє благода́ті в Це́ркві явля́ющая;","ра́дуйся, я́ко, на іко́ну Твою́ взира́юще, Само́й Тебі́, і́стинній Богоро́дице, поклоня́ємся.","Ра́дуйся, іко́ною Твоє́ю, я́ко столпо́м о́гненним, мрак гріха́ отгоня́ющая;","ра́дуйся, то́ю печа́лі на́ша утоля́ющая.","Ра́дуйся, Це́рков освяти́вшая тоя́ явле́нієм;","ра́дуйся, я́ко ми, грі́шнії, сохраня́ємся Твої́м заступле́нієм.","Ра́дуйся, вре́тище ско́рби на́шея растерза́ющая;","ра́дуйся, ві́чною ра́достію нас одіва́ющая.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 8","ps":["Стра́нну і пресла́вну в Це́ркві я́вльшуюся святу́ю Твою́ іко́ну а́нгели воспі́ша, апо́столи просла́виша, лик святи́телей поклони́шася, ми же, грі́шнії, припа́дающе, ожида́єм Твоєя́ вели́кия і бога́тия ми́лости, с весе́лієм вопію́ще: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі́ми ви́шніми і ни́жніми влади́чествуяй Госпо́дь, ви́дів Тя, Ма́тер Свою́, всегда́ предстоя́щу Єму́ і со умиле́нієм Єму́ принося́щу моле́ніє о нас грі́шних, обіща́ іспо́лнити вся проше́нія Твоя́. Ми же, грі́шнії, наді́ющеся на Твоя́ Ма́тернія о нас моли́тви, благода́рственная Тебі́ прино́сим си́це:","Ра́дуйся, с Си́ном Твої́м і Бо́гом ві́чно ца́рствующая;","ра́дуйся, Єму́же всегда́ о нас моле́нія принося́щая.","Ра́дуйся, всіх к Тебі́ прибіга́ющих Твоє́ю ми́лостію покрива́ющая;","ра́дуйся, всіх Ра́досте, печа́лі на́ша утоля́ющая.","Ра́дуйся, примире́ніє на́ше с Бо́гом соді́лавшая;","ра́дуйся, Бо́га і челові́ка соєдини́вшая.","Ра́дуйся, спасе́ніє челові́чеськоє устро́ївшая;","ра́дуйся, прароди́тельнаго гріха́ кля́тву разруши́вшая.","Ра́дуйся, сме́ртноє на́ше єстество́ безсме́ртієм просвіти́вшая;","ра́дуйся, жесто́кость се́рдця на́шего умили́вшая.","Ра́дуйся, отча́янних к Бо́гу возводя́щая;","ра́дуйся, сосу́ди сме́ртния, на нас угото́ванния, сокруши́вшая.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє похва́льния пі́сні прино́сить Тебі́, Бо́жієй Ма́тері і Засту́пнице всіх припа́дающих Тебі́ і прося́щих Твоєя́ по́мощі, я́ко тве́рдим і крі́пким Твої́м предста́тельством пра́ведних весели́ши, грі́шних заступа́єши і от бід ізбавля́єши, і печа́лі утоля́єши, і мо́лишися о всіх ві́рою зову́щих: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́ннії, я́ко ри́би безгла́сния, недоумі́ють хвали́ти сла́вний, Влади́чице, іко́ни Твоєя́ пра́здник, ніже́ от скве́рних усте́н на́ших приноси́мия Ті похвали́ досто́йни, оба́че неісче́тная благодія́нія, іко́ною Твоє́ю нам явля́ємая, ви́дівше, душе́ю і се́рдцем ра́дующеся, Тебі́ глаго́лем:","Ра́дуйся, от гла́да нас Хлі́бом жи́зні пита́ющая;","ра́дуйся, от губи́тельства сме́ртнаго безсме́ртієм нас соблюда́ющая.","Ра́дуйся, от тру́са гріхо́внаго нас сохраня́ющая;","ра́дуйся, от пото́па сме́ртнаго руко́ю Твоє́ю крі́пкою нас ізбавля́ющая.","Ра́дуйся, от огня́ росо́ю моли́тв Твої́х нас восхища́ющая;","ра́дуйся, от бід си́льним Твої́м предста́тельством нас защища́ющая.","Ра́дуйся, от меча́ си́лою Твоє́ю нас охраня́ющая;","ра́дуйся, от наше́ствія іноплеме́нник нас спаса́ющая.","Ра́дуйся, от междоусо́бния бра́ні і́стинним ми́ром нас огражда́ющая;","ра́дуйся, от смертоно́сния ра́ни прибіга́ющих к Тебі́ ісціля́ющая.","Ра́дуйся, от належа́щаго пра́веднаго преще́нія Бо́жия Твої́м моле́нієм нас свобожда́ющая;","ра́дуйся, от вся́кия нас я́зви Твої́м честни́м хода́тайством ізима́ющая.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ род челові́чеський от пре́лести вра́жия, Человіколю́бець Госпо́дь Тебе́, Ма́тер Свою́, дарова́ земни́м на по́мощ, глаго́ля: си́нове челові́честії, се Ма́ти Моя́ покро́в і прибі́жище вам да бу́деть, печа́льним утіше́ніє, скорб'я́щим ра́дованіє, оби́димим засту́пниця, да всіх із глубини́ гріхо́вния воздви́гнеть, вопію́щих: Аллилу́я."]},{"h":"Ікос 10","ps":["Царю́ Небе́сний, — та́ко мо́лить за ни всегда́ Небе́сная Цари́ця, — прийми́ вся́каго челові́ка, сла́в'ящаго Тя і призива́ющаго і́м'я Твоє́, іді́же бива́єть па́м'ять свято́му і́мені Твоєму́, і прославля́ющих М'я іме́не Твоєго́ ра́ди, і не отри́ни їх от лиця́ Твоєго́, но благоволи́ в них і прийми́ от них вся́коє моле́ніє, і всіх от бід ізба́ви. Ми же, грі́шнії, наді́ющеся на Твоя́ Ма́тернія моли́тви, зове́м си́це:","Ра́дуйся, Моли́твеннице на́ша к Бо́гу те́плая;","ра́дуйся, я́ко Твоя́ Ма́терняя моли́тва мно́го мо́жеть, Влади́ку умилостивля́ющи.","Ра́дуйся, отча́янних Наде́ждо, печа́лі їх утоля́ющая;","ра́дуйся, Твоє́ю благода́тію на́ше недосто́їнство осіява́ющая.","Ра́дуйся, на́шу скве́рну Твоє́ю чистото́ю очища́ющая;","ра́дуйся, моле́нія на́ша Твої́м благоуха́нієм ісправля́ющая.","Ра́дуйся, бре́ніє на́ше тлі́нноє в нетлі́ніє обраща́ющая;","ра́дуйся, неможе́ніє на́ше врачу́ющая.","Ра́дуйся, вся на́ша болі́зні душе́вния і тіле́сния ісціля́ющая;","ра́дуйся, наше́дший на нас о́блак страсте́й, скорбе́й і печа́лей ско́ро разгоня́ющая.","Ра́дуйся, си́льним Твої́м проше́нієм вся поле́зная да́рующая;","ра́дуйся, пред Престо́лом Си́на Твоєго́ за моля́щих Ті ся хода́тайствующая.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прийми́ от нас, Небе́сная Цари́це, і моли́тву, приноси́мую Тебі́, Ді́во Богоро́дице, усли́ши, к Тебі́ бо в напа́стіх, ско́рбіх і печа́ліх прибіга́єм і пред Тобо́ю в біда́х на́ших сле́зи пролива́єм і мо́лим: утоли́ на́ша печа́лі і прийми́ сію́ же́ртву Твої́х рабо́в, зову́щих: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мная свіща́ і́стиннаго Сві́та су́щим на землі́ я́вльшися, ду́ші просвіща́єши чту́щих Твоєя́ іко́ни явле́ніє і к ра́зуму боже́ственному наставля́єши пою́щих Ті сицева́я:","Ра́дуйся, свіще́ неугаси́мая Огня́ невеще́ственнаго, нас просвіща́ющая;","ра́дуйся, заре́ незаходи́маго Сві́та Боже́ственнаго, нас озаря́ющая.","Ра́дуйся, Со́лнце пра́вди нам явля́ющая;","ра́дуйся, Істо́чник жи́зні ра́йськия нам істоча́ющая.","Ра́дуйся, Ма́ти Сві́та І́стиннаго, благочести́вих ду́ші просвіща́ющая;","ра́дуйся, Ма́ти всіх Бо́га, озло́бленних всіх ду́ші утіша́ющая.","Ра́дуйся, Тя на по́мощ призива́ющих і і́м'я Твоє́ сла́в'ящих спаса́ющая;","ра́дуйся, упова́ющим на Тя живота́ непости́дний коне́ць да́рующая.","Ра́дуйся, всім родо́м, Тя Ма́тер Бо́жию почита́ющим і Богоро́дицю імену́ющим, непреста́нно помога́ющая;","ра́дуйся, осіне́нієм святи́я Твоєя́ іко́ни злих духо́в мечта́нія от нас прогоня́ющая.","Ра́дуйся, во внеза́пних на нас находя́щих ско́рбіх і печа́ліх ско́ро нас утіша́ющая;","ра́дуйся, всему́ ми́ру ра́дость да́рующая.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственную іспроси́ нам у Небе́снаго Влади́ки, Си́на Твоєго́ і Бо́га, і простри́ нам руку́ по́мощі, і моли́твами Твої́ми утоли́ на́ша печа́лі, покри́й нас кро́вом крилу́ Твоє́ю, отжени́ от нас вся́каго врага́ і супоста́та, умири́ на́шу жизнь, да не поги́бнем лю́ті, но прийми́ нас во ві́чния кро́ви, Покрови́тельнице на́ша, да, ра́дующеся Тебі́, зове́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Тя, держа́вную Помо́щницю, хва́лим Тя і, моля́щеся Тебі́ со умиле́нієм, ві́руєм і іспові́дуєм, я́ко іспро́сиши блага́я вре́менная і ві́чная воспіва́ющим Ті:","Ра́дуйся, моли́твами Твої́ми весь мир спаса́ющая;","ра́дуйся, всю вселе́нную хода́тайством Твої́м заступа́ющая.","Ра́дуйся, правосла́вним на ва́рвари побі́ди подава́ющая;","ра́дуйся, наше́ствія на христия́ни іноплеме́нних побіжда́ющая.","Ра́дуйся, во ві́рі благочести́вия сохраня́ющая;","ра́дуйся, не почита́ющих іко́ни Твоя́ святи́я, я́ко прах, от лиця́ землі́ развіва́ющая.","Ра́дуйся, поклоня́ющимся іко́ні Твоє́й і Тя на по́мощ призива́ющим, і в печа́ліх бе́дствующим ско́ро помога́ющая;","ра́дуйся, нас грі́шних ко спасе́нію і восприя́тію благ ві́чних наставля́ющая.","Ра́дуйся, безконе́чнаго ца́рствія у Си́на Твоєго́ і Бо́га на́шего всім нам іспроша́ющая;","ра́дуйся, ві́рним безконе́чную жизнь да́рующая.","Ра́дуйся, всім во вся́кой потре́бі вся поле́зная і блага́я подава́ющая;","ра́дуйся, нетлі́нная стяжа́ти науча́ющая.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, Небе́сная Цари́це і Влади́чице, Ді́во Богоро́дице, ро́ждшая всіх святи́х Святі́йшеє Сло́во, ни́нішнєє приє́мши приноше́ніє, утоли́ на́ша печа́лі і ізба́ви нас от вся́ких напа́стей, бід, скорбе́й і ві́чнаго осужде́нія і гряду́щаго ізми́ муче́нія, і сподо́би нас, рабо́в Твої́х, во ві́чних ра́йських селе́ніях водвори́тися, зову́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел мно́жество і вся Небе́сная Во́їнства сла́в'ять Тебі́, Цари́цю всіх Богоро́дицю, Ти же іспо́лнила єси́ ра́дости ду́ші на́ша ми́лостивим явле́нієм нам о́браза Твоєго́ свята́го, Богоізбра́нная Ді́во Влади́чице, к нему́же кла́няющеся, Тебі́ умиле́нная моле́нія возсила́єм, милосе́рдому Твоєму́ к нам заступле́нію со стра́хом зову́ще такова́я:","Ра́дуйся, Отця́ Безнача́льнаго благослове́ніє;","ра́дуйся, Си́на Преві́чнаго жили́ще.","Ра́дуйся, Ду́ха Свята́го пребива́ніє;","ра́дуйся, я́ко Тебі́ сла́в'ять многоочи́тії херуви́ми.","Ра́дуйся, я́ко Тебі́ похва́льная прино́сять шестокрила́тії серафи́ми;","ра́дуйся, я́ко Тебі́ вся небе́сная во́їнства велича́ють.","Ра́дуйся, я́ко Тебі́ вся колі́на земна́я Ма́тер Бо́жию іспові́дують;","ра́дуйся, я́ко Тобо́ю вся вселе́нная весе́лія ісполня́ється.","Ра́дуйся, я́ко Тобо́ю вся болі́зні на́ша ісціля́ються;","ра́дуйся, Твої́ми бо моли́твами печа́лі на́ша утоля́ються.","Ра́дуйся, Твої́ми бо хода́тайстви вся проше́нія на́ша ісполня́ються;","ра́дуйся, я́ко Тебі́ і Си́ну Твоєму́ в Твоє́й честні́й іко́ні благода́рно поклоня́ємся.","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Кондак 1","ps":["Взбра́нноє нам і ди́вноє ізбавле́ніє дарова́ся, Твой о́браз честни́й, Преблагослове́нная Ді́во Влади́чице Богоро́дице, я́ко ізба́вльшеся от злих явле́нієм єго́ і к нему́ взира́юще, воспису́єм Ті благода́рственная раби́ Твої́, Богоро́дице; но я́ко іму́щая держа́ву непобіди́мую, от вся́ких нас бід свободи́, да зове́м Ті:","Ра́дуйся, Ра́досте на́ша, ізба́ви нас от вся́каго зла і утоли́ на́ша печа́лі."]},{"h":"Молитва","ps":["Ді́во Влади́чице Богоро́дице, па́че єстества́ і сло́ва роди́вшая Єдоноро́дноє Бо́жиє Сло́во, Творця́ і Влади́ку всея́ тва́рі ви́димия і неви́димия, Єди́наго от Тро́йці Бо́га, Бо́га же і Челові́ка, соде́лавшаяся оби́тель Божества́, вмісти́лище вся́кия святи́ні і благода́ті, в не́мже благоволе́нієм Бо́га і Отця́, соді́йствієм Свята́го Ду́ха, тіле́сні обита́ше полнота́ Божества́, несравне́нно превознесе́нная боголі́пним досто́їнством і прейму́ществующая пред вся́кою тва́рію, сла́во і утіше́ніє, і неізрече́нноє весе́ліє а́нгелов, ца́рственний ві́нче апо́столов і проро́ков, преєсте́ственноє і чу́дноє му́жество му́чеников, побо́рнице в по́двизіх і пода́тельнице побі́ди, уготовля́ющая подви́жником вінці́ і воздая́нія ві́чная і боголі́пная, преви́сшая вся́кия че́сти, честь і сла́во преподо́бних, непогріши́тельная путеуказа́тельнице і наста́внице безмо́лвія, две́ре открове́ній і духо́вних та́їн, істо́чниче сві́та, врата́ ві́чния жи́зні, неістощи́мая ріко́ милосе́рдія, неісчерпа́ємоє мо́ре всіх боголі́пних дарова́ній і чуде́с! Тя про́сим і Тя умоля́єм, сострада́тельнійшую Ма́тер человіколюби́ваго Влади́ки: будь ми́лостива к нам, смире́нним і недосто́йним рабо́м Твої́м, воззри́ благосе́рдно на пліне́ніє і смире́ніє на́ше, уврачу́й сокруше́нія душ і тіле́с на́ших, разсі́й ви́димия і неви́димия враги́, бу́ди нам, недосто́йним, пред лице́м враго́в на́ших крі́пкий столп, бра́нноє ору́жіє, си́льноє ополче́ніє, Воєво́да і непреобори́мая побо́рниця, покажи́ ни́ні на нас дре́внія і чу́дния ми́лості Твоя́, да позна́ють беззако́ннії враги́ на́ші, я́ко Син Твой і Бог Єди́н єсть Цар і Влади́ка, я́ко Ти воі́стину Богоро́диця, роди́вшая по пло́ті і́стиннаго Бо́га, я́ко вся Тебі́ возмо́жна суть і є́же а́ще восхо́щеши, Влади́чице, і́маши си́лу все сіє́ соверши́ти на небесі́ і на землі́, і на вся́коє проше́ніє дарова́ти коєму́ждо на по́льзу: больни́м здра́віє, су́щим на мо́рі тишину́ і до́броє кораблепла́ваніє. Путеше́ствующим спутеше́ствуй і охраня́й їх, плі́нния спаса́й от го́ркаго ра́бства, утіша́й печа́льния, облегча́й нищету́ і вся́коє друго́є тіле́сноє злострада́ніє; всіх свобожда́й от душе́вних неду́гов і страсте́й, неви́димими Твої́ми предста́тельстви і внуше́ньми, я́ко да, до́брі і непреткнове́нно соверши́в путь сея́ вре́менния жи́зні, улучи́м Тобо́ю і о́ная ві́чная блага́я в Ца́рствії Небе́снім.","Ві́рних, почте́нних стра́шним і́менем Єдиноро́днаго Си́на Твоєго́, упова́ющих на Твоє́ предста́тельство і на ми́лость Твою́ і во всем іму́щих Тя хода́таїцю і побо́рницю, укрепля́й неви́димо проти́ву обстоя́щих враго́в, разсі́й о́блак уни́нія, ізба́ви я от душе́внаго утружде́нія і пода́й їм сві́тлоє благоду́шіє і ра́дость, і обнови́ мир і безм'яте́жіє в сердця́х їх.","Спаси́ моли́твами Твої́ми, Влади́чице, сію́ Тебі́ посвяще́нную па́ству, весь град і страну́ от гла́да, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нних і междоусо́бния бра́ні і вся́кий пра́ведно подви́гшийся на нас гнів обрати́, по благоволе́нію і благода́ті Єдиноро́днаго Си́на і Бо́га Твоєго́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, с Сове́чним і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Наде́ждо всіх конце́в землі́, Пречи́стая Ді́во, Госпоже́ Богоро́дице, утіше́ніє моє́! Не гнуша́йся мене́, грі́шнаго, на Твою́ бо ми́лость упова́ю: угаси́ мі пла́мень гріхо́вний і покая́нієм ороси́ ізсо́хшеє моє́ се́рдце, очи́сти ум мой от гріхо́вних помисло́в, прийми́ мольбу́, от ду́ші і сердця́ со воздиха́нієм приноси́мую Тебі́. Бу́ди о мні Хода́тайця к Си́ну Твоєму́ і Бо́гу і укроти́ гнів Єго́ ма́терніми Твої́ми моли́твами, душе́вния і тіле́сния я́зви ісціли́, Госпоже́ Влади́чице, утоли́ болі́зні ду́ші і ті́ла, утиши́ бу́рю злих нападе́ній вра́жеських, отими́ бре́м'я гріхо́в мої́х, і не оста́ви мене́ до конця́ поги́бнути, і печа́лію сокруше́нноє се́рдце моє́ уті́ши, да сла́влю Тя до послі́дняго іздиха́нія моєго́. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Утоли́ болі́зні / многовоздиха́ющия душі́ моєя́, / Утоли́вшая вся́ку слезу́ от лиця́ землі́, / Ти бо челові́ков болі́зні отго́ниши / і грі́шних ско́рби разруша́єши, / Тебі́ бо всі стяжа́хом наде́жду і утвержде́ніє, // Пресвята́я Ма́ти Ді́во."]},{"h":"Кондак, глас 6","ps":["Не вві́ри м'я челові́чеському предста́тельству, / Пресвята́я Влади́чице, / но прийми́ моле́ніє раба́ Твоєго́, / скорб бо обдержи́ть м'я, / терпі́ти не могу́ де́монськаго стріля́нія, / покро́ва не і́мам, / ніже́ гді прибі́гну окая́нний / всегда́ побіжда́єм, / і утіше́нія не і́мам, ра́зві Тебе́, Влади́чице ми́ра, / упова́ніє і предста́тельство ві́рних, / не пре́зри моле́ніє моє́, // поле́зно сотвори́."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Козельщанська»","e":"Akathist to the Theotokos before her icon “Kozelshchyna”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній Влади́чице і Засту́пнице ро́да христия́нськаго, зна́меніями чуде́с ди́вних от святи́я Своєя́ іко́ни в страні́ на́шей возсія́вшей, благода́рственная і умиле́нная пі́нія немо́лчно принося́ще, я́ко Ма́тері Госпо́дней, в печа́ліх на́ших і болі́зніх вопіє́м:","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Ікос 1","ps":["Арха́нгели і А́нгели, Херуви́ми і Серафи́ми і вся Небе́сния Си́ли, зря́ще Тя на небесі́ і на землі́, я́ко неісчерпа́ємий істо́чник благода́тних ісціле́ній, непреста́нно сла́в'ять Тя, Присноблаже́нная Богоро́дице; ми же, грі́шнії, на землі́, помина́юще ди́вноє зна́меніє ми́лости Твоєя́, є́же в сія́ послі́дняя времена́ яви́ла єси́ в цільбоно́сній іко́ні, наслі́дії предко́в дражайшем, от літ дре́вніх із ро́да в род преходящем, ублажа́єм Тя си́це:","Ра́дуйся, Небе́сная Цари́це, Честні́йшая Херуви́м і Сла́внійшая без сравне́нія Серафи́м;","ра́дуйся, от всіх родо́в на землі́ похвала́ми ублажа́ємая.","Ра́дуйся, одесну́ю Си́на Твоєго́ і Бо́га предстоя́щая;","ра́дуйся, ко Го́споду Спа́су всіх нас приводя́щая.","Ра́дуйся, я́ко во ви́димом о́бразі Твоє́м неви́димую си́лу благода́ті обріта́єм;","ра́дуйся, я́ко на Твоє́ предста́тельство все упова́ніє на́ше возлага́єм.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 2","ps":["Ви́дящи Тя, Благосе́рдая Ма́ти, в пречу́дній іко́ні Твоє́й, я́коже су́щую с на́ми, стра́ждущая в неісцельном неду́зі діви́ця Марі́я со слеза́ми і ві́рою об'ят іко́ну Твою́, лобиза́ющи ю і ча́ющи от Тебе́ вели́кия ми́лости. Ті́мже, ісціле́ніє улучи́вши, а́біє велегла́сно возопи́ к Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́н іму́ще, роди́телі ісцелевшия всім лю́дем пропові́даша о чудеси́, явленном от святи́я іко́ни сея́, да всі притека́ють к ней с ві́рою і, приє́млюще ско́рая ісціле́нія, просла́в'ять Тя, взива́юще:","Ра́дуйся, Ма́ти Бо́жия, проше́нія боля́щих приє́млющая;","ра́дуйся, Ма́ти милосе́рдія, от оче́с сле́зи стра́ждущим отирающая.","Ра́дуйся, Всеми́лостивая, спасе́ніє лю́дем от Спа́са явля́ющая;","ра́дуйся, Всеще́драя, Свої́ми щедро́тами нас одаряющая.","Ра́дуйся, я́ко Тобо́ю душа́м на́шим утіше́ніє обріта́єм;","ра́дуйся, я́ко во успе́нії Твоє́м зало́г безсме́ртія уразумеваєм.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 3","ps":["Си́лою Ду́ха Бо́жия води́ма Марі́я, ісціле́ніє улучи́вши, с ра́достію ве́лією взят святу́ю іко́ну ро́дную і во град Москву́ ко отцю́ і враче́м ту́ю принесе́ во свиді́тельство їм, да не сокри́т бу́деть новоявле́нний істо́чник благода́тних ісціле́ній. Мно́жество же наро́да, уві́дівше, к предивней іко́ні с ві́рою прихожда́ху і ісціле́ніє неду́гов свої́х неісці́льних прийма́ху, благода́рно взива́юще ко Го́споду Сил: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи вседрагую іко́ну Твою́, Влади́чице, я́ко дар благода́тний, ра́дости іспо́лнися оби́тель Козельщанськая, на го́рнім мі́сті моли́твою, пото́м, скорбми́ і слеза́ми созда́нная; зря́щи бо на ру́ку Твоє́ю Богомладе́нця, Крест всечестни́й в десни́ці Своє́й воздвиза́юща, ча́шу же і лжи́цю близ Того́ предлежа́щу, с тре́петом лобиза́єть святи́ню Твою́, взива́ющи согла́сно:","Ра́дуйся, Одиги́тріє, ко оби́телем Го́рнім путь открива́ющая;","ра́дуйся, святу́ю оби́тель на́шу в жили́ще Себе́ на землі́ устро́ївшая.","Ра́дуйся, Крест Си́на Своєго́, я́ко ору́жіє о́строє в се́рдці Твоє́ восприя́вшая;","ра́дуйся, всім на землі́ Крест Христо́в на ся вземшим понести́ облегча́ющая.","Ра́дуйся, іночеству, оби́тель Твою́ возлюби́вшему, смисл до́браго житія́ дарова́вшая;","ра́дуйся, ча́шу терпі́нія і во гла́ді пита́ніє єму́ благосе́рдно наві́ки прине́сшая.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 4","ps":["Бу́ря ве́лія іногда́ укроти́ся сему́ о́бразу Твоєму́, ше́ствующу по Ру́ському мо́рю ко Оте́честву на́шему, і всі во́їни христолюби́вії благода́тно от потопле́нія спасо́шася. Ті́мже і ми, сицева́го явле́нія помина́ніє творя́ще, в бу́рі житія́ на́шего ру́ку по́мощі се́ю іко́ною Твоє́ю получи́ти тщі́мся, Си́ну же Твоєму́ і Бо́гу вопіяти дерза́єм: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шим мно́жество чуде́с, от іко́ни Твоєя́ явля́ємих, я́ко і всі конці́ землі́ ко Твоєму́ покро́ву, не то́кмо ві́рнії, но і чужді́ї ві́рі правосла́вной со стра́хом і упова́нієм к Тебі́, Богоро́дице, ру́ці свої́ простира́ють і, припа́дающе ко Твоєму́ благосе́рдію, славосло́вія Ті сицева́я возсила́ють:","Ра́дуйся, ума́ на́шего просвіще́ніє;","ра́дуйся, се́рдця на́шего умиле́ніє.","Ра́дуйся, ві́ру крі́пкую в нас утвержда́ющая;","ра́дуйся, на спасе́нія стезі́ заблу́ждших обраща́ющая.","Ра́дуйся, в покая́нії грі́шних ободря́ющая;","ра́дуйся, і са́мих отча́янних наде́ждою спасе́нія увеселя́ющая.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 5","ps":["Бо́гом просла́вленную іко́ну Твою́, я́ко живоно́сний істо́чник святи́ні почита́юще, прибіга́єм к Тебі́ во храм Твой благолі́пний, во сла́ву Твою́, Премилосе́рдая Ма́ти, созда́нний: прийми́ зді, я́коже кади́ло благово́нноє, проше́нія всіх нас, да благода́рні воспоє́м благоді́ющему Тобо́ю Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше неоску́дноє чуде́с ізлія́ніє, от іко́ни Твоєя́ явля́ємоє, правосла́внії лю́ди потща́шася дарми́ послужи́ти Тебі́, Преблагослове́нная, і вмі́сто ку́щи ма́лия, в не́йже пе́рвіє іко́на Твоя́ водвори́ся, честни́й храм Тебі́ от древе́с сложи́ша, посліди́ же і сей дом, небесі́ подо́бний, Тебі́ воздвиго́ша. Таково́му усе́рдію люде́й Твої́х, ві́ру неослабную к Тебі́ іму́щих, ра́дующеся, непреста́нно глаго́лати Тебі́ дерза́єм:","Ра́дуйся, страну́ Полтавськую сві́том ві́ри озари́вшая;","ра́дуйся, явле́нієм чуде́с от святи́я Твоєя́ іко́ни всіх увеселившая.","Ра́дуйся, горо́ благода́ті небе́сния, на го́рнім мі́сті оби́тель Твою́ утверди́вшая;","ра́дуйся, киво́те святи́ні небе́сния, во хра́мі созда́нном жили́ще Себі́ восприя́вшая.","Ра́дуйся, Боже́ственная трапе́зо і ста́мно злата́я, небе́сною ма́нною всіх напита́вшая;","ра́дуйся, лі́ствице висо́кая, путь земни́м к небесі́ показа́вшая.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 6","ps":["Пропові́дуєть мир весь вели́чіє Твоє́, Богома́ти, сла́вить Тя найпа́че же страна́ Украї́нськая немо́лчно; лику́єть оби́тель свята́я Твоя́, святи́телей лик воспіва́єть Тя при́сно, мона́си і мирсті́ї к іко́ні Твоє́й припа́дають; хор земноро́дних согла́сно взива́єть: не забу́ди всіх нас, Всепі́тая Ді́во, мир ми́рові да́руй і в ско́рбіх обра́дуй, всім ра́дость посли́ і во́плю воньми́; да воззове́м всі с небожительми ку́пно Небе́сному Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́, я́ко світ от небе́с, оби́тель Твоя́, Присноді́во Влади́чице Чи́стая, вели́коє бо мно́жество преди́вних чуде́с явля́єши Ти: се о́трок недви́жим диха́нієм ві́ри жизнь прояви́; та́мо сліпе́ць Іоа́нн не преста́ вопіяти: «Да́руй мі, Ма́ти моя́, да очи́ма прозрю́», - і світ от Тебе́ сліпоту́ єго́ озари́. Притека́єм у́бо і ми к чудотво́рній іко́ні Твоє́й, вопію́ще:","Ра́дуйся, тве́рдая і необори́мая на́ша Засту́пнице;","ра́дуйся, ро́да христия́нськаго всемо́щная Защи́тнице.","Ра́дуйся, градо́в і ве́сей покро́в і огражде́ніє;","ра́дуйся, оби́телей святи́х благослове́ніє і утвержде́ніє.","Ра́дуйся, я́ко пред свято́ю іко́ною Твоє́ю зна́менія чуде́с созерца́єм;","ра́дуйся, я́ко на Твоє́ предста́тельство все упова́ніє своє́ возлага́єм.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 7","ps":["Хотя́щим враго́м оби́тель Твою́ утеснити і і́нокинь ста́до, о Христі́ любо́вію со́бранноє, враждой порази́ти, ско́ро позна́ша сі́ї Твоє́ заступле́ніє, стіно́ю необоримою Твоє́ю обстої́ми. І ми с ві́рою взира́єм в гряду́щую даль віко́в і време́н, благода́рно вопію́ще Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно і дони́ні прославля́ється свята́я іко́на Твоя́, Влади́чице, зна́меньми ісціле́ній, от нея́ явля́ємих. Ти бо, Пречи́стая, бі́сния ісціля́єши, хроми́м да́руєши хожде́ніє, сліпи́м прозрі́ніє, расслабленним крі́пость і си́лу і всяк неду́г в лю́діх по ві́рі врачу́єши. І ми, ви́дяще чудеса́ сія́ і сте́кшеся в храм Твой, благолі́пієм чи́стим сія́ющий, мо́лим Тя неотсту́пно:","Ра́дуйся, всім призива́ющим Тя, ско́ро гото́вая по́моще;","ра́дуйся, пресла́вній оби́телі Твоє́й, всім стра́ждущим і скорб'я́щим сві́тлая ра́досте.","Ра́дуйся, я́ко в іко́ні Твоє́й чудотворя́щей зало́г ми́лости ві́чния обріта́єм;","ра́дуйся, я́ко Твоє́ю благодеющею си́лою в житії́ своє́м путь к небесі́ улуча́єм.","Ра́дуйся, всіх немощни́х ду́хом і ті́лом врачевство́ ві́рноє;","ра́дуйся, всіх скорб'я́щих і обремене́нних облегче́ніє всеблаго́є.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє ви́дим та́їнство, я́ко ди́вная і ужа́сная яви́ла єси́ во оби́телі Твоє́й, о неісчерпа́ємая в чудесі́х Свої́х Благости́ня! Єгда́ воу́тріє предпра́зднества Твоєго́ Вхожде́нія во храм Госпо́день приведо́ша сестри́ іноки́ню Параске́ву, зіло́ разсла́бленну, ко Твоєму́ пречи́стому о́бразу, і сію́ укріпи́ла єси́ во мгнове́нії о́ка, дарова́вши єй си́лу і движе́ніє омертвелому соста́ву єя́ тілесе́, і сподо́бися та за Боже́ственною слу́жбою Святи́х Та́їн причасти́тися, посліди́ же, ісходя́щи, воспі́т со мно́жеством люде́й, би́вших во хра́мі, хвалу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всяк земноро́дний да взигра́ється ду́хом просвіща́єм і освящаєм от цільбоно́сния святи́ні Твоєя́, Ра́досте на́ша і Похвало́, да не умолчи́ть нікогда́ си́ли Твоя́ глаго́лати, а́ще і недосто́їн єсть пред вели́чеством сла́ви Твоєя́; сего́ ра́ди і ми пресла́вная глаго́лем о Тебі́, неізглаго́ланная Та́йно; прийми́ сицеви́я от нас, я́ко от глуби́н ду́ха на́шего возноси́мия хвали́ і благодаре́нія:","Ра́дуйся, Храни́тельнице на́ша в настоя́щем ві́ці;","ра́дуйся, Предста́тельнице на́ша в бу́дущем.","Ра́дуйся, же́стокость і окамене́ніє се́рдця на́шего любо́вію Своє́ю ум'ягча́ющая;","ра́дуйся, чи́стим і благи́м се́рдцем познава́ти Тя науча́ющая.","Ра́дуйся, я́ко стра́сті на́ша Тобо́ю побіжда́єм;","ра́дуйся, я́ко жа́ло гріхо́вноє стра́стію Си́на Твоєго́ і Бо́га в себі́ умерщвля́єм.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ челові́чеськоє удиви́ся пресла́вному чудеси́, явле́нному іспе́рва, посліди́ же і всім явле́нним і явля́ємим зді і на вся́цім мі́сті от святи́я іко́ни Твоєя́, Преблагослове́нная Ма́тер Живота́, я́ко вся́ку похвалу́ от землі́ превосхо́дить небе́сная сла́ва Твоя́: не то́чію землі́ на́шея, но і іни́х стран любому́дріє і врачевство́ преклоня́ються смире́нні і че́стне пред вели́чеством непостижи́мия та́йни ісціле́ній, от Твоєя́ си́ли істоча́ємих. І ми, грі́шнії, в неду́зіх і ско́рбіх отягченнії, не ві́ми іни́я на землі́ Засту́пниці, ні благи́я Уті́шительниці, то́кмо Тебі́, о Богома́ти, і ко Твоєму́ благосе́рдію припа́дающе, во умиле́нії се́рдця за премно́гую ми́лость к нам, недосто́йним, возсила́єм Бо́гу ми́лующему і спаса́ющему всіх нас Тобо́ю: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не возмо́жеть досто́йно воспі́ти Тя, о Всепі́тая Ма́ти, всему́ ми́ру і страні́ на́шей во святи́ні іко́н Твої́х неісчисли́мая зна́менія і чудеса́ я́вльшую; ми же, просвіща́ємії сія́нієм такови́я сла́ви і бога́тством ми́лостей Твої́х недосто́їнству на́шему, непреста́нно тщі́мся хвалу́ Ті возда́ти моле́нії си́ми:","Ра́дуйся, Цари́це Небесе́ і землі́, Престо́лу Госпо́дню предстоя́щая;","ра́дуйся, Засту́пнице ві́чная, Христа́ за ни умоляющая.","Ра́дуйся, Ма́ти чадолюби́вая, всіх охраня́ющая;","ра́дуйся, заблу́ждших от путі́ і́стини к покая́нію призива́ющая.","Ра́дуйся, Молебнице те́плая, Судію́ всіх умилостивля́ющая;","ра́дуйся, вход во оби́телі ві́чния кающимся открива́ющая.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 10","ps":["Спасти́ хотщи ізбра́нную Бо́гом страну́ і прибегающия к Тебі́ лю́ди, ди́вно просла́вила єси́, Богома́ти Пречи́стая, іко́ну Твою́ Козельщанськую промислительними зна́меньми ми́лостей Твої́х всебогатих. А́ще бо Ти не би предстоя́ла моля́щи о нас, кто би ни ізба́вил от толи́ких бід, кто би сохрани́л ни до ни́ні свобо́дні? Ність числа́ чудесе́м Твої́м, Всеблага́я, не отсту́пим, Влади́чице, от Тебе́. Да́руй ни́ні і при́сно всім нам зрі́ти своя́ прегріше́нія, откри́й в нас істо́чники слез, да оми́єм паде́ніє в бе́здни гріхо́вния і, позна́вше Твоєго́ милосе́рдія неізслі́димую бе́здну, возста́нем і порабо́таєм, пою́ще к небесе́м просла́вльшему Тя Всемогу́щему Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ крі́пкая оби́телі Твоє́й, я́коже і всему́ ми́ру, огражда́ющая нас от враго́в досажде́нія, ві́рою і любо́вію чту́щих Тя, честно́му о́бразу Твоєму́ покланя́ющихся і принося́щих те́плі благодаре́нія такова́я:","Ра́дуйся, чистоти́ ді́вства і цілому́дрія се́рдця ревни́телей в любо́в Своєго́ се́рдця приє́мшая;","ра́дуйся, печа́ль і оби́ду от ми́ра в Небе́сную ра́дость по ві́рі преложшая.","Ра́дуйся, вдов і сиро́т заступле́ніє;","ра́дуйся, дома́шніх церкве́й охране́ніє.","Ра́дуйся, сла́сти земни́я презира́ти нас науча́ющая;","ра́дуйся, преходя́щия бла́га ми́ра гріхо́внаго ні во что́же вміня́ти побужда́ющая.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 11","ps":["Пі́ніє арха́нгельськоє умиле́нно прино́сим Ті, Богоро́дице Ді́во: «Ра́дуйся, Благода́тная Марі́є, Госпо́дь с Тобо́ю, благослове́нна Ти в жена́х!» - оба́че і та́ко вели́чія сла́ви Твоєя́ об'яти не мним: висота́ бо єси́ неудобовосходи́мая челові́чеському по́мислу і глубина́ неудобозри́мая і а́нгельському очеси́. Кий язи́к восхва́лить Тя, ко́є сло́во возвели́чить? Познава́я у́бо такови́я не́мощі на́ша, тре́петно вопіє́м рожде́нному от Тебе́ Боже́ственному Сло́ву: Аллилу́я."]},{"h":"Ікос 11","ps":["Я́ко світоно́сная свіща́, яви́ся свята́я іко́на Твоя́, Влади́чице і Ма́тер Сві́та, світ благода́ті небе́сній всім ізлія́вшая, пред не́юже ми благогові́йно предстоя́ще, взива́єм Ті: ізба́ви гра́ди і ве́сі, до́ми і ни́ви на́ша от вся́каго вре́да і зла, да со благодаре́нієм непреста́нно воспоє́м Ті:","Ра́дуйся, уда́ри гро́ма і мо́лнії от нас отводя́щая;","ра́дуйся, от сухости, гра́да, че́рв'я і іни́я па́губи вертогра́ди і ни́ви на́ша спаса́ющая.","Ра́дуйся, от о́гненнаго запале́нія і зловрі́дних пові́трій нас ороша́ющая;","ра́дуйся, от гла́да і сме́рті напра́сния нас свобожда́ющая.","Ра́дуйся, путьшествующим по су́ші і мо́рю вспоможе́ніє крі́пкоє;","ра́дуйся, язв душевре́дних і болі́зней тіле́сних врачева́ніє ві́рноє.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 12","ps":["Благода́ть Твою́ сви́ше пода́ждь нам, Богоблагода́тная Ді́во; до послі́дніх дній ми́ра святу́ю оби́тель Твою́ сохрани́; восхотевшим в ней жи́ти путь добр к небесі́ укажи́; любо́в і терпі́ніє со стра́хом Госпо́днім стяжа́ти в сердця́х умудри́, да со А́нгели і всі́ми святи́ми воспою́ть Преві́чному Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м чудеса́ Твоя́, от святи́я іко́ни пред всі́ми явле́нная, велича́єм Пода́теля вся́чеських Бо́га, дарова́вшаго в ней толи́коє всім утіше́ніє: боля́щим ісціле́ніє, скорб'я́щим ра́дованіє, ни́щим по́мощ, окова́нним свобо́ду, м'ятущимся ду́хом упова́ніє бо́дроє, слабим во ві́рі укріпле́ніє тве́рдоє; зрим начерта́ніє кро́ткаго ли́ка Твоєго́ і об'ятаго любо́вію Твоє́ю, Богома́ти, Богомладе́нця Христа́, лобиза́єм свяще́нния знаки страда́ній Єго́ за гріхи́ всего́ ми́ра - Крест і Ча́шу Святу́ю - і покланя́ємся непостижним та́йнам є́же от Тебе́ рождества́, непобіди́мия си́ли Креста́ і світоза́рнаго всім Воскресе́нія і воспіва́єм Ті ві́чную сла́ву:","Ра́дуйся, во сла́ві присідя́щая Си́ну Твоєму́ на Престо́лі Небе́снім;","ра́дуйся, прера́дованная Ма́ти Царе́ва, мир христия́нський под ві́чний покро́в Свой любо́вію об'явшая.","Ра́дуйся, уповающим на Тя коне́ць живота́ непости́ден даю́щая;","ра́дуйся, безболі́зненну і ми́рну кончи́ну ві́рним Бо́гу до сме́рти низпосила́ющая.","Ра́дуйся, в мита́рствах возду́шних душе́ челові́честій путь к Судії́ указу́ющая;","ра́дуйся, взивающим к Тебі́ до конця́ живота́ красоту́ ві́чния жи́зні я́ві явля́ющая.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 13","ps":["О Всепі́тая Ма́ти, Боже́ственная сла́во і красото́ небесе́ і землі́, неісчерпа́ємоє чуде́с мо́ре, засту́пнице і храни́тельнице ро́да христия́нськаго і святи́я оби́телі Твоєя́, прийми́ недосто́йноє сіє́, оба́че благода́рноє от сокруше́ннаго се́рдця возноси́моє к Тебі́ моле́ніє; яви́ нам до конця́ Ма́тернєє Твоє́ милосе́рдіє: в ско́рбі і напа́сти не оста́ви нас си́рих і в час сме́ртний Твої́м те́плим предста́тельством прича́стники ві́чнаго блаже́нства сотвори́, да, пам'яту́юще ви́ну Твоя́ ди́вная о нас заступле́нія, со всі́ми святи́ми не преста́нем воспіва́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгели і А́нгели, Херуви́ми і Серафи́ми і вся Небе́сния Си́ли, зря́ще Тя на небесі́ і на землі́, я́ко неісчерпа́ємий істо́чник благода́тних ісціле́ній, непреста́нно сла́в'ять Тя, Присноблаже́нная Богоро́дице; ми же, грі́шнії, на землі́, помина́юще ди́вноє зна́меніє ми́лости Твоєя́, є́же в сія́ послі́дняя времена́ яви́ла єси́ в цільбоно́сній іко́ні, наслі́дії предко́в дражайшем, от літ дре́вніх із ро́да в род преходящем, ублажа́єм Тя си́це:","Ра́дуйся, Небе́сная Цари́це, Честні́йшая Херуви́м і Сла́внійшая без сравне́нія Серафи́м;","ра́дуйся, от всіх родо́в на землі́ похвала́ми ублажа́ємая.","Ра́дуйся, одесну́ю Си́на Твоєго́ і Бо́га предстоя́щая;","ра́дуйся, ко Го́споду Спа́су всіх нас приводя́щая.","Ра́дуйся, я́ко во ви́димом о́бразі Твоє́м неви́димую си́лу благода́ті обріта́єм;","ра́дуйся, я́ко на Твоє́ предста́тельство все упова́ніє на́ше возлага́єм.","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Кондак 1","ps":["Ізбра́нній Влади́чице і Засту́пнице ро́да христия́нськаго, зна́меніями чуде́с ди́вних от святи́я Своєя́ іко́ни в страні́ на́шей возсія́вшей, благода́рственная і умиле́нная пі́нія немо́лчно принося́ще, я́ко Ма́тері Госпо́дней, в печа́ліх на́ших і болі́зніх вопіє́м:","Ра́дуйся, ско́рая Уті́шительнице і Ціли́тельнице, любо́в Свою́ і милосе́рдіє нам явля́ющая."]},{"h":"Молитва","ps":["О, Пресвята́я Ді́во Влади́чице Богоро́дице, добропослу́шная Боже́ственному Сло́ву, Ма́ти Пречи́стая от всіх родо́в ізбра́нная, на Небесі́ і на землі́ ублажа́ємая, прийми́ і сіє́ благодаре́ніє на́ше і всеблагогове́йноє поклоне́ніє чудотво́рній іко́ні Твоє́й ю́же я́ко многоціле́бний істо́чник Твоєя́ благода́ті благоізво́лила єси́ яви́ти страні́ на́шей правосла́вній і святі́й оби́телі сей. Арха́нгельський глас вопіє́м Ті; Чи́стая, — Обра́дованная, ра́дуйся, с Тобо́ю Госпо́дь і Тобо́ю с на́ми! Предста́тельством Твої́м і заступле́нієм на Небесі́ у Престо́ла Всеблага́го Бо́га нікто́же да ізи́деть отсю́да упова́нія своєго́ тощ і неусли́шан. О, Пречу́дная і ви́сшая всіх тва́рей небе́сних і земни́х Богома́ти Ді́во, благода́рні помина́я пресла́вная чудеса́ от свята́го о́браза Твоєго́ дарова́нная, мо́лим Тя, Всеблага́я, не лиши́ от него́ і нас ди́внаго зна́менія во спасе́ніє на́ше. Пом'яни́ щедро́ти Твоя́ дре́внія, в судьба́х Оте́чества на́шего явле́нная, і да преста́нем всі от лука́вств свої́х і́миже прогні́вахом Тя во вік сей м'яте́жний удале́нієм от любве́ є́юже возлюби́ і возрасти́ нас Це́рков Свята́я. О, Прему́драя Небе́сная Началоводи́тельнице ко спасе́нію і́нокинь оби́телі і́менем Твої́м нарече́нной ю́же ізбра́ла єси́ в достоя́ніє Своє́ на мі́сті сем Тобо́ю благослове́ннем, яви́ ю приста́нище ти́хоє всім скорб'я́щим і обремене́нним і ча́ющим блаже́нния ві́чния жи́зні. Грі́шнії єсьми́, Пренепоро́чная Влади́чице, но Твої́ до ві́ка. Озари́ у́бо ду́ші на́ша сві́том Боже́ственная благода́ті Твоєя́, покри́й нас от вся́каго зла, ско́рби і печа́лі: огради́ от вся́кия напа́сти, клевети́ челові́чеськія і наві́та вра́жия; немощни́м і боля́щим здра́віє да́руй; ка́ющихся грі́шников прости́ і от плі́на страсте́й свободи́; отступи́вшия от правосла́вния ві́ри і поги́бельними єресьми́ осліпле́нния сві́том богопозна́нія просвіти́ і Святі́й Апо́стольстій Це́ркві причти́. Мо́лим Тя, умиле́нно, сохрани́ і поми́луй па́стирей Це́ркві Правосла́вния і всіх ві́рних чад єя́; утверди́ житіє́ на́ше в ми́рі; упра́ви путі́ і сові́ти на́ша в пра́вді, во є́же откри́тися в них Ца́рству Христо́ву: да́руй нам кончи́ну христия́нськую, безболі́знену, непости́дну, ми́рну, Боже́ственних Та́їн прича́стну, і Сама́ нам в час той предста́ни і спаси́ посреди́ мита́рств возду́шних от мра́ка і ско́рби лю́тия; в стра́шний же день Суда́ сподо́би ни ста́ти одесну́ю Си́на Твоєго́ Христа́ Бо́га на́шего. Мо́лим Тя, Ді́во Всепі́тая, при́зри благосе́рдієм Твої́м на оби́тель сію́ і сохрани́ ю до ві́ка ці́лу і неврежде́нну, да ви́ну чистото́ю возвиша́ється і сла́виться в ней вели́чество Єдиносу́щния Тро́йці і Твоє́ препі́тоє і преблагослове́нноє і́м'я во ві́ки. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Весели́ся, земле́ Полта́вськая / і все оте́чество на́ше правосла́вноє: / се бо я́ко світоза́рноє со́лнце, / яви́ся пречу́дная іко́на Твоя́, Преблагослове́нная Богома́ти, / мир озаря́ющи мно́жеством чуде́с Твої́х, / ті́ми у́бо обріта́єм, я́же на землі́, вся блага́я і поле́зная, / і су́щих, я́же на Небесі́, сокро́вищ сподобля́ємся. / Сего́ ра́ди вопіє́м Ті: / ра́дуйся, Похвало́ на́ша приснопокланя́ємая, / спаси́ ни, моля́щіяся Тебі́, // єди́ная Наде́ждо і Ра́дованіє ві́чноє пою́щих Тя."]},{"h":"Кондак, глас 3","ps":["Боголі́пно во смире́нії красу́ється оби́тель Красного́рськая, / осіня́ємая і спаса́ємая преди́вним о́бразом Влади́чиці Пречи́стия, / Небесе́ і землі́ Цари́ці Богоро́диці, / от него́же істо́чники благода́ті і ча́ша чуде́с оби́льно ізлива́ються, / і усе́рдно притека́ющії ісціле́нія ві́рою приє́млють, / і неві́рнії ві́рою крі́пкою сердца́ ісполня́ють / і ми, раби́ Твої́, Богома́ти, благода́рні вопіє́м Ті: // ра́дуйся, Предста́тельство христия́н непости́дноє і оби́телі Твоєя́ красото́ і ра́дованіє."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Свенська»","e":"Akathist to the Theotokos before her icon “Svensk”","secs":[{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Пресвяті́й Ді́ві Марі́ї Богоро́дице, я́ко воі́стину пло́тію ро́ждшей Ісу́са Христа́, Спа́са і Бо́га на́шего, Влади́чице всея́ Вселе́нния, ізбравшей втори́м земни́м жре́бієм страну́ на́шу Украї́нськую і оби́телі іноческиє чудотво́рними іко́нами прославившей, похва́льноє прино́сим пі́ніє; Ти же, о Всечестна́я на́ша Ма́ти і Засту́пниця, храни́ оби́тель Твою́ (сію́) і спаси́ всіх нас от враг ви́димих і неви́димих да зове́м Ті:","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Ікос 1","ps":["А́нгел Храни́тель внуши́ кня́зю Рома́ну, єгда́ той бисть во гра́ді Брянске, вспом'янути о чудесі́х от іко́ни Твоєя́, Влади́чице, во оби́телі Пече́рстій би́вших, да іспро́сить і́ноков Пече́рських отпусти́ти іко́ну чудотво́рную, писанную преподо́бним Алипієм, ісціле́нія ра́ди сліпоти́ своєя́ і возопи́ Ті та́ко:","Ра́дуйся, Всечестна́я на́ша Ма́ти;","Ра́дуйся, ди́вная на́ша Засту́пнице;","Ра́дуйся, Наде́ждо на́шего спасе́нія;","Ра́дуйся, гра́да Брянська Храни́тельнице;","Ра́дуйся, живу́щих в нем христия́н Покрови́тельнице;","Ра́дуйся, наді́ющихся на Тя, Руководи́тельнице;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 2","ps":["Ви́дящи ісціле́нія, получаємиє с ві́рою і любо́вію упова́ющими на Тя і усли́шав о явле́нії іко́ни Твоєя́ на дре́ві, на горі́ Свенстей стоя́щей, ю́же обріто́ша і́ноці, князь Рома́н устреми́ся к мі́сту явле́нія єя́ і возопи́ Бо́гу: Аллилуя."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний приведе́ кня́зя Рома́на к мі́сту явле́нія іко́ни Твоєя́, Влади́чице, і вознесе́ горячую моли́тву пред не́ю, князь Рома́н, получи́в ісціле́ніє очесе́м свої́м, созда́ ту оби́тель, собра́ і́ноки і вку́пі с ни́ми возопи́ Тебі́:","Ра́дуйся, іко́ну Твою́ чудеса́ми просла́вившая;","Ра́дуйся, Свенськую оби́тель є́ю же просла́вила єси́;","Ра́дуйся, но́вий Свой уді́л на Свени возлюби́ла єси́;","Ра́дуйся, я́ко в ней іко́ну Твою́ чудотво́рную яви́ла єси́;","Ра́дуйся, ди́вни і вели́ки чудеса́ от нея́ показа́ла єси́;","Ра́дуйся, всім просящим у Теб'я́ ісціле́нія через іко́ну Твою́ істоча́єши;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 3","ps":["Си́лою Бо́жию і благода́тію Своє́ю зе́млю Брянськую осіни́вшая, Богоро́дице Ді́во, чрез явле́ніє іко́ни Своєя́ на Свени, похва́льноє возглаша́єм Ті пі́ніє і та́ко вопіє́м ко Го́споду: Аллилуя."]},{"h":"Ікос 3","ps":["Імі́я ві́ру ве́лію, благові́рний князь Рома́н, предизбранний сви́ше послужи́ти прославле́нію іко́ни Твоєя́ на Свени яви́вшейся, Влади́чице Преблага́я, той бо путь творя́ от гра́да Брянська к ріці́ Свени і дости́гнув мі́ста Тобо́ю ізбранного, ви́дів іко́ну Твою́ на дре́ві стоя́щу, к ней же, моле́бно припа́дая (со слеза́ми те́плими) си́це Тебі́ возглаша́єм:","Ра́дуйся, спасе́нія на́шего глави́зно;","Ра́дуйся, кня́зя Рома́на к прославле́нію іко́ни Твоєя́ ізбра́вшая;","Ра́дуйся, єму́ же істо́чник ісціле́ній указавшая;","Ра́дуйся, проше́ніє єго́ о принесе́нії іко́ни Твоєя́ іспо́лнившая;","Ра́дуйся, путь і́ноков на Свени задержавшая;","Ра́дуйся, кня́зя Рома́на к сему́ мі́сту призва́вшая;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 4","ps":["Бу́рю сомні́ній разгна́, си́ла Ви́шняго осіни́ кня́зя Рома́на устро́їти храм на мі́сті славного явле́нія іко́ни Твоєя́, і бисть воздви́гнуть храм Успе́нія ра́ди Твоєго́, Богома́ти, і в нем прославля́я Тя, на́шу Засту́пницю, Честні́йшую Херуви́м і Сла́внійшую без сравне́нія Серафи́м і Си́ну Твоєму́ вопіє́м: Аллилуя."]},{"h":"Ікос 4","ps":["Сли́ша об оби́лії чуде́с і ісціле́ній от святи́я іко́ни Твоєя́, Пренепоро́чная Ді́во, ізлива́ємих, недоуміва́єм пісносло́вити Тя по достоя́нію, кий бо язи́к челові́чеський возмо́жеть ізрещи́ вели́чія Твоя́, о Ди́вная Влади́чице, оба́че любо́вію Твоє́ю побіжда́єми си́це вопіє́м Ті:","Ра́дуйся, в селе́нія ра́йськия путеводи́тельнице;","Ра́дуйся, в по́двизіх на́ших укріпля́ющая;","Ра́дуйся, благо́є нача́ло і сла́вний коне́ць всіх подвиза́ющихся;","Ра́дуйся, святи́я ра́дости Боже́ственная Струє́;","Ра́дуйся, встречающих Тя с любо́вію, утіше́ніє;","Ра́дуйся, посіще́нієм Свої́м храм душе́вний устроя́ющая;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 5","ps":["Благода́тная си́ла, іко́ні Твоє́й дарова́нная, Пресвята́я Госпоже́ Богоро́дице, созива́єть ві́рних собо́ри пі́сньми духо́вними сла́вити Тя, Честні́йшую Херуви́мов і Серафи́мов, і́бо ро́ждши Єди́наго от Тро́йці, предстої́ши ни́ні пред Престо́лом Триіпоста́снаго Божества́, іді́же во́їнства го́рнія с тре́петом вопію́ть: Аллилуя."]},{"h":"Ікос 5","ps":["Ви́діша то́ки чуде́с на мі́сті явле́нія чу́дния іко́ни Твоєя́, Влади́чице Всеми́лостивая, на Свени би́вшая, князь Рома́н вку́пі с насе́льники гра́да Брянська со усе́рдієм мно́гим храм Бо́жий воздвиго́ша і та́ко созда́ша святу́ю оби́тель но́ву, в ней же немо́лчно воспіва́ють Ті благохвале́нія сицеви́я:","Ра́дуйся, зе́млю Брянськую в достоя́ніє Себе́ ізбра́вшая;","Ра́дуйся, я́ко на горі́ Свенстей духо́вний сад насади́вшая;","Ра́дуйся, я́ко та́мо живу́щим вся потре́бная пода́вшая;","Ра́дуйся, і́ноков от ми́ра гріхо́внаго собра́вшая;","Ра́дуйся, во оби́тель Свенськую їх приве́дшая;","Ра́дуйся, от враго́во ви́димих і неви́димих защища́ющая;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 6","ps":["Пропові́дуєть оби́тель Свенськая Твоє́ ма́тернеє пред Бо́гом предста́тельство, Преблагословленная Ді́во, і́бо Тебі́ даде́ся ве́лія благода́ть всеми́рнаго заступле́нія, тім же уми́льно на святу́ю Твою́ іко́ну взира́юще, в ско́рбіх і недугах врачевство́ оби́льно от нея́ почерпа́єм і вопіє́м глаго́ли хвале́бними на ней ізображе́нному вку́пі с Тобо́ю Си́ну Твоєму́ і Бо́гу: Аллилуя."]},{"h":"Ікос 6","ps":["Возсія́ нам бли́жнім і да́льним істо́чник чуде́с на Свени, Свята́я і Пречи́стая іко́на Твоя́, Цари́це і Влади́чице всея́ тва́рі, к ней же со усе́рдієм мно́гим притека́єм, приє́мля от нея́ да́ри неісче́тних Твої́х щедро́т і недосто́йнії стезе́ю отце́в на́ших ше́ствуя, с ві́рою і любо́вію припа́даєм к Твоє́й чудотво́рній іко́ні і із глубини́ серде́чния вопіє́м Ті та́ко:","Ра́дуйся, я́ко іко́на Твоя́ чу́дно на Свени яви́вшаяся, зе́млю Брянськую просвіти́ла єсть;","Ра́дуйся, я́ко гра́ду Брянську і преді́лам єго́ сви́ше наслі́діє спаси́тельноє дарова́ла єси́;","Ра́дуйся, я́ко іко́ною Твоє́ю оби́тель на Свени сві́тло красу́ється;","Ра́дуйся, я́ко іко́ні Твоє́й ца́ріє і святитиліє благогові́йно поклоня́ються;","Ра́дуйся, я́ко іко́ну Твою́ все монашество і всі правосла́внії ві́рно почита́ють;","Ра́дуйся, Бо́гом просвіще́нних украї́нців крі́пкоє заступле́ніє;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 7","ps":["Хотя́ яви́ти стра́нноє чу́до, Ді́во Богоро́дице, єгда́ воздвизашася це́рков ка́менна во оби́телі Свенстей і сво́ди церко́вния падо́ша, Ти бра́тію со ігу́меном Мартиніяном неврежде́нно сохрани́ла єси́, о Пречу́дная Влади́чице, да́руй же і нам, Госпоже́, Всеми́лостивая, ви́діти всегда́ чу́дний Покро́в Твой над на́ми недосто́йними і непреста́нно взива́ти к Си́ну Твоєму́: Аллилуя."]},{"h":"Ікос 7","ps":["Но́воє і пресла́вноє чу́до яви́ всіх чуде́с Творе́ць і всея́ тва́рі Влади́ко, єгда́ во хра́мі воздвизавшемся во оби́телі Твоє́й Свенстей, Пресвята́я Ді́во, попуще́нієм Бо́жиїм паде́ніє сводов бисть, сохраннії же і́ноці Твоєя́ оби́телі, Пречи́стая, позна́ша си́лу засту́пничества Твоєго́ і покровительства мі́ста сего́ із глубини́ серде́чния возопи́ша Ті сицева́я:","Ра́дуйся, облече́нная в сві́тлую оде́жду ми́лості і щедро́т;","Ра́дуйся, сія́ющая благода́тію і сла́вою преди́вних чуде́с;","Ра́дуйся, си́лою Твоє́ю боже́ственною, тече́ніє єсте́ственноє ізміня́ющая;","Ра́дуйся, Свої́м заступничеством безвре́менно поги́бнути не попустившая;","Ра́дуйся, неви́димо Свої́ми рука́ми от поги́белі лю́ди Твоя́ ісхитившая;","Ра́дуйся, ру́ку по́мощі Твоєя́ всім надеющимся на Тя простирающая;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 8","ps":["Стра́нноє заступле́ніє ви́дя, наро́д наш правосла́вний милостями Твої́ми, Богогмати, облагода́тствованний, немо́лчно сла́вить і́м'я Твоє́ і благогові́йно почита́єть Пречи́стаго ли́ка Твоєго́ ізображе́ніє, їм же ди́вная і пресла́вная чудеса́ нам яви́ла єси́; тім же си́нове украї́нськії іко́ну Твою́ в щит і огражде́ніє от враго́во ви́димих і неви́димих іму́ще і по́мощію Твоє́ю побіжда́юще супоста́ти, вопію́ть Царю́ Небесе́ і землі́: Аллилу́я."]},{"h":"Ікос 8","ps":["Во дні наше́ствія враг си́льних і вооруже́нних, чу́дную і благода́тную си́лу іко́ни Твоєя́ яви́ла єси́; я́ко забра́лом град окружила і полки́ вра́жії в бі́гство обрати́ла єси́; посіти́ і нас ми́лостію і щедро́тами Твої́ми, і я́ко отце́м на́шим по́мощ Твою́ ниспослаше, та́ко і нас не лиши́ заступле́нія Твоєго́, є́же по Бо́зі наде́жду крі́пку на Тя возлага́єм і зове́м Ті:","Ра́дуйся, жи́телей гра́да Брянська во ві́рі утверди́вшая;","Ра́дуйся, світ ти́хий і ра́достний от многочу́днаго Ли́ка Твоєго́ ізлива́ющая;","Ра́дуйся, сія́нієм Ли́ка Твоєго́ свята́го враго́в ослепившая і в бі́гство обрати́вшая;","Ра́дуйся, ско́рбния се́рдця і́ноков оби́телі отгнанієм враго́во возвесели́вшая;","Ра́дуйся, сі́тованіє їх на ликова́ніє приложившая;","Ра́дуйся, лише́нія їх щедродательно восполнившая;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 9","ps":["Вся́каго єстества́ а́нгельськаго чисті́йши су́щи, Влади́чице Богоро́дице, оби́тель ра́ди прише́ствія Твоєя́ іко́ни созда́нную, от нечисто́т гріхо́вних, близ поги́белі би́вшую, но покая́нієм очистившуюся, я́ко моли́твенниця о ро́ді христия́нстім от враг ізба́вила єси́, тща́щихся же разори́ти ю, посрами́ла єси́; тім же вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії недоуміва́ють воспі́ти по достоя́нію мно́жество чуде́с Твої́х, Влади́чице Богоро́дице, во оби́телі Свенстей Тобо́ю сотворе́нних; Ти же і при́сно не оста́ви нас недосто́йних чад Твої́х і сохрани́ оби́тель Твою́ (сію́), да вопіє́м Ті та́ко:","Ра́дуйся, зе́млю Брянськую прише́ствієм Свої́м освяти́вшая;","Ра́дуйся, по всей земле́ Брянськой лю́ди Твоя́ ізбра́вшая, їх же возлюби́ла єси́;","Ра́дуйся, в оби́телі Отця́ Небе́снаго їх вводя́щая;","Ра́дуйся, моли́тви на́ша в се́рдці Своє́м приє́млющая;","Ра́дуйся, в страда́ніях на́ших утіше́ніє;","Ра́дуйся, і́ноков і і́нокинь благоподвизающихся Всемо́щная Покрови́тельнице;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу свою́, святи́тель Іоа́нн при́йде в Твою́ оби́тель, Богоро́дице, і бисть зді іску́сен ігу́мен; чрез него́ же просла́вися іко́на Твоя́, Богоневі́сто, і просія́, па́че со́лнця; ні́ції же і́ноці клевету́ на него́ воздвиго́ша, но в ту́не бисть труд їх, он же храни́м Девой Богородицей, непреста́нно моля́ся Єй, прославля́ше Ю і Бо́гу вопія́ше: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рда і заступле́ніє яви́лася єси́, Влади́чице, но́вой оби́телі Твоє́й Свенстей, єгда́ же вразі́ облего́ша зе́млю Брянськую і мно́гажди разоря́ше дом Твой, Пречи́стая, Ти же, о Богома́ти, воздвизала єси́ із пе́пла і руїн оби́тель Твою́, іноци же вку́пі собра́вшеся благоро́дним се́рдцем і усти́ вопіяли к Ті такова́я:","Ра́дуйся, іко́ну Твою́ чу́дную нам дарова́вшая;","Ра́дуйся, оби́тель Свенськую є́ю же утешившая;","Ра́дуйся, прибіга́ющих к Тебі́ покро́в і огражде́ніє;","Ра́дуйся, оби́тель Свою́ наде́жно охраня́ющая;","Ра́дуйся, от супоста́тов іноплеме́нних ю ізбавля́ющая;","Ра́дуйся, все блага́я проше́нія на́ша ісполня́ющая;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прино́сять пред іко́ною Твоє́ю Свенською не то́кмо во гра́ді Ки́єве, но і в Брянскі, і в Москві́, і в Ярославлі і в друзих граді́х (і ве́сіх) землі́ на́шея правосла́вния лю́ди, призива́я Тя в по́мощ і заступле́ніє, вку́пі с преподо́бними Анто́нієм і Феодо́сієм Печерстими; получившия же от Тебе́ по́мощ і заступле́ніє, Богоро́дице, вопію́ть Си́ну Твоєму́ і Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́, просвіща́ющую всіх Тя призива́ющих, іму́ще мир християнстій Тебі́, Ді́во Богоро́дице, найпа́че же оби́тель Свенськая прославля́єть Тя, свою́ Покрови́тельницю, ю́же храни́ши мно́гая лі́та от нахожде́нія ага́рян і вся́ких враг, от єритик же і междуусо́бния бра́ні, і от нападе́нія іноплеме́нник; а́ще же іногда́ і попускала єси́ єй разоренной би́ти, гріх ра́ди на́ших, но па́ки єще́ благолі́пніє воздвизала єси́ ю, і дара́ми земни́ми ізобиловала насельников єя́; ті́мже і дара́ми благода́тними обогаща́єши вопію́щих Ті си́це:","Ра́дуйся, іко́ною Твоє́ю нас защища́ющая;","Ра́дуйся, в ско́рб'ях і болезнях нам помога́ющая;","Ра́дуйся, нерукотворе́нним о́бразом Твої́м нас покрива́ющая;","Ра́дуйся, сто́льний град Москву́ Свенською іко́ною посіти́вшая;","Ра́дуйся, і град Яросла́вль і другиє гра́ди землі́ Ру́ськия озари́вшая;","Ра́дуйся, іко́ною Твоє́ю ісціле́нія і ра́дость духо́вную нам подаю́щая;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственную, покро́в і заступле́ніє пода́ждь нам, Влади́чице на́ша і Ма́ти, припадающим пред іко́ною Свенською, воздви́гни нас от сна гріхо́внаго, сохрани́ оби́тель Твою́ (сію́) і нас недосто́йних чад Твої́х, сподо́би нас жи́тельствовати во огра́ді оби́телі Свенськия до конця́ дній на́ших і прославля́ти Тя і Си́на Твоєго́, Христа́ Бо́га на́шего, поя́ Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Твоя́ ми́лості і чудеса́, явле́нная во оби́телі Свенстей от літ дре́вніх і до ни́ні, поклоня́ємся пред о́бразом Твої́м і́мже спаса́єши нас, і всіх призива́ющих Тя в по́мощ і заступле́ніє і вопію́щих Ті такова́я:","Ра́дуйся, торжество́ ві́ри правосла́вния во оби́телі Свенстей іко́ною Твоє́ю утверди́вшая;","Ра́дуйся, се́рдця челові́чеськія любо́вію о Бо́зі распаляющая;","Ра́дуйся, оби́тель Свенськую іко́ною Твоє́ю прославля́ющая;","Ра́дуйся, іко́ни Твоя́, я́ко пропові́дници спасе́нія показа́вшая;","Ра́дуйся, с небе́сних висо́т на нас взирающая;","Ра́дуйся, на благи́я дія́нія нас наставля́ющая;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 13","ps":["О, Всепі́тая на́ша Ма́ти, Пресла́вная Влади́чице! Прийми́ сія́ похвали́ і моле́нія от скве́рних усте́н і нечи́стаго се́рдця на́ми возноси́мия, сохрани́ оби́тель Твою́ (сію́), гріхи́ на́шими оскверне́нную, собери́ нас расточе́нних і сподо́би в чи́ні А́нгельстім дости́гнути Небе́снаго Ца́рствія, і вку́пі с преподо́бними Анто́нієм і Феодо́сієм, і всі́ми уго́дники Бо́жиїми прославля́ти Тя ві́чно, на́шу Ма́тер і Си́на Твоєго́ і Бо́га і воспіва́ти Єму́ піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел Храни́тель внуши́ кня́зю Рома́ну, єгда́ той бисть во гра́ді Брянске, вспом'янути о чудесі́х от іко́ни Твоєя́, Влади́чице, во оби́телі Пече́рстій би́вших, да іспро́сить і́ноков Пече́рських отпусти́ти іко́ну чудотво́рную, писанную преподо́бним Алипієм, ісціле́нія ра́ди сліпоти́ своєя́ і возопи́ Ті та́ко:","Ра́дуйся, Всечестна́я на́ша Ма́ти;","Ра́дуйся, ди́вная на́ша Засту́пнице;","Ра́дуйся, Наде́ждо на́шего спасе́нія;","Ра́дуйся, гра́да Брянська Храни́тельнице;","Ра́дуйся, живу́щих в нем христия́н Покрови́тельнице;","Ра́дуйся, наді́ющихся на Тя, Руководи́тельнице;","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Кондак 1","ps":["Ізбра́нній от всіх родо́в Пресвяті́й Ді́ві Марі́ї Богоро́дице, я́ко воі́стину пло́тію ро́ждшей Ісу́са Христа́, Спа́са і Бо́га на́шего, Влади́чице всея́ Вселе́нния, ізбравшей втори́м земни́м жре́бієм страну́ на́шу Украї́нськую і оби́телі іноческиє чудотво́рними іко́нами прославившей, похва́льноє прино́сим пі́ніє; Ти же, о Всечестна́я на́ша Ма́ти і Засту́пниця, храни́ оби́тель Твою́ (сію́) і спаси́ всіх нас от враг ви́димих і неви́димих да зове́м Ті:","Ра́дуйся, Пресвята́я Богоро́дице Ді́во, Свенськая Похвало́ і на́ше при́сноє утіше́ніє."]},{"h":"Молитва","ps":["О, Пресвята́я і Пренепоро́чная Ді́во Богоро́дице, на́ша Све́нськая похвало́ і украше́ніє, держа́вний покро́ве свята́го мі́ста сего́, і́стинная Влади́чице ізбра́ннаго уде́ла Своєго́. Прийми́ нас, недосто́йних рабо́в Твої́х (імена́), убо́гоє моле́ніє, с ві́рою і любо́вію принося́щих пред чу́дним о́бразом Твої́м, да посіти́ши ми́лостивно гріхо́вноє житіє́ на́ше, просвіща́ющи єго́ сві́том покая́нія, осіни́ нас, обремене́нних скорбми́ мно́гими, Твоє́ю Небе́сною ра́достію, сподо́би нас при́сно сла́вити Тя в ми́рі і благоче́стії на мі́сті святі́м сем, да, без поро́ка преше́дше путь житія́ на́шего, по́мощію Твоє́ю дости́гнем ві́чнаго весе́лія во сві́тлості святи́х і преподо́бних оте́ць на́ших Ку́кши, Оле́га і Поліка́рпа Брянських і всіх уго́дников Бо́жиїх, і єди́ними усти́ і се́рдці воспої́м Тя с Предві́чним Си́ном Твої́м і Безнача́льним Єго́ Отце́м і Пресвяти́м, Животворя́щим, Всеблаги́м і Єдиносу́щним Єго́ Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь сві́тло торжеству́єть Све́нськая оби́тель; / і ра́дується явле́нієм о́браза Богома́тері; / Безмі́рний лик Пече́рських отце́в / с ни́ми же і ми непреста́нно вопіє́м: // ра́дуйся Благода́тная Све́нськая Похвало́."]},{"h":"Кондак, глас 4","ps":["Ді́ва днесь неви́димо предстої́ть в це́ркві / і с ли́ки Пече́рських отце́в мо́литься о нас, / благогові́йно велича́ющих Єя́ безмі́рную ми́лость к ро́ду на́шему, / я́вльшуюся в чу́дном о́бразі Єя́, // оби́тель Свенськую украша́ющем."]},{"h":"Величання","ps":["Велича́єм Тя Пресвята́я Ді́во, і почита́єм святу́ю іко́ну Твою́, ю́же от літ дре́вніх во оби́телей Свенстей просла́вила єси́."]},{"h":"Інше величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / і чтим о́браз Твой святи́й, / і́мже от нахожде́нія злові́рних / град Твой ізба́вила єси́."]},{"h":"Інше величання","ps":["Досто́йно єсть / велича́ти Тя, / Богоро́дице, / землі́ Ру́ськия Цари́цю Небе́сную, // Све́нський о́браз Твой в ней просла́вльшую."]}],"notes":[]},{"u":"Акафіст Пресвятій Богородиці перед іконою «Ченстоховська»","e":"Akathist to the Theotokos before her icon “Częstochowa”","secs":[{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Спаси́тельнице землі́ Ру́ськия, похва́льноє прино́сим пі́ніє. Ти же, Ма́ти царя́ Небесного от вся́кия ізба́ви напа́сти страну́ на́шу і от всіх скорбе́й і бід свободи́ зову́щих:","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Ікос 1","ps":["А́нгельський собо́р на Небесі́ немо́лчно воспіва́єть Тя, Влади́чице, і ми земноро́днії, притека́юще ко іко́ні Твоє́й чудотво́рній, святи́м Луко́ю писанной, вопіє́м Ті си́це:","Ра́дуйся, Ма́ти Сві́та Невече́рняго;","Ра́дуйся, Ду́ха Святага Оби́тель Свяще́нная;","Ра́дуйся, сві́тлоє благода́ті Позна́ніє;","Ра́дуйся, А́нгельських Сил Ликова́ніє;","Ра́дуйся, Купино́ неопа́льно горя́щая;","Ра́дуйся, Го́спода Сил ві́чно Зря́щая;","Ра́дуйся, Неув'яда́ємий Цві́те нетлі́нія;","Ра́дуйся, О́бразе Христо́ва Воскресе́нія;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 2","ps":["Ви́дяще благоче́стіє і ві́ру святи́я цари́ці Єле́ни, обретшей Крест Честни́й Госпо́день во Ієрусали́мі, дарова́ла єси́ єй, о, Богома́ти, і іко́ну Свою́, чрез ві́рних служи́телей Свої́х сохраненную от літ дре́вніх, да мо́ляться пред не́ю ви́ну лю́діє, пою́ще: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́вше свята́я цари́це Єле́но, я́ко о́браз сей єсть благослове́ніє Бо́жиє гра́ду ца́рствующему, поста́виша є та́мо в це́ркві собо́рній, іді́же мно́зі от него́ ісціле́нія прия́ша, пою́ще Ма́тері Бо́жієй похвали́ сицеви́я:","Ра́дуйся, Ча́ше, че́рплющая ві́чную ра́дость;","Ра́дуйся, Істо́чниче, ізливающий неізрече́нную сла́дость;","Ра́дуйся, Черто́же Рая́ красні́йшій;","Ра́дуйся, Вертогра́ді Христо́в сла́внійший;","Ра́дуйся, Ду́ха Свята́го Селе́ніє;","Ра́дуйся, враго́в Бо́жієй Пра́вди Посрамле́ніє;","Ра́дуйся, духо́вною ра́достію нас Утіша́ющая;","Ра́дуйся, с ві́рою Тя призива́ющих, не посрамля́ющая;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго храня́ше іко́ну Твою́, Богома́ти, во дні єресе́й от поруга́нія, і от лю́тих іконобо́рцев погубле́нія, і от рук ва́рварських пліне́нія, я́ко Самі́й Ті би́ти Хранительницей христия́ном, пою́щим Си́ну Твоєму́ і Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще сокро́вище святи́я іко́ни Твоєя́, святі́ї Кири́лле і Мефо́діє просвіти́ша землі́ слав'янсткії сві́том ві́ри христия́нський, да уві́дять язи́чници Бо́га і́стиннаго і просла́в'ять Ма́тер Бо́жию та́ко:","Ра́дуйся, Держа́вная на́ша строїтельнице;","Ра́дуйся, Всеси́льная Побіди́тельнице;","Ра́дуйся, Свободи́тельнице плі́нних;","Ра́дуйся, Покрови́тельнице обремене́нних;","Ра́дуйся, Хода́тайця за всю Вселеную;","Ра́дуйся, Да́рующая жизнь нетлі́нную;","Ра́дуйся, ідольського служе́нія Ізбавле́ніє;","Ра́дуйся, с Бо́гом на́ше примире́ніє;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 4","ps":["В бурния дні смуть і нестроє́ній, спаса́ше іко́на Твоя́, Пресвята́я Ді́во, всіх притека́ющих к ней і обріта́ху всі от Тебе́ покро́в і заступле́ніє вопію́ще благода́рними се́рдці: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще і зря́ще чудеса́, явля́ємия от іко́ни Твоєя́, Пресвята́я Богоро́дице, князне ру́сстії храниша от ро́да в род святи́ню сію́, моля́щеся пред не́ю умиле́нно:","Ра́дуйся, А́гнця і Па́стиря Ма́ти Нетлі́нная;","Ра́дуйся, Ді́во преблагослове́нная;","Ра́дуйся, Ма́тернюю любо́в нам явля́ющая;","Ра́дуйся, ри́зою честно́ю всіх покрива́ющая;","Ра́дуйся, благ ві́чних Наде́ждо ві́рная;","Ра́дуйся, Моли́твеннице на́ша усе́рдная;","Ра́дуйся, Судії́ Всеправедного Умоле́ніє;","Ра́дуйся, гріхо́во всіх на́ших Проще́ніє;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 5","ps":["Боготечне ше́ствуя ізо гра́да во град Русі́ Червонния іко́на Твоя́, Пресвята́я Богоро́дице, повсю́ду явля́ше сла́ву твою́ і Си́на Твоєго́, Христа́ Бо́га на́шего, вопію́щим Єму́ лю́дем: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша житиліє гра́да Белза гро́зноє нападе́ніє ага́рян, ізнесо́ша іко́ну Твою́ чудотво́рную, Пресвята́я Ді́во, на сто́гни гра́да своєго́ і моля́щеся с ві́рою Ті о заступле́нії, Ти же ускори́ла єси́ тогда́ на по́мощ їм, да зову́ть Ті:","Ра́дуйся, ми́лости Свої́ на нас ізлива́ющая;","Ра́дуйся, Влади́ку Умилостивля́ющая;","Ра́дуйся, іко́ною Твоє́ю от бід Сохране́ніє;","Ра́дуйся, христия́н правосла́вних Спасе́ніє;","Ра́дуйся, зли́є діла́ Запина́ющая;","Ра́дуйся, милосе́рдіє нам Явля́ющая;","Ра́дуйся, страни́ Украї́нськия Утіше́ніє;","Ра́дуйся, Це́ркві Христо́вой свяще́нноє Украше́ніє;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 6","ps":["Пропові́даху всю́ду лю́діє о ди́внім заступле́нії Твоє́м, я́ко єгда́ нечести́вії татарове стріло́ю уязви́ша на іко́ні ізображе́ніє Пречи́стаго Ли́ка Твоєго́, тогда́ внеза́пу тьма і помраче́ніє на́йде нань і друг дру́га убива́ху ти́я, біжа́ще всп'ять, ві́рнії же зря́ще чу́до сіє́, поя́ху Го́споду хвале́ніє: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ благода́ть і мрак ісчезе́ і возви́сися рог люде́й християнстких, я́ко Ти, Богома́ти, укреплявши ві́ру правосла́вную, чудесьми і зна́меньми от святи́я іко́ни Твоєя́ явля́ємими человецем, молящимся та́ко:","Ра́дуйся, от наше́ствія іноплеме́нников преди́вно ізбавля́ющая;","Ра́дуйся, от плі́на і пораже́нія спаса́ющая;","Ра́дуйся, агарянською стріло́ю пронзенная;","Ра́дуйся, Ма́ти і Ді́во Неізрече́нная;","Ра́дуйся, молящимся то́ки чуде́с істоча́ющая;","Ра́дуйся, печа́ль на ра́дость прелагающая;","Ра́дуйся, ключу́ Ца́рствія Небе́снаго;","Ра́дуйся, Помо́щнице житія́ честна́го;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 7","ps":["Хотя́ще оста́вити іко́ну Свою́ во гра́ді Ченстохове, сделала єси́ возок с іко́ною недвижимим, єгда́ неция злочестивія тща́хуся ісхити́ти ю із гра́да, христия́не же обрі́тше і о́браз Твой неукраденним, возопіяше Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до, на устраше́ніє нечестивих яви́ла єси́ тогда́ от о́браза Твоєго́ Пречи́стая, поразивши сліпото́ю і ско́рою сме́ртію богохульников, і́же іко́ну Твою́ мече́м уязви́ша і на три ча́сти разсіко́ша, ми же іко́ну сію́ чту́ще вопіє́м Ті:","Ра́дуйся, Ма́тер Бо́жия закланная;","Ра́дуйся, от нача́ла віко́в Предизбранная;","Ра́дуйся, Путеводи́тельнице к Не́бу пе́рвійшая;","Ра́дуйся, всіх А́нгельських Сил честні́йшая;","Ра́дуйся, милосе́рдая всіх Ма́ти;","Ра́дуйся, неісчерпа́ємий Сосу́д благода́ті;","Ра́дуйся, просящим по́мощ явля́ющая;","Ра́дуйся, до́броє житіє́ устроя́ющая;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 8","ps":["Стра́нно бисть войську свейському ви́діти, я́ко непобіди́моє досе́лі гро́зноє во́їнство їх побеждено бисть внеза́пу близ гра́да Ченсто́хова, іді́же чудотво́рная іко́на Богома́тері стоя́ше, пред не́ю же лю́діє не престава́ху пі́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім молящимся і притекающим ко іко́ні Твоє́й Ско́рая Помо́щнице явля́єшися, Пресвята́я Ді́во, я́коже дре́вле, та́ко і ни́ні заступавши і охранявши почита́ющих Тя, прийми́ і сія́ похвали́ от нас:","Ра́дуйся, Сові́та неізрече́ннаго Таї́ннице;","Ра́дуйся, благода́ті Бо́жієй Сокровищнице;","Ра́дуйся, іноплеме́нних ра́тей Одолі́ніє;","Ра́дуйся, от убіє́нія і разоре́нія Спасе́ніє;","Ра́дуйся, го́рняго і до́льняго ми́ра Всецари́це;","Ра́дуйся, вся́чеських благ пода́тельнице;","Ра́дуйся, от враго́в і бід ізбавле́ніє;","Ра́дуйся, непреста́нноє челові́к удивле́ніє;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 9","ps":["Вся́кий пол і во́зраст возвесели́ся зря́ще, єгда́ цар ру́ський Петр моле́бноє пі́ніє поя́ше перед іко́ною Богома́тері, пам'яту́юще, я́ко о́браз сей бисть ні́когда достоя́ніє ца́рськоє і князе́й ру́ських, восхваляше пред ни́ми Го́спода і Ма́тер Єго́ пі́снію: Аллилу́я."]},{"h":"Ікос 9","ps":["Весь мир христия́нський покривавши омофо́ром ми́лости Своєя́, на по́мощ ско́ро к нам притекавши, ку́пно со уго́дники Бо́жії і святи́телем Никола́єм за нас перед Бо́гом хода́тайствуєши, воньми́ і ни́ні гла́су моле́ній на́ших перед о́бразом Твої́м:","Ра́дуйся, сві́том і́стини нас Озаря́ющая;","Ра́дуйся, ру́ці Твої́ за ни моляшася Простирающая;","Ра́дуйся, Бо́га і челові́ка Соєдини́вшая;","Ра́дуйся, сме́ртноє єстество́ бессмертієм Просвіти́вшая;","Ра́дуйся, ві́рних душ Услажде́ніє;","Ра́дуйся, душепа́губних діл Удале́ніє;","Ра́дуйся, благочести́вих христия́н Окормительнице;","Ра́дуйся, смиренномудрих блага́я Вседержительнице;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ род челові́ч, Богома́ти, от тьми неві́рія і заблужде́нія, яви́ ми́ру світ ві́ри Правосла́вния і то́кмо во́їнству ру́ському подаде́ одолі́ти крі́пость, іді́же іко́на Єя́ чудотво́рная стоя́ше, пред не́ю же воспі́ благода́рственно: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ нера́туєма і огражде́ніє тве́рдоє, Ти єси́ ві́рним лю́дем ру́ським почита́ющим Тя, о, Бо́жия Ма́ти, я́ко во мно́зіх списках со іко́ни Ченстоховськия являвши благоволе́ніє Своє́, проси́моє подає́ши і гнів Бо́жий отвращавши от пою́щих Ті:","Ра́дуйся, Держа́ву Украї́нськую Устроя́ющая;","Ра́дуйся, под но́зі Царя́ Православного вся Покаряющая;","Ра́дуйся, Облича́ющая уче́нія душевре́дния;","Ра́дуйся, Призревающая на моли́тви смире́нния;","Ра́дуйся, в печа́ліх і біда́х Утіше́ніє;","Ра́дуйся, от нечаянниє сме́рті Спасе́ніє;","Ра́дуйся, Да́рующая Побі́ди ві́рним;","Ра́дуйся, Вінча́ющая вінце́м нетлі́нним;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 11","ps":["Пі́ніє воспіва́єм і хвалу́ прино́сим Ті, о, Пресвята́я Ді́во, мо́лимся пред іко́ною Твоє́ю, на ней же зрим я́зви, рука́ми нечести́вих челові́к нанесе́нния, от на́ших же прегріше́ній незаживляємия, к Бо́гу взива́єм, іму́ще Тя о нас Хода́таїцю: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоявле́нная іко́на Твоя́ сія́єть чудеси́, да́же і додне́сь, явля́я нам ми́лость Твою́, я́ко мно́гажди тща́хуся лю́діє сокри́ти ва́пи разли́чними уязвле́ніє Пречи́стаго Ли́ка Твоєго́, на сей іко́ні живописанного, но всу́є труди́шася ізографи, я́ко па́ки проступаху я́зі, ї́хже ми гріхми́ на́шими і беззако́ньми наносим Ті, но отпусти́ нам вся, Ді́во, і поми́луй зову́щия:","Ра́дуйся, крі́пкоє Ві́ри Забра́ло;","Ра́дуйся, чуде́с Христо́вих Нача́ло;","Ра́дуйся, Врат Ра́йських Отверзе́ніє;","Ра́дуйся, та́йни Бо́жієй всеси́льноє Проявле́ніє:","Ра́дуйся, прия́тноє моли́тви Кади́ло;","Ра́дуйся, носящего вся Носи́ло;","Ра́дуйся, людськи́ми гріхми́ Істерзанная;","Ра́дуйся, в любві́ Бо́жієй Утвержде́нная;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 12","ps":["Благода́тію покри́й нас, о, Пресвята́я Ді́во, ісходя́щею от ди́вния іко́ни Твоєя́, предста́тельством Твої́м спаси́ і поми́луй страну́ Ру́ськую, в ней же во дні дре́внія чудеси́ мно́гими просія́ла єси́ і яви́ нам, молящимся пред о́бразом Твої́м, чу́до спасе́нія, пою́щим Си́ну Твоєму́ і Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще пі́ніє похва́льноє усти́ недосто́йними, упова́єм на ми́лость Бо́жию і Твоє́, о, Богома́ти, заступле́ніє і хода́тайство за нас, грі́шних, пред Го́сподем, я́ко да да́руєть держа́ві ру́сстій на супоста́ти одолі́ніє, от іноплеме́нних пога́н свобожде́ніє, царя́ православного во охране́ніє і к Ца́рствію Небе́сному путевожденіє, і ви́ну бу́ди с на́ми, зовущим Ті:","Ра́дуйся, огне́м Боже́ственним Всепросвещающая;","Ра́дуйся, мрак гріха́ Отгоня́ющая;","Ра́дуйся, же́стокости на́ших серде́ць Ум'ягче́ніє;","Ра́дуйся, заблудших на путь спасе́нія Возвраще́ніє;","Ра́дуйся, Стіно́ Неруши́мая;","Ра́дуйся, Побі́до Непобіди́мая;","Ра́дуйся, Небесі́ і землі́ Украше́ніє;","Ра́дуйся, Наде́ждо на́шего Воскресе́нія;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 13","ps":["О, Всепі́тая Ма́ти, ро́ждшая всіх святи́х святі́йшеє Сло́во, при́зри ни́ні на Ца́рство Твоє́ земно́є і умоли́ Го́спода Вседержи́теля, да не вни́деть в суд с на́ми, но да пода́сть нам гріхо́в оставле́ніє, от і́га бісо́вськаго свобожде́ніє і Свято́й Русі́ Воскресе́ніє, вопію́щим Бо́гу ві́рою: Аллилу́я. Аллилу́я. Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський собо́р на Небесі́ немо́лчно воспіва́єть Тя, Влади́чице, і ми земноро́днії, притека́юще ко іко́ні Твоє́й чудотво́рній, святи́м Луко́ю писанной, вопіє́м Ті си́це:","Ра́дуйся, Ма́ти Сві́та Невече́рняго;","Ра́дуйся, Ду́ха Святага Оби́тель Свяще́нная;","Ра́дуйся, сві́тлоє благода́ті Позна́ніє;","Ра́дуйся, А́нгельських Сил Ликова́ніє;","Ра́дуйся, Купино́ неопа́льно горя́щая;","Ра́дуйся, Го́спода Сил ві́чно Зря́щая;","Ра́дуйся, Неув'яда́ємий Цві́те нетлі́нія;","Ра́дуйся, О́бразе Христо́ва Воскресе́нія;","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Кондак 1","ps":["Взбра́нной Воєво́ді, Спаси́тельнице землі́ Ру́ськия, похва́льноє прино́сим пі́ніє. Ти же, Ма́ти царя́ Небесного от вся́кия ізба́ви напа́сти страну́ на́шу і от всіх скорбе́й і бід свободи́ зову́щих:","Ра́дуйся, Засту́пнице Усе́рдная, ізба́ви нас от всякого зла і сотвори́ чу́до спасе́нія."]},{"h":"Молитва","ps":["О, Всеми́лостивая Госпоже́, Цари́це Богоро́дице, от всіх родо́в ізбра́нная і всі́ми ро́ди небе́сними і земни́ми ублажа́ємая! Воззри́ ми́лостивно на предстоя́щия пред свято́ю іко́ною Твоє́ю лю́ди сія́, усе́рдно моля́щієся Тебі́ і сотвори́ предста́тельством Твої́м і заступле́нієм у Си́на Твоєго́ і Бо́га на́шего, да нікто́же оти́деть от мі́ста сего́ упова́нія своєго́ тощ і посра́млен в наде́жді своє́й; но да при́йметь ки́йждо от Тебе́ вся по благо́му ізволе́нію се́рдця своєго́, по ну́жди і потре́бі своє́й, во спасе́ніє душі́ і во здра́віє ті́лу. Моли́, Милосе́рдая Влади́чице, пренебе́снаго Бо́га, да при́сно це́рков свою́ святу́ю соблюде́ть, ви́шнім свої́м благослове́нієм архієре́єв на́ших правосла́вних укріпи́ть, ми́ром огради́ть і святі́й своє́й це́ркві ці́лих, здра́вих, честни́х, долгоде́нствующих і пра́во пра́в'ящих сло́во своєя́ і́стини да́руєть, от всіх же ви́димих і неви́димих враго́в со всі́ми правосла́вними христия́ни ми́лостивно ізба́вить і во Правосла́вії і тве́рдій ві́рі до конця́ віко́в неотсту́пно і неізмі́нно сохрани́ть. Призира́й благосе́рдієм, Всепі́тая, і призрі́нієм ми́лостиваго Твоєго́ заступле́нія на все ца́рство на́ше Всеукраї́нськоє, ца́рствующия гра́ди на́ша, град сей і свято́й храм сей, і ізле́й на ня бога́тия Твоя́ ми́лості, Ти бо єси́ всеси́льная Помо́щниця і Засту́пниця всіх нас. Приклони́ся к моли́твам і всіх раб Твої́х, притека́ющих зді ко святі́й іко́ні Твоє́й сей, усли́ши воздиха́нія і гла́си, і́ми же раби́ Твої́ мо́ляться во святі́м хра́мі сем. А́ще же і інові́рний, і іноплеме́нник, ідя́ і проходя́ зді, помо́литься, усли́ши, чадолюби́вая Госпоже́, і сего́ человіколю́біє і ми́лостивно соді́лай, я́же к по́мощі єму́ і ко спасе́нію. Ожесточе́нния же і разсі́янния се́рдці свої́ми во страна́х на́ших на путь і́стини наста́ви. Отпа́дшия от благочести́вия ві́ри обрати́ і па́ки сопричти́ святі́й Твоє́й Правосла́вній кафоли́чеськой це́ркві. В семе́йствах люде́й всіх і во бра́тії на́шей мир огради́ і соблюди́, в ю́них бра́тство і смиренному́дріє утверди́, ста́рость поддержи́, о́трочество наста́ви, му́жество умудри́, си́рия і вдови́ці заступи́, утісне́нния і в ско́рбіх су́щия уті́ши і охрани́, младе́нці воспита́й, боля́щия уврачу́й, пліне́нния свободи́, огражда́я ни ви́ну от вся́каго зла бла́гостію Твоє́ю і уті́ши ми́лостивним Твої́м посіще́нієм і всіх благоде́ющих нам. Да́руй же, Блага́я, землі́ плодоно́сіє, возду́ху благорастворе́ніє і вся, я́же на по́льзу на́шу, да́ри благовре́менния і благопотре́бния, всемо́щним свої́м предста́тельством пред Всесвято́ю Живонача́льною Тро́йцею, ку́пно со святи́ми ізбра́нними угодниками Єя́ Кири́ллом і Мефо́дієм. Пре́жде отше́дшия отці́ і ма́тері, бра́тія і сестри́ на́ша, і вся от літ дре́вніх припа́давшия ко святі́й іко́ні Твоє́й сей упоко́й в селе́ніях святи́х, в мі́сті сві́тлі, в мі́сті зла́чні, в мі́сті поко́йні, іді́же ність печа́ль і воздиха́ніє. Єгда́ же приспі́єть і на́ше от житія́ сего́ отше́ствіє і к ві́чной жи́зні преселе́ніє, предста́ни нам, Преблагослове́нная Ді́во, і да́руй христия́нськую кончи́ну живота́ на́шего безболі́зненну, непости́дну, ми́рну і Святи́х Тайн прича́стну, да і в бу́дущем ві́ці сподо́бимся всі, ку́пно со всі́ми святи́ми, безконе́чния блаже́нния жи́зні во ца́рствії возлю́бленнаго Си́на Твоєго́, Го́спода і Спа́са на́шего Ісу́са Христа́, Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Непобіди́мая Побі́до, Влади́чице Ченстохо́вськая: дре́вняго і́же о нас благоволе́нія Самозри́тельнице, бу́дущаго спасе́нія Храни́тельнице: покая́нієм соді́лай ни но́вия но́вому Царю́."]},{"h":"Величання","ps":["Велича́єм Тя, / Пресвята́я Ді́во, / Богоізбра́нная Отрокови́це, / і чтим о́браз Твой святи́й, / і́мже то́чиши ісціле́нія // всім с ві́рою притека́ющим."]}],"notes":[]}];
export default D;
